 'theregister', 'https://www.theregister.com/2024/04/03/taiwan_earthquake_tech_impact/', '2024-04-03 08:00:00', 0,
 -1.648, -2.830,
 'A magnitude 7.4 earthquake struck off Taiwan''s east coast and TSMC evacuated some fabs as a precaution. The company later said there was no damage to its critical tools, including its EUV lithography tools.'),

(609, 'TSM', 'supply_chain',
 'TSMC pauses production after strong earthquake hits Taiwan',
 'TSMC paused work at plants after a magnitude 6.4 quake. It said structural inspections were completed at all sites and operations were gradually resuming, though tools may need recalibration.',
 'theregister', 'https://www.theregister.com/2025/01/21/taiwan_earthquake_tsmc/', '2025-01-21 08:00:00', 0,
 2.058, 1.445,
 'TSMC paused work at plants after a magnitude 6.4 quake. It said structural inspections were completed at all sites and operations were gradually resuming, though tools may need recalibration.'),

(610, 'TSM', 'supply_chain',
 'January earthquake shook $165M off TSMC’s revenue forecast',
 'TSMC warned that the January earthquake would cost it revenue, which The Register put at roughly 165 million dollars. The disruption was small relative to its overall production.',
 'theregister', 'https://www.theregister.com/2025/02/11/tsmc_taiwan_earthquake_financial_impact/', '2025-02-11 08:00:00', 0,
 -1.131, 0.109,
 'TSMC warned that the January earthquake would cost it revenue, which The Register put at roughly 165 million dollars. The disruption was small relative to its overall production.'),

(611, 'ASML', 'supply_chain',
 'ASML ships another high NA EUV lithography machine to mystery client',
 'ASML shipped its second High-NA EUV lithography machine to an unnamed customer. High-NA scanners are reported to cost roughly 300 to 400 million dollars each.',
 'theregister', 'https://www.theregister.com/2024/04/17/asml_ships_another_high_na/', '2024-04-17 08:00:00', 0,
 -2.047, -1.773,
 'ASML shipped its second High-NA EUV lithography machine to an unnamed customer. High-NA scanners are reported to cost roughly 300 to 400 million dollars each.'),

(612, 'ASML', 'supply_chain',
 'ASML share plunge wipes over $50 billion off Dutch chip giant''s value',
 'ASML published its third-quarter results a day early with weak forecasts. It guided 2025 net sales of 30 to 35 billion euros, in the lower half of its prior range, and bookings of 2.6 billion euros against a 5.6 billion euro consensus. The headline refers to a 12 percent same-day drop, but this question is about the following session.',
 'cnbc', 'https://www.cnbc.com/2024/10/15/chip-firm-asml-shares-fall-12percent-after-earnings-released-earlier-than-expected.html', '2024-10-15 08:00:00', 0,
 -6.422, 0.000,
 'ASML published its third-quarter results a day early with weak forecasts. It guided 2025 net sales of 30 to 35 billion euros, in the lower half of its prior range, and bookings of 2.6 billion euros against a 5.6 billion euro consensus. The headline refers to a 12 percent same-day drop, but this question is about the following session.'),

(613, 'ASML', 'supply_chain',
 'ASML faces turbulence amid stock drop, customer delays',
 'ASML''s stock fell after weak orders, which analysts linked to a small number of customers including Intel and Samsung. China was expected to be around 20 percent of ASML''s revenue in 2025.',
 'theregister', 'https://www.theregister.com/2024/10/21/asml_setbacks/', '2024-10-21 08:00:00', 0,
 0.954, -0.371,
 'ASML''s stock fell after weak orders, which analysts linked to a small number of customers including Intel and Samsung. China was expected to be around 20 percent of ASML''s revenue in 2025.'),

(614, 'INTC', 'supply_chain',
 'Intel delays Ohio fab build, blames semiconductor slowdown',
 'Intel postponed the completion of its planned Ohio site to late 2026. It blamed weak semiconductor market conditions and delays in receiving CHIPS Act subsidy money.',
 'theregister', 'https://www.theregister.com/2024/02/02/intel_pushes_back_ohio_fab/', '2024-02-02 08:00:00', 0,
 0.399, 1.366,
 'Intel postponed the completion of its planned Ohio site to late 2026. It blamed weak semiconductor market conditions and delays in receiving CHIPS Act subsidy money.'),

(615, 'INTC', 'supply_chain',
 'Intel slows its roll on $28B Ohio fab expansion, pushing production to 2030s',
 'Intel said the first Ohio fab would start production between 2030 and 2031, with the second about a year later. The company slowed construction to match capital spending with market demand.',
 'theregister', 'https://www.theregister.com/2025/02/28/intel_delay_ohio/', '2025-02-28 08:00:00', 0,
 -4.172, -3.534,
 'Intel said the first Ohio fab would start production between 2030 and 2031, with the second about a year later. The company slowed construction to match capital spending with market demand.'),

(616, 'INTC', 'supply_chain',
 'Intel puts consumer chip production on back burner as datacenters make a run on Xeons',
 'Intel''s CFO acknowledged misjudging datacenter demand, leading to a capacity crunch on Intel 7. Capacity was shifted to server Xeon parts over client chips, so low-end PC processors could become harder to find.',
 'theregister', 'https://www.theregister.com/on-prem/2026/01/23/intel-prioritizes-xeons-over-client-chips-to-meet-ai-demand/4961785', '2026-01-23 08:00:00', 0,
 -5.724, -0.476,
 'Intel''s CFO acknowledged misjudging datacenter demand, leading to a capacity crunch on Intel 7. Capacity was shifted to server Xeon parts over client chips, so low-end PC processors could become harder to find.'),

(617, 'INTC', 'supply_chain',
 'AMD climbs in desktop and server CPUs while Intel battles supply squeeze',
 'AMD gained CPU market share in the fourth quarter of 2025. The Register tied this to Intel''s supply constraints on client processors after Intel moved manufacturing capacity toward server chips.',
 'theregister', 'https://www.theregister.com/2026/02/13/amd_intel_market_share/', '2026-02-13 08:00:00', 0,
 -1.304, -0.158,
 'AMD gained CPU market share in the fourth quarter of 2025. The Register tied this to Intel''s supply constraints on client processors after Intel moved manufacturing capacity toward server chips.'),

(618, 'INTC', 'supply_chain',
 'Intel begins production of most-advanced chip, inching closer to possible Apple deal',
 'Intel moved its enhanced 18A-P process into early production. The Wall Street Journal had reported a preliminary deal for Intel to make some Apple chips, which Intel had not confirmed.',
 'cnbc', 'https://www.cnbc.com/2026/06/16/intel-begins-production-of-18a-p-inches-closer-to-possible-apple-deal.html', '2026-06-16 08:00:00', 0,
 3.460, 1.436,
 'Intel moved its enhanced 18A-P process into early production. The Wall Street Journal had reported a preliminary deal for Intel to make some Apple chips, which Intel had not confirmed.'),

(619, 'MU', 'supply_chain',
 'Micron bounces back as AI drives up memory prices',
 'Micron returned to profit as AI demand lifted memory prices. Management said HBM was sold out for calendar 2024, with the overwhelming majority of 2025 supply already allocated.',
 'theregister', 'https://www.theregister.com/on-prem/2024/03/21/micron-bounces-back-to-profit-as-ai-hikes-up-memory-prices/1289450', '2024-03-21 08:00:00', 0,
 0.328, 0.120,
 'Micron returned to profit as AI demand lifted memory prices. Management said HBM was sold out for calendar 2024, with the overwhelming majority of 2025 supply already allocated.'),

(620, 'MU', 'supply_chain',
 'Micron close to selling all the high-bandwidth memory it will make in 2026',
 'Micron reported fiscal fourth-quarter 2025 results and said its HBM supply for next year was nearly fully committed. It said it had pricing agreements for most of its HBM3E supply in calendar 2026.',
 'theregister', 'https://www.theregister.com/2025/09/24/micron_q4_2025/', '2025-09-24 08:00:00', 0,
 -3.018, -0.320,
 'Micron reported fiscal fourth-quarter 2025 results and said its HBM supply for next year was nearly fully committed. It said it had pricing agreements for most of its HBM3E supply in calendar 2026.'),

(621, 'MU', 'supply_chain',
 'AI memory is sold out, causing an unprecedented surge in prices',
 'HBM consumes so much DRAM capacity that supply for consumer electronics is being depleted. Memory makers have shifted output toward AI-focused HBM, driving a broad price surge.',
 'cnbc', 'https://www.cnbc.com/2026/01/10/micron-ai-memory-shortage-hbm-nvidia-samsung.html', '2026-01-10 08:00:00', 0,
 0.226, 0.478,
 'HBM consumes so much DRAM capacity that supply for consumer electronics is being depleted. Memory makers have shifted output toward AI-focused HBM, driving a broad price surge.'),

(622, 'MU', 'supply_chain',
 'Micron CEO says it can''t deliver enough memory to key customers after blowout earnings',
