 'Micron''s CEO said it can supply only about 50 to two-thirds of key customers'' mid-term requirements. Shares fell about 3 percent on the same day despite revenue nearly tripling, and the following session is the focus of this question.'),

(623, 'SSNLF', 'supply_chain',
 'Samsung Electronics to make ''meaningful'' cut to chip production in effort to support prices',
 'Samsung said it would make a meaningful cut to chip production as a chip glut hit prices. It guided first-quarter operating profit down about 96 percent after pandemic-era stockpiling left customers with excess inventory. The move shown is for Samsung''s Korea-listed shares.',
 'cnbc', 'https://www.cnbc.com/2023/04/07/samsung-electronics-says-first-quarter-profit-likely-plunged-96percent-as-chip-glut-slashes-prices.html', '2023-04-07 08:00:00', 0,
 1.077, 1.766,
 'Samsung said it would make a meaningful cut to chip production as a chip glut hit prices. It guided first-quarter operating profit down about 96 percent after pandemic-era stockpiling left customers with excess inventory. The move shown is for Samsung''s Korea-listed shares.'),

(624, 'SSNLF', 'supply_chain',
 'Samsung extends cut in memory chip production, will focus on high-end AI chips instead',
 'Samsung extended memory production cuts to accelerate inventory normalization after a memory-unit operating loss of roughly 4.36 trillion won in the second quarter of 2023. It said it would focus on high-end products such as HBM. The move shown is for Samsung''s Korea-listed shares.',
 'techcrunch', 'https://techcrunch.com/2023/07/27/samsung-extends-cut-in-memory-chip-production-will-focus-on-high-end-ai-chips-instead/', '2023-07-27 08:00:00', 0,
 -1.534, 2.183,
 'Samsung extended memory production cuts to accelerate inventory normalization after a memory-unit operating loss of roughly 4.36 trillion won in the second quarter of 2023. It said it would focus on high-end products such as HBM. The move shown is for Samsung''s Korea-listed shares.'),

(625, 'SSNLF', 'supply_chain',
 'Samsung''s HBM chips reportedly fail Nvidia tests due to heat and power consumption woes',
 'Reuters reported that Samsung''s 8-layer and 12-layer HBM3E chips failed an April Nvidia test because of heat and power consumption problems. Samsung had been trying to pass Nvidia''s HBM3 and HBM3E tests since 2023. The move shown is for Samsung''s Korea-listed shares.',
 'cnbc', 'https://www.cnbc.com/2024/05/24/samsungs-hbm-chips-are-failing-nvidia-tests-reuters.html', '2024-05-24 08:00:00', 0,
 1.713, 1.689,
 'Reuters reported that Samsung''s 8-layer and 12-layer HBM3E chips failed an April Nvidia test because of heat and power consumption problems. Samsung had been trying to pass Nvidia''s HBM3 and HBM3E tests since 2023. The move shown is for Samsung''s Korea-listed shares.'),

(626, 'SSNLF', 'supply_chain',
 'Samsung''s 8-layer HBM3E chips clear Nvidia''s tests for use, Reuters reports',
 'Samsung''s 8-layer HBM3E chips passed Nvidia''s tests, while the 12-layer version had not yet. Supply to Nvidia was expected to start in the fourth quarter of 2024. The move shown is for Samsung''s Korea-listed shares.',
 'cnbc', 'https://www.cnbc.com/2024/08/07/samsungs-8-layer-hbm3e-chips-clear-nvidias-tests-for-use-reuters-reports.html', '2024-08-07 08:00:00', 0,
 -1.740, 6.899,
 'Samsung''s 8-layer HBM3E chips passed Nvidia''s tests, while the 12-layer version had not yet. Supply to Nvidia was expected to start in the fourth quarter of 2024. The move shown is for Samsung''s Korea-listed shares.'),

(627, 'SSNLF', 'supply_chain',
 'Samsung expects second-quarter profits to more than halve as it struggles to capture AI demand',
