-- ---- Quiz items: 11 hand-written samples (ids 1-11, mixing real_news and
-- concept types) + 148 imported from Semiconductor_News (1).xlsx (ids 12-159,
-- all real_news; question/option/answer text comes from the spreadsheet) ----
-- NOTE: correct_option is deliberately spread across a/b/c (not clustered on
-- 'a') so a student can't pattern-guess the answer key. Keep this spread when
-- more content is added -- don't always put the correct choice first.
--
-- quiz.php should pull AT MOST 5 items per category at random, e.g.:
--   SELECT * FROM quiz_items WHERE category = ? ORDER BY RAND() LIMIT 5;
INSERT INTO quiz_items
    (id, category, question_type, news_article_id, question_text, option_a, option_b, option_c, correct_option, explanation, show_price_trend) VALUES
(1, 'geopolitical', 'real_news', 1,
 'The US tightened export rules on advanced AI chips to China. Which direction did NVDA move over the following days?',
 'Down sharply, well below the sector', 'Up, roughly in line with the broader sector', 'Flat, no reaction at all',
 'b',
 'NVDA rose about 3.1% while the SOXX sector benchmark rose about 1.0% over the same period — the stock moved with (and somewhat ahead of) the sector, not against it.',
 0),

(2, 'geopolitical', 'concept', NULL,
 'Which of these is the clearest example of a geopolitical news event for a semiconductor stock?',
 'A company beating its quarterly earnings estimate', 'A factory reporting a temporary equipment breakdown', 'A country announcing new export controls on chip technology',
 'c',
 'Export controls, tariffs, and diplomatic tension between chip-manufacturing nations are the defining feature of the geopolitical category.',
 0),

(3, 'earnings', 'real_news', 2,
 'TSMC beat quarterly revenue and margin estimates, citing strong AI chip demand. How did TSM perform against the sector benchmark the next day?',
 'It matched the sector exactly', 'It underperformed the sector, falling more than SOXX', 'It outperformed the sector by a wide margin',
 'b',
 'TSM fell about 2.05% while SOXX fell only about 0.55% — TSM underperformed its own sector despite beating estimates.',
 0),

(4, 'earnings', 'real_news', 6,
 'Micron raised its forward guidance on a memory-pricing recovery. How did MU move relative to the sector?',
 'It outperformed the sector benchmark', 'It underperformed the sector benchmark', 'It moved in the opposite direction of the sector',
 'a',
 'MU rose about 5.4% versus roughly 1.5% for SOXX — a clear outperformance, consistent with a company-specific guidance beat.',
 0),

(5, 'earnings', 'concept', NULL,
 'Why can a stock fall even after reporting record profit?',
 'Because earnings reports never affect stock prices', 'Because record profit always causes an automatic sell-off', 'Because the market reacts to results relative to expectations and guidance, not just absolute profit',
 'c',
 'Markets price in expectations ahead of the report. If guidance disappoints or margins miss forecasts, a stock can fall even on record headline profit.',
 0),

(6, 'macro', 'real_news', 3,
 'Global semiconductor sales rose for an eighth straight month. What is the most likely sector-wide effect?',
 'Only the single largest company reacts', 'Broad positive sentiment across most chip stocks, moving with the sector benchmark', 'No effect, since this is old news by the time it''s published',
 'b',
 'Industry-wide sales data is a macro signal that tends to lift sentiment across the whole sector at once, which is why it shows up in the SOXX benchmark rather than just one stock.',
 0),

(7, 'macro', 'concept', NULL,
 'If a stock and the SOXX sector benchmark move by almost the same percentage on the same day, what does that suggest about the news driving it?',
 'The news is more likely sector-wide (macro) than stock-specific', 'The news is definitely a corporate action', 'The news had no real effect on the market',
 'a',
 'When a stock tracks the benchmark closely, the driver is usually something affecting the whole industry rather than something unique to that one company.',
 0),

(8, 'corporate', 'real_news', 4,
 'Intel announced a new foundry partnership alongside a cost-cutting restructuring plan. How did INTC move compared to the sector?',
 'It moved identically to the sector', 'It significantly underperformed the sector benchmark', 'It significantly outperformed the sector benchmark',
 'c',
 'INTC rose about 6.7% versus roughly 0.9% for SOXX — a large stock-specific outperformance, typical of a company-level strategic announcement.',
 0),

(9, 'corporate', 'concept', NULL,
 'Which of these counts as a "corporate action" rather than a macro or earnings event?',
 'A company announcing a restructuring plan and new executive hires', 'An industry-wide report on global chip sales', 'A country imposing new tariffs on chip imports',
 'a',
 'Corporate actions are decisions a company makes about its own structure — restructuring, M&A, executive changes, buybacks — distinct from sector-wide macro data or a scheduled earnings report.',
 0),

(10, 'supply_chain', 'real_news', 5,
 'ASML flagged delayed shipments due to a shortage of a critical component from a sub-supplier. How did ASML move relative to the sector?',
 'It rose while the sector fell', 'It fell well beyond the sector benchmark''s decline', 'It fell by about the same amount as the sector',
 'b',
 'ASML fell about 5.3% while SOXX fell only about 1.4% — a much larger drop than the sector, consistent with a problem specific to ASML''s own supply chain.',
 0),

(11, 'supply_chain', 'concept', NULL,
 'Why might a shortage at one supplier affect multiple companies'' stock prices?',
 'Because supply chain issues only ever affect the supplier itself', 'Because supply chain news never affects stock prices', 'Because many chipmakers depend on the same specialized suppliers, so a delay can ripple forward to their customers',
 'c',
 'Chipmaking supply chains are highly interconnected — a shortage at one critical supplier can delay production for every company that depends on it.',
 0),

(39, 'earnings', 'real_news', 34,
 'Headline: ''Nvidia reports record Q2 revenue of $13.51 billion''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Soars +15.0%: Record Q2 revenue of $13.51B crushed consensus, triggering an immediate euphoric rally across the AI hardware complex.', 'Drops -6.5%: Investors aggressively took profits as gross margins contracted severely due to soaring TSMC packaging costs.', 'Finishes virtually flat (+0.08%): Despite record Q2 numbers and raised guidance, the stock had rallied 200%+ year-to-date, meaning blowout results were already fully priced in.',
 'c',
 'The stock finished virtually flat at +0.08% the following day (defying a sector decline of -3.30%).\nExplanation & Article Drivers: Nvidia doubled Q2 revenue to $13.51B and guided Q3 revenue to $16.0B (far above the $12.6B consensus) alongside a $25B share buyback. Despite historic results, the stock did not rally because shares had surged over 200% year-to-date into the report, meaning exceptional beats were already priced in. Investors also focused on supply commentary regarding TSMC CoWoS packaging bottlenecks, which capped near-term shipment upside.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Good Earnings Can Still Cause a Muted Reaction / Selloff) & Lesson 2 (Consensus vs Whisper Expectations): Shows that when exceptional results are already embedded in valuation, reported beats fail to generate further upside without supply expansion.',
 1),

(46, 'earnings', 'real_news', 41,
 'Headline: ''TSMC projects return to solid growth in 2024''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +1.04%: Management projected a return to solid 20%+ revenue growth for 2024 driven by 3nm expansion and AI demand, providing strong forward guidance.', 'Drops -7.0%: Lower CapEx budget of $28B-$32B signaled management had lost confidence in long-term AI semiconductor growth.', 'Skyrockets +18.0%: TSMC announced it would triple foundry wafer prices for all major US customers including Apple and Nvidia.',
 'a',
 'The stock gained 1.04% the following day (sector +3.91%).\nExplanation & Article Drivers: TSMC reported Q4 profit beating estimates and guided full-year 2024 revenue growth of 20% to 25% in US dollars. CEO C.C. Wei noted that excess smartphone and PC customer inventories had cleared, while AI server accelerator demand was expanding at 50% annually, confirming that the foundry sector had transitioned from downturn to expansion.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance and Management Commentary) & Lesson 4 (Foundry Utilization & Advanced Nodes): Illustrates how positive multi-quarter revenue guidance and end-market inventory normalization provide visibility and drive stock gains.',
 0),

(62, 'earnings', 'real_news', 57,
 'Headline: ''Nvidia posts 69% sales growth but flags bigger China export-control hit''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunged -6.5%: Warning of a steep drop in Q4 China sales due to newly expanded US export controls triggered heavy institutional selling.', 'Rose +3.25%: Massive 206% YoY Data Center revenue growth easily outweighed the expected China decline, reassuring markets of insatiable Western cloud demand.', 'Surged +18.0%: Nvidia reported that new China export controls had zero effect on any current or future GPU products.',
 'b',
 'The stock rose 3.25% the following day (outperforming the sector''s +0.41% gain).\nExplanation & Article Drivers: Nvidia reported fiscal Q1 sales jumping 69% YoY, but disclosed that U.S. export controls on H20 chips cost ~$2.5B in the quarter and guided to an ~$8B revenue hit in Q2. The stock rallied because surging demand from Western cloud hyperscalers and sovereign AI programs far exceeded supply, proving that global AI momentum easily absorbed the Chinese market restrictions.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Quantifying Export Control Risk Commentary) & Lesson 2 (Expectations vs Absolute Performance): Demonstrates how insatiable global core product demand neutralizes localized geopolitical and regulatory headwinds.',
 1),

(63, 'earnings', 'real_news', 58,
 'Headline: ''TSMC heads into Q4 earnings with record profit expected on AI demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Dropped -3.0%: High expectations heading into earnings triggered pre-emptive profit taking among hedge funds.', 'Remained unchanged (0.00%): Ahead of earnings results, TSMC shares traded strictly sideways in low-volume consolidation.', 'Climbed +4.44%: Bullish pre-earnings expectations driven by strong monthly revenue reports and relentless AI accelerator demand propelled the stock higher.',
 'c',
 'The stock climbed 4.44% the following day (outperforming the sector''s +1.60% rise).\nExplanation & Article Drivers: Ahead of its Q4 earnings call, reports projected record quarterly profit driven by robust 3nm and 5nm wafer demand for AI accelerators. The stock climbed +4.44% as investors anticipated an upward revision to TSMC''s full-year 2026 revenue and CapEx guidance, with cutting-edge node utilization running near 100% and major customers accepting wafer price hikes.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Foundry Indicators: Advanced-Node Utilization, Wafer ASP & CapEx Guidance) & Lesson 5 (Earnings Expectations): Shows how expectations of strong advanced-node wafer pricing power and utilization drive pre-earnings stock rallies.',
 1),

(64, 'earnings', 'real_news', 59,
 'Headline: ''ASML Q1 bookings miss estimates as tariffs cloud 2025-2026 outlook''\nConsidering this is a Earnings calls event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rose +0.82%: While Q1 bookings missed expectations and geopolitical tariff concerns lingered, resilient gross margins and reaffirmed 2025 targets supported the stock.', 'Crashed -8.0%: Impending tariff risks prompted major customers like Intel and TSMC to cancel existing lithography machinery orders.', 'Surges +7.5%: ASML announced full exemption from all US and European international trade tariffs.',
 'a',
 'The stock rose 0.82% the following day (outperforming the sector''s -0.50% dip).\nExplanation & Article Drivers: ASML reported Q1 net bookings of €3.9B, missing consensus expectations as tariff and trade war concerns created customer hesitation. However, the stock held positive ground because ASML reaffirmed its full-year guidance and management clarified that AI demand for advanced logic and HBM memory lithography was resilient, meaning tool orders were merely delayed rather than canceled.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Equipment Indicators: Bookings vs Long-Term Backlog) & Lesson 3 (Risk Commentary): Demonstrates that an order booking miss does not damage stock valuation if management confirms underlying structural demand and preserves annual guidance.',
 1),

(67, 'macro', 'real_news', 62,
 'Headline: ''Federal Reserve raises rates by 25 basis points, acknowledges inflation is easing''\nConsidering this is a Industry-wide (macro) event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.68%: Powell''s mention of a ''disinflationary process'' signaled the end of aggressive rate hikes, lowering bond yields and boosting high-growth tech valuations.', 'Plunges -6.0%: Raising benchmark interest rates by 25 bps increased corporate borrowing costs, triggering panic selling in capital-intensive tech.', 'Surges +15.0%: The Fed announced an emergency rate cut to 0%, triggering the largest single-day Nasdaq rally of the decade.',
 'a',
 'The stock price rose 3.68% the following day (outperforming the sector''s +2.32% gain).\nExplanation & Article Drivers: The Federal Reserve raised interest rates by 25 bps as expected, but Chair Jerome Powell acknowledged for the first time that the ''disinflationary process has started.'' Investors cheered the commentary as a clear signal that the aggressive rate-hike campaign was near its conclusion. Falling Treasury yields relieved valuation multiple compression on high-growth equities, sparking aggressive buying in premier AI leaders like Nvidia.\nRelated DIP Lesson: Lesson - Industry macro: Lesson 1 (The Cost of Capital: Interest Rate Hikes & Cuts) & Lesson 2 (Inflation Indicators as Market Catalysts): Demonstrates how falling benchmark bond yields reduce the equity discount rate, driving immediate Price-to-Earnings (P/E) multiple expansion for high-growth tech stocks.',
 1),

(71, 'macro', 'real_news', 66,
 'Headline: ''Fed holds rates steady, sparking massive tech and bond rally''\nConsidering this is a Industry-wide (macro) event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.0%: Holding rates steady without committing to future cuts disappointed investors who demanded immediate monetary easing.', 'Rises +1.50%: Holding benchmark rates steady while dot-plot projections confirmed the end of tightening fueled a broad tech and bond rally.', 'Surges +8.5%: Freezing rates instantly resolved the global memory chip oversupply and pushed DRAM prices to all-time highs.',
 'b',
 'The stock price rose 1.50% the following day (tracking the sector''s +2.27% rally).\nExplanation & Article Drivers: The Fed held interest rates steady at 5.25%-5.50% for a second consecutive meeting, noting that elevated long-term Treasury yields were doing the work of cooling the economy. Benchmark yields plunged immediately, igniting a massive tech rally. Micron advanced as cheaper borrowing costs and lower discount rates encouraged institutional capital rotation back into capital-intensive, cyclical memory producers.\nRelated DIP Lesson: Lesson - Industry macro: Lesson 1 (The Cost of Capital: Valuation Multiple Compression Relieved): Plunging bond yields lower the cost of capital, relieving valuation pressure on high-CapEx memory manufacturers and stimulating market liquidity.',
 0),

(74, 'macro', 'real_news', 69,
 'Headline: ''SIA says global semiconductor sales increased month-to-month in September''\nConsidering this is a Industry-wide (macro) event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.0%: Month-over-month sales growth was deemed too sluggish to justify current memory stock valuations.', 'Rises +1.60%: Successive month-over-month sales increases confirmed demand stabilization across memory and logic chips, reinforcing cyclical recovery hopes.', 'Surges +12.0%: September sales broke all-time historic records, completely erasing the multi-year post-pandemic electronics slump.',
 'b',
 'The stock price rose 1.60% the following day (sector +2.27%).\nExplanation & Article Drivers: SIA announced that global chip sales reached $44.9B in September 2023, rising 1.9% month-over-month for the seventh consecutive monthly increase. Samsung gained as this official data confirmed the chip market had definitively bottomed out, providing macro proof that upstream memory production cuts and downstream inventory absorption were driving a durable pricing recovery.\nRelated DIP Lesson: Lesson - Industry macro: Lesson 4 (Sector-Wide Growth Forecasts: Confirming the Trend) & Lesson 3 (Consumer Demand Cycles: Inventory Digestion): Comprehensive industry sales data confirms that downstream consumer inventory digestion has ended, restoring supplier pricing power.',
 1),

(86, 'macro', 'real_news', 81,
 'Headline: ''US CPI comes in cooler than expected for October''\nConsidering this is a Industry-wide (macro) event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.0%: Cooler inflation sparked fears of rapid deflation and contracting consumer spending across Asian markets.', 'Gains +1.98%: Slower inflation cemented expectations that Fed rate hikes had concluded, lifting Treasury yields pressure and driving global tech equity gains.', 'Surges +9.0%: Cooler CPI triggered an immediate emergency rate cut from the Bank of Korea.',
 'b',
 'The stock price gained 1.98% the following day (outperforming the sector''s +0.73% rise).\nExplanation & Article Drivers: US headline CPI was unchanged MoM in October and slowed to 3.2% YoY, cooler than economists forecast. The data sparked a powerful global relief rally, with Samsung gaining nearly 2% as tumbling bond yields and rate pause certainty stimulated risk appetite, lowering corporate borrowing costs and boosting expectations for an enterprise and consumer hardware recovery.\nRelated DIP Lesson: Lesson - Industry macro: Lesson 2 (Inflation Indicators: How ''Cool'' Inflation Data Pushes Stocks Up: The Relief Rally): Cooler-than-expected inflation releases give central banks the green light to halt rate hikes, driving down bond yields and triggering rapid equity multiple expansion.',
 0),

(93, 'corporate', 'real_news', 88,
 'Headline: ''Nvidia announces 10-for-1 stock split following massive earnings beat''\nConsidering this is a Corporate actions event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.0%: Stock splits create no fundamental value and investors took profits following the announcement.', 'Surges +9.32%: A 10-for-1 forward split drastically improved retail investor accessibility and liquidity, amplifying momentum from blowout Q1 earnings.', 'Surges over +30%: Lowering the per-share price from $1,000 to $100 instantly tripled Nvidia''s total enterprise valuation.',
 'b',
 'The stock surged 9.32% the following day (defying a sector decline of -0.56%).\nExplanation & Article Drivers: Alongside record Q1 earnings, Nvidia announced a 10-for-1 forward stock split and raised its dividend by 150%. While a stock split does not change the company''s underlying market valuation or enterprise value, dropping the per-share price from ~$1,000 to ~$100 drastically improved retail accessibility, liquidity, and options market participation, fueling substantial buying demand.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 2 / 3 (Capital Allocation: Stock Splits and Buybacks: Retail Accessibility): Stock splits divide existing shares to lower the individual share price, making equity accessible to retail investors and employees and driving liquidity and positive sentiment.',
 1),

(143, 'supply_chain', 'real_news', 138,
 'Headline: ''TSMC working hard to meet chip demand, would like to hike prices''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunges -8.0%: Threatening to hike prices provoked backlash from major customers like Apple, threatening foundry order cancellations.', 'Remains unchanged (0.00%): Wafer price hikes were dismissed as empty rhetoric because TSMC had already signed fixed multi-year customer contracts.', 'Rises +2.40%: Executive commentary indicating intentions to raise prices demonstrated unmatched pricing power, allowing TSMC to rally despite a sector drop.',
 'c',
 'The stock price rose 2.40% the following day (sharply defying a severe sector selloff of -10.44%).\nExplanation & Article Drivers: TSMC Chairman C.C. Wei publicly stated that TSMC''s AI capacity was under severe strain and confirmed plans to hike wafer prices for advanced manufacturing and packaging services. TSMC surged +2.40% while the sector collapsed -10.44% because the planned price increases proved TSMC''s monopolistic pricing power, directly expanding expected gross margins and future earnings.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Financial Metrics: ASP ↑ + Utilisation ↑ → Gross Margin ↑ → Profit ↑) & Lesson 2 (Supply-Chain Pricing Power): Demonstrates operating leverage: when demand exceeds supply, raising wafer prices directly expands gross margin percentages and fuels earnings growth.',
 1),

(144, 'supply_chain', 'real_news', 139,
 'Headline: ''Nvidia CEO says its advanced packaging technology needs are changing''\nConsidering this is a Supply chain event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.40%: Signaling evolving packaging requirements highlighted rapid architectural innovation, reinforcing Nvidia''s technology leadership in AI compute.', 'Plunges -6.0%: Evolving packaging needs indicated that TSMC''s CoWoS technology was obsolete and could no longer support Nvidia chips.', 'Surges +14.0%: Nvidia announced it had designed a revolutionary chip that completely eliminates the need for advanced packaging.',
 'a',
 'The stock price rose 2.40% the following day (in line with the sector''s +2.77% gain).\nExplanation & Article Drivers: Jensen Huang noted that Nvidia''s packaging requirements were shifting from CoWoS-S to more complex CoWoS-L and panel-level packaging to accommodate massive Blackwell multi-die architectures. The stock rose as investors recognized that Nvidia was collaborating closely with TSMC to retool packaging capacity ahead of volume ramps, ensuring high yields for high-ASP Blackwell GPUs.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure: Advanced Packaging Bottlenecks) & Lesson 2 (Ecosystem Coordination): Architectural shifts toward multi-chiplet packaging require proactive supply-chain retooling, enabling chip designers to capture higher average selling prices.',
 1),

(145, 'supply_chain', 'real_news', 140,
 'Headline: ''Nvidia refocuses TSMC capacity as export controls stall China sales''\nConsidering this is a Supply chain event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -5.0%: Stalling China sales forced Nvidia to write off billions of dollars in specialized Hopper wafer capacity.', 'Rises +2.40%: Successfully reallocating advanced TSMC foundry capacity to satisfy insatiable Western AI demand demonstrated remarkable operational agility.', 'Surges +12.0%: Reallocating capacity enabled Nvidia to immediately eliminate all global lead times for H100 GPU clusters.',
 'b',
 'The stock price rose 2.40% the following day (sharply outperforming the sector''s -4.22% decline).\nExplanation & Article Drivers: Following expanded US export controls that stalled China-specific H20 chips, Nvidia swiftly reallocated its reserved TSMC advanced packaging and wafer capacity toward next-generation global Blackwell and Hopper chips. The stock rallied against a falling sector because Nvidia demonstrated agile supply-chain flexibility, immediately replacing restricted Chinese volume with high-margin Western enterprise demand.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Geopolitical Restrictions & Capacity Reallocation): Demonstrates how fabless market leaders mitigate regional export restrictions by seamlessly redirecting contracted foundry capacity to unconstrained global markets.',
 0),

(146, 'supply_chain', 'real_news', 141,
 'Headline: ''ASML expected to address capacity and China challenges as AI demand surges''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunges -7.0%: China export risks and manufacturing capacity challenges sparked fears that ASML''s 2025 growth targets were unachievable.', 'Surges +9.0%: ASML announced the Chinese government had granted a special permanent waiver for all lithography exports.', 'Rises +2.40%: Reassurances that expanding capacity would meet surging long-term AI demand bolstered investor confidence, defying a sector decline.',
 'c',
 'The stock price rose 2.40% the following day (defying a sector decline of -2.23%).\nExplanation & Article Drivers: Reports highlighted that ASML was actively expanding production capacity for EUV tools booked through 2027 while managing export limits on China. ASML rose against a falling sector as investors focused on ASML''s multi-year order backlog driven by global AI fab expansions, recognizing that Western fab construction more than compensated for Chinese regulatory headwinds.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Equipment Moats & Backlogs) & Lesson 2 (End-Market AI Demand Driving Equipment CapEx): Long equipment backlogs and indispensable lithography technology insulate toolmakers from regional market turbulence during global AI fab buildouts.',
 0),

(147, 'supply_chain', 'real_news', 142,
 'Headline: ''ASML warns tariffs cloud outlook as semiconductor equipment crosses borders repeatedly''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.40%: Warning that geopolitical tariffs create supply chain friction was viewed as an industry-wide risk that ASML''s unmatched moat would easily navigate.', 'Crashes -8.0%: Tariffs on cross-border machinery components caused ASML to suspend all equipment manufacturing in Europe.', 'Surges +10.0%: International trade authorities announced complete tariff exemptions for all semiconductor manufacturing equipment.',
 'a',
 'The stock price rose 2.40% the following day (outperforming the sector''s -0.50% dip).\nExplanation & Article Drivers: ASML cautioned that escalating international trade tariffs added logistical complexity and cost uncertainty, as specialized components cross European, US, and Asian borders dozens of times during tool assembly. The stock held positive ground because investors recognized that ASML''s technological monopoly enabled it to pass trade tariffs and logistical costs directly onto foundry customers.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Geopolitical Restrictions & Component Supply Friction) & Lesson 4 (Pricing Power & Cost Pass-Through): Globalized semiconductor supply chains face logistical friction from tariffs, but proprietary equipment monopolies maintain strong pricing power to pass through costs.',
 1),

(148, 'supply_chain', 'real_news', 143,
 'Headline: ''TSMC still evaluating ASML High-NA while Intel targets future use''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.5%: TSMC delaying High-NA adoption proved that the $350M lithography tool was a commercially unviable technology.', 'Rises +2.40%: Intel aggressively adopting High-NA early while TSMC evaluated cost-effectiveness reassured markets that both leaders were advancing advanced nodes.', 'Surges +11.0%: Intel adopting High-NA allowed it to manufacture sub-1nm chips commercially ahead of all global competitors.',
 'b',
 'The stock price rose 2.40% the following day (outperforming the sector''s -0.50% dip).\nExplanation & Article Drivers: Reports indicated TSMC was holding off on adopting expensive High-NA EUV tools ($350M+ each) until its A14 node in 2027 due to cost concerns, whereas Intel was actively deploying them for its 14A node. Intel''s stock gained as investors viewed its early High-NA adoption as a bold technological leap that could allow Intel to regain process node leadership over TSMC.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Industry Structure: Equipment & Foundries) & Lesson 4 (CapEx vs Technology Moats): Foundries make strategic tradeoffs between tool costs and lithography scaling; adopting next-generation equipment early offers a chance to leapfrog rivals in transistor density.',
 1),

(149, 'supply_chain', 'real_news', 144,
 'Headline: ''US finalizes chip subsidies supporting domestic advanced-node capacity''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.0%: Subsidies had been leaked months in advance, triggering an immediate ''sell-the-news'' reaction among hedge funds.', 'Surges +15.0%: Finalizing federal CHIPS subsidies fully covered 100% of Intel''s domestic factory construction costs.', 'Rises +2.40%: Finalizing billions in direct CHIPS Act grants and loans cemented federal backing for Intel''s leading-edge manufacturing, outperforming the sector.',
 'c',
 'The stock price rose 2.40% the following day (outperforming the sector''s +1.29% gain).\nExplanation & Article Drivers: The US Commerce Department finalized binding CHIPS Act awards across domestic foundries, including Intel and TSMC, to establish onshore advanced-node capacity. Intel gained as finalized subsidies de-risked its multi-billion-dollar domestic fab financing, lowering capital expenditure outlays and ensuring dedicated government backing for its foundry network.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Capacity Expansion & Subsidies) & Lesson 4 (Free Cash Flow): Direct government grants reduce corporate capital expenditure burdens, directly boosting free cash flow projections for domestic manufacturing facilities.',
 1),

(150, 'supply_chain', 'real_news', 145,
 'Headline: ''Micron among memory makers driving ASML tool demand as AI capacity expands''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.40%: Memory makers driving ASML equipment demand highlighted accelerating CapEx for high-bandwidth memory, confirming cyclical recovery in memory.', 'Drops -5.0%: High tool procurement costs by memory manufacturers threatened to compress Micron''s operating margins.', 'Surges +12.0%: Micron announced it had purchased 100% of ASML''s High-NA lithography tools for DRAM fabrication.',
 'a',
 'The stock price rose 2.40% the following day (defying a sector decline of -2.23%).\nExplanation & Article Drivers: Reports detailed that memory producers including Micron and SK Hynix were ramping EUV tool procurement from ASML to scale high-density 1-beta and 1-gamma DRAM for HBM3E. Micron rose against a declining market as investors recognized that incorporating EUV lithography into memory manufacturing provided superior bit density and power efficiency, driving premium pricing in AI servers.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Memory Manufacturers Adopting EUV Equipment) & Lesson 4 (Bit Density & ASP Expansion): Transitioning memory production to advanced lithography lowers per-bit manufacturing costs and expands gross margins on high-performance AI memory.',
 0),

(151, 'supply_chain', 'real_news', 146,
 'Headline: ''AI memory shortage drives long-term capacity expansion across HBM supply chain''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plummets -7.0%: Industry-wide capacity expansion raised immediate fears that the memory market would plunge into severe oversupply by 2025.', 'Rises +2.40%: Prolonged HBM shortages and structured multi-year capacity expansions supported strong pricing power and gross margin expansion.', 'Surges +14.0%: HBM shortages forced cloud hyperscalers to sign 10-year non-cancelable memory supply contracts with Micron.',
 'b',
 'The stock price rose 2.40% the following day (strongly outperforming a -3.20% sector drop).\nExplanation & Article Drivers: Industry reports forecasted severe high-bandwidth memory shortages extending through 2030 due to explosive AI data center buildouts, forcing memory makers into multi-year capacity expansions. Micron advanced against a broad market decline as investors priced in persistent memory supply tightness, which guaranteed multi-year pricing power and elevated operating margins.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Stage 3 Shortage Phase) & Lesson 2 (Supply-Demand Tightness): When structural shortages outpace capacity expansion for years, memory manufacturers enjoy extended pricing power, driving sustained multi-year profitability.',
 0),

(152, 'supply_chain', 'real_news', 147,
 'Headline: ''Micron to exit consumer memory business amid global supply shortage''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +6.0%: Exiting low-margin consumer memory lines was cheered as a masterstroke that would immediately double corporate gross margins.', 'Remains flat (0.00%): Consumer memory represented such an insignificant fraction of total revenue that markets completely ignored the announcement.', 'Drops -3.21%: Exiting consumer memory sparked near-term restructuring costs and highlighted intense price competition from domestic Chinese memory producers.',
 'c',
 'The stock price dropped 3.21% the following day (underperforming the sector''s -1.00% dip).\nExplanation & Article Drivers: Micron announced plans to wind down certain consumer-grade memory retail product lines to redirect silicon wafers and packaging capacity toward higher-margin AI enterprise customers. The stock fell because investors were concerned over near-term restructuring expenses and revenue disruption from forfeiting consumer retail channels before AI memory volume fully scaled.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Capacity Reallocation) & Lesson 4 (Product Mix & Restructuring Costs): Reallocating manufacturing capacity from consumer to enterprise markets optimizes long-term gross margins, but can trigger near-term revenue friction.',
 1),

(153, 'supply_chain', 'real_news', 148,
 'Headline: ''ASML denies selling EUV chipmaking tool to China after report of US concern''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Remains flat (-0.02%): Clarifying that ASML had complied with export rules and not sold EUV systems to China removed regulatory overhang during a -7.88% sector crash.', 'Crashes -15.0%: Reports of US scrutiny prompted the Dutch government to revoke ASML''s corporate operating charter.', 'Surges +8.0%: US officials officially apologized to ASML and lifted all existing export controls on advanced DUV lithography systems.',
 'a',
 'The stock price remained virtually flat at -0.02% the following day (massively outperforming a -7.88% sector crash).\nExplanation & Article Drivers: ASML firmly denied reports that it had shipped EUV lithography systems to Chinese semiconductor firms, confirming complete compliance with Dutch and US export bans. The stock held steady while the sector plunged nearly 8% because ASML''s clarification removed catastrophic regulatory enforcement risks, reassuring investors that its global business was in full compliance.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Geopolitical Restrictions & Regulatory Overhang): Regulatory compliance in equipment supply chains is paramount; disproving illegal export rumors eliminates existential legal and sanctions risks.',
 1),

(154, 'supply_chain', 'real_news', 149,
 'Headline: ''China''s chip tool push shows ASML caught in US-China squeeze''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +5.0%: Accelerating Chinese domestic tool development provided ASML with lucrative joint venture licensing royalties.', 'Falls -2.04%: Being caught in US-China geopolitical crosshairs highlighted long-term revenue vulnerabilities, though beating a severe -5.38% sector drop.', 'Plunges -12.0%: China''s domestic lithography breakthrough rendered all ASML immersion DUV systems obsolete within mainland fabs.',
 'b',
 'The stock price fell 2.04% the following day (outperforming the sector''s -5.38% drop).\nExplanation & Article Drivers: Reports highlighted China''s accelerating multi-billion-dollar push to commercialize domestic immersion DUV lithography systems (via SMEE) to bypass Western export curbs. ASML fell as investors contemplated long-term market-share erosion in China, though it outperformed the broader market drop because domestic Chinese tools remained generations behind ASML''s precision lithography.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Equipment Moats & Barriers to Entry) & Lesson 2 (Geopolitical Restrictions & Domestic Substitution): Export bans accelerate foreign domestic substitution programs, threatening long-term mature equipment market share while preserving leading-edge moats.',
 1),

(155, 'supply_chain', 'real_news', 150,
 'Headline: ''Dutch government objects to proposed US law restricting ASML''s China exports''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +6.0%: Dutch government objections forced the US Congress to permanently withdraw all proposed extraterritorial export control legislation.', 'Remains unchanged (0.00%): Geopolitical posturing was viewed as routine diplomatic noise with zero impact on equipment shipment schedules.', 'Falls -5.22%: Escalating diplomatic friction between the US and Netherlands over ASML''s China servicing raised fears of harsher unilateral US restrictions.',
 'c',
 'The stock price fell 5.22% the following day (underperforming the sector''s -4.06% decline).\nExplanation & Article Drivers: The Dutch government publicly voiced opposition to unilateral US legislative proposals aiming to restrict ASML from servicing and repairing previously sold DUV tools in China. ASML dropped sharply as geopolitical tensions threatened recurring service revenue and customer maintenance contracts, which comprise one of ASML''s highest-margin, most stable revenue streams.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Servicing Bans & Installed Base Friction): Equipment business models rely heavily on high-margin recurring servicing and maintenance; expanding export bans to tool maintenance threatens recurring operating profits.',
 0),

(156, 'supply_chain', 'real_news', 151,
 'Headline: ''SK Hynix to start AI chip output in Indiana in 2029, sees memory shortage through 2030''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunges -8.0%: SK Hynix building an Indiana packaging fab threatened to steal Micron''s domestic US customers like Intel and IBM.', 'Dips -0.27%: SK Hynix predicting HBM shortages through 2030 validated multi-year structural memory demand, keeping Micron stable during a -3.20% sector drop.', 'Surges +10.0%: Prolonged shortage forecasts allowed Micron to double contract prices on all legacy DDR4 and DDR5 memory modules.',
 'b',
 'The stock price dipped 0.27% the following day (strongly outperforming the sector''s -3.20% drop).\nExplanation & Article Drivers: SK Hynix broke ground on a $4 billion advanced packaging fab in Indiana and projected structural HBM shortages lasting through 2030. Micron showed strong relative resilience against a declining sector because long-term structural shortage forecasts confirmed that high memory pricing and tight capacity would benefit all major HBM producers for the rest of the decade.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Structural Shortage Phase) & Lesson 1 (Memory Industry Dynamics): Extended shortage forecasts signal durable pricing power for all qualified memory manufacturers, supporting high gross margins and dampening cyclical volatility.',
 0),

(157, 'supply_chain', 'real_news', 152,
 'Headline: ''SK Hynix expands US HBM packaging capacity as AI customers drive demand''\nConsidering this is a Supply chain event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +6.0%: Expanding US packaging capacity guaranteed Nvidia zero supply chain lead times for all future Blackwell AI accelerators.', 'Remains flat (0.00%): SK Hynix''s long-term Indiana packaging facility was too distant to impact near-term GPU trading sentiment.', 'Falls -4.58%: Broad macro rate jitters and semiconductor profit-taking pulled Nvidia down, as long-term 2028 packaging plans offered no immediate supply relief.',
 'c',
 'The stock price fell 4.58% the following day (underperforming the sector''s -3.20% decline).\nExplanation & Article Drivers: SK Hynix''s groundbreaking on a US HBM packaging facility promised to localize critical memory supplies closer to US AI data centers. However, Nvidia fell alongside a broader market selloff as investors recognized that the Indiana packaging facility would not come online until 2028-2029, offering no immediate relief to near-term HBM and packaging supply constraints.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Lead Times vs Near-Term Constraints): Long multi-year construction lead times mean future packaging fabs cannot resolve immediate supply-chain shortages, keeping near-term shipment ceilings in place.',
 1),

(158, 'supply_chain', 'real_news', 153,
 'Headline: ''ASML export restrictions accelerate China''s push for domestic lithography''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -5.12%: Accelerating Chinese domestic lithography R&D raised long-term structural competitive risks, pulling Intel down alongside a -5.38% sector tumble.', 'Surges +7.0%: Chinese equipment push prompted US tech firms to increase domestic semiconductor CapEx orders with Intel Foundry.', 'Crashes -15.0%: Chinese domestic lithography advances caused Intel to abandon its entire European fab expansion strategy.',
 'a',
 'The stock price fell 5.12% the following day (in line with the sector''s -5.38% tumble).\nExplanation & Article Drivers: Reports highlighted that expanding Western export restrictions on ASML were driving massive Chinese state subsidies into domestic wafer fabrication and domestic equipment makers. Intel dropped alongside a broader market selloff as investors worried that aggressive Chinese equipment localization would eventually create a flood of subsidized legacy-node chips, eroding global foundry margins.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Overinvestment & Future Oversupply) & Lesson 2 (Geopolitical Restrictions): Subsidized domestic capacity expansion in response to export bans risks creating long-term industry-wide oversupply in trailing process nodes.',
 1),

(159, 'supply_chain', 'real_news', 154,
 'Headline: ''Nvidia CEO says its advanced packaging technology needs are changing''\nConsidering this is a Supply chain event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rose +3.10%: Reaffirming adaptable packaging requirements demonstrated technical flexibility to scale Blackwell architecture using multiple advanced packaging partners.', 'Drops -4.5%: Changing packaging requirements indicated severe defect rates in TSMC''s CoWoS-L substrate manufacturing.', 'Surges +12.0%: Nvidia announced it would build its own multi-billion-dollar semiconductor packaging foundries in North America.',
 'a',
 'The stock price rose 3.10% the following day (outperforming the sector''s +2.77% gain).\nExplanation & Article Drivers: Jensen Huang discussed how the complexity of AI chip architectures was forcing a transition toward CoWoS-L and panel-level packaging, requiring tighter co-engineering with TSMC and substrate suppliers. The stock rose as investors gained confidence that Nvidia had secured the necessary next-generation packaging lines to support the ramp of high-margin Blackwell GPU racks.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Packaging and Testing as Core Industry Chokepoint) & Lesson 2 (Supply-Chain Coordination): Demonstrates how fabless leaders proactively coordinate with foundry and packaging partners to ensure backend capacity matches complex chiplet architecture rollouts.',
 0),

(201, 'geopolitical', 'real_news', 201,
 'Headline: ''Nvidia stock falls after U.S. announces new restrictions on AI chip exports''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.10%: Nvidia said it did not expect a near-term meaningful impact on its financial results, so investors may shrug off the rules.', 'Falls -3.96%: Tighter rules that close the loophole around the China-specific A800 and H800 chips remove a product line, so investors may mark down future China sales.', 'Falls -9.50%: The curbs cover several flagship chips, so the market may price in a collapse of China sales.',
 'b',
 'The stock fell 3.96% the following day (compared to the sector''s -1.80%).\nExplanation & Article Drivers: The Commerce Department closed the loophole around Nvidia''s China-specific A800 and H800 chips, and Nvidia said the curbs also cover the A100, H100, L40, L40S and RTX 4090. Nvidia had already fallen 4.68% on the announcement day, so this question is about the following session. Nvidia said it did not expect a near-term meaningful impact, yet the stock fell by about twice the sector''s move, so investors appeared to weigh the China exposure more heavily than the reassurance.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(202, 'geopolitical', 'real_news', 202,
 'Headline: ''Nvidia shares fall after China opens investigation over possible violation of antimonopoly law''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.50%: The probe is only an investigation with no penalty yet, so investors may look past it.', 'Falls -8.00%: The probe could threaten Nvidia''s whole China business, so a very steep drop is likely.', 'Falls -2.69%: A Chinese antimonopoly probe tied to the Mellanox deal adds regulatory risk in one of Nvidia''s largest markets.',
 'c',
 'The stock fell 2.69% the following day (in line with the sector''s -2.38%).\nExplanation & Article Drivers: China''s market regulator opened an antimonopoly investigation tied to Nvidia''s 2020 Mellanox acquisition, and China is one of Nvidia''s largest markets. The stock closed about 2.6% lower on the news day. The next-day fall of 2.69% was close to the sector''s 2.38% decline, so most of the move appeared to come from sector weakness, with only a small extra amount specific to Nvidia.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(203, 'geopolitical', 'real_news', 203,
 'Headline: ''Nvidia falls on tougher AI chip export rules. Jim Cramer calls them ''absurd''''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -1.10%: A tiered licensing system and a cap on computing power could limit sales to many countries, so investors may stay cautious.', 'Rises +3.20%: Eighteen close allies were exempt, so investors may see the rules as a limited burden and rebound.', 'Falls -6.50%: The cap affects most of the world, so sales could drop sharply.',
 'a',
 'The stock fell 1.10% the following day (against the sector''s +0.66%).\nExplanation & Article Drivers: The outgoing Biden administration unveiled a tiered licensing system with a cap on computing power most countries could obtain, while 18 close allies were exempt. Nvidia had fallen about 2.5% on the announcement day and was more than 10% below its record close of $149.43 on Jan. 6. The following session saw a smaller fall of 1.10% while the sector edged up, so the pressure appeared specific to Nvidia and the export rules rather than the sector.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(204, 'geopolitical', 'real_news', 204,
 'Headline: ''Tech stocks drop as Nvidia, AMD warn of higher costs from China export controls''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.10%: After a roughly 7% drop, investors may rebound now that the charge is known.', 'Falls -2.87%: A license requirement for the H20 and a $5.5 billion quarterly charge show the cost of China export controls, so selling pressure may continue.', 'Falls -0.35%: The charge was already reflected in the large drop, so little further change is likely.',
 'b',
 'The stock fell 2.87% the following day (against the sector''s -0.50%).\nExplanation & Article Drivers: The US told Nvidia it needed a license to export its H20 AI chip to China, and Nvidia said it would take a $5.5 billion quarterly charge. Nvidia fell about 7% on the news day, and this question concerns the following session. The next-day fall of 2.87% was much larger than the sector''s 0.50% decline, so investors appeared to keep marking down Nvidia specifically, since the H20 was designed for China to meet earlier US limits.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(205, 'geopolitical', 'real_news', 205,
 'Headline: ''Nvidia and AMD to pay 15% of China chip sales revenues to the U.S. government, FT reports''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -0.35%: Handing 15% of certain China chip revenue to the US government trims margins, even though the licenses restore some sales.', 'Rises +3.50%: Export licenses reopen China sales, so investors may buy aggressively.', 'Falls -5.00%: Paying 15% of revenue is a heavy cost that could badly damage profits.',
 'a',
 'The stock fell 0.35% the following day (in line with the sector''s -0.19%).\nExplanation & Article Drivers: Nvidia and AMD agreed to give the US government 15% of revenue from certain chips sold in China, including the H20, in exchange for export licenses, according to the Financial Times. The stock slipped only 0.35% the next day, close to the sector''s 0.19% dip, so the news appeared to have little effect beyond general sector drift. Investors appeared to weigh the revenue share against the benefit of having licenses to sell in China.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(206, 'geopolitical', 'real_news', 206,
 'Headline: ''China says Nvidia violated anti-monopoly law after preliminary probe''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.00%: Nvidia said it complies with the law in all respects, so investors may treat the finding as a procedural step.', 'Falls -7.00%: A violation finding could lead to a ban in China, so a steep sell-off is likely.', 'Falls -1.62%: A finding that Nvidia violated antimonopoly law, with the probe continuing, raises the risk of penalties in a major market.',
 'c',
 'The stock fell 1.62% the following day (against the sector''s +0.30%).\nExplanation & Article Drivers: China''s market regulator said a preliminary probe found Nvidia violated the anti-monopoly law over its 2020 Mellanox acquisition and that the investigation would continue, without saying how. Nvidia replied that it complies with the law in all respects. The stock fell 1.62% the next day while the sector rose 0.30%, so the weakness appeared specific to Nvidia, consistent with investors worrying about possible penalties.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(207, 'geopolitical', 'real_news', 207,
 'Headline: ''Trump greenlights Nvidia H200 AI chip sales to China if U.S. gets 25% cut, says Xi responded positively''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.00%: Permission to ship H200 chips to China reopens a large market, so investors may buy aggressively.', 'Falls -0.31%: The 25% cut to the US government is higher than the 15% agreed earlier and Blackwell and Rubin chips are excluded, which tempers the benefit of new China access.', 'Falls -4.50%: A 25% government cut is a heavy burden, so the stock may drop sharply.',
 'b',
 'The stock fell 0.31% the following day (in line with the sector''s -0.18%).\nExplanation & Article Drivers: Trump said Nvidia could ship H200 chips to approved customers in China, with 25% of proceeds going to the US government, up from the 15% agreed earlier in 2025, while Blackwell and Rubin chips were excluded. The stock slipped 0.31% against a 0.18% sector dip, a small move that went with the sector, which suggests investors saw the extra China access and the bigger government share as roughly offsetting.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(208, 'geopolitical', 'real_news', 208,
 'Headline: ''US to award TSMC $6.6B in grants, $5B in loans to step up chip manufacturing in Arizona''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -2.40%: A third Arizona fab pushes planned spending above $65 billion, which may worry investors about returns.', 'Rises +8.00%: A multi-billion subsidy is a huge windfall, so shares should surge.', 'Rises +1.83%: Up to $6.6 billion in CHIPS Act grants plus about $5 billion in loans lowers the cost of building TSMC''s Arizona plants.',
 'c',
 'The stock rose 1.83% the following day (compared to the sector''s +1.08%).\nExplanation & Article Drivers: The Commerce Department signed a preliminary agreement for up to $6.6 billion in CHIPS Act grants plus about $5 billion in proposed loans, and TSMC announced a third Arizona fab, taking planned capital spending at the Phoenix site above $65 billion. The stock rose 1.83% against a 1.08% sector gain, so the sector lifted it and TSMC outperformed modestly, which fits investors appearing to value the funding support for its US expansion.\nRelated DIP Lesson: Lesson - Political: Lesson 2 (Government Grants & Subsidies)',
 1),

(209, 'geopolitical', 'real_news', 209,
 'Headline: ''Trump says Taiwan should pay the U.S. for defense; shares of chip giant TSMC fall''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +0.39%: After a morning dip on Trump''s remarks, the reaction faded and the stock edged up with the sector.', 'Falls -3.50%: Remarks questioning US support for Taiwan raise geopolitical risk for the key chipmaker, so selling continues.', 'Rises +3.80%: The dip may reverse sharply as the fear fades.',
 'a',
 'The stock rose 0.39% the following day (in line with the sector''s +0.30%).\nExplanation & Article Drivers: Trump said Taiwan should pay the US for defense and that Taiwan took about 100% of the US chip business, and TSMC shares fell more than 2% in morning trading on the remarks. The question here is the following session, when the stock edged up 0.39%, close to the sector''s 0.30% gain. Investors appeared to treat the remarks as talk rather than a change in real supply, so the fear discount faded and the move was mostly sector-driven.\nRelated DIP Lesson: Lesson - Political: Lesson 3 (Factory Location Risk)',
 1),

(210, 'geopolitical', 'real_news', 210,
 'Headline: ''U.S. ordered TSMC to halt shipments to China of chips used in AI applications, source says''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.50%: The order covers only some chips and customers, so the stock may hold up.', 'Falls -3.55%: A US order to halt shipments of 7nm and more advanced AI chips to China cuts off a group of customers.', 'Falls -0.40%: The restriction affects a narrow set of products, so the impact on TSMC''s sales may be small.',
 'b',
 'The stock fell 3.55% the following day (compared to the sector''s -2.50%).\nExplanation & Article Drivers: A Commerce Department letter restricted shipments to China of chips on 7nm or more advanced processes used in AI accelerators and GPUs, following the discovery of a TSMC-made part inside a Huawei AI processor. TSMC told affected customers it was suspending such shipments from Nov. 11. The stock fell 3.55% against a 2.50% sector fall, so a large part of the drop looked sector-wide, with TSMC falling somewhat more.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(211, 'geopolitical', 'real_news', 211,
 'Headline: ''What the world''s biggest chipmakers are doing to stave off Trump''s tariffs''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.80%: The exemption for companies building in the US should keep lifting TSMC.', 'Falls -5.50%: A proposed 100% chip tariff would hurt the whole industry, so the stock should drop hard.', 'Falls -0.33%: After a sharp rise on hopes that its US expansion would shield it from tariffs, investors may have paused while the sector rose.',
 'c',
 'The stock fell 0.33% the following day (against the sector''s +0.84%).\nExplanation & Article Drivers: Trump proposed a 100% tariff on imported chips but said companies building or committed to build in the US would not be charged, and TSMC shares rose nearly 5% in Taiwan on its US expansion. The following session saw a 0.33% fall for the stock while the sector rose 0.84%, so the stock lagged the sector, and investors appeared to pause after the earlier jump.\nRelated DIP Lesson: Lesson - Political: Lesson 4 (Tariffs & Trade Wars)',
 1),

(212, 'geopolitical', 'real_news', 212,
 'Headline: ''Intel faces headwinds in China as trade body calls for security probe''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.47%: The call is only a recommendation from a trade body, so investors may have judged the risk as limited for now.', 'Falls -3.50%: China was 27% of Intel''s revenue, ahead of the US at 26%, so a security review threatens a big part of sales.', 'Falls -0.80%: Intel prioritizes product safety, but the review recommendation creates mild uncertainty.',
 'a',
 'The stock rose 1.47% the following day (against the sector''s +0.09%).\nExplanation & Article Drivers: The Cybersecurity Association of China recommended a cybersecurity review of Intel products sold in China, citing vulnerabilities and failure rates, and Intel said it prioritizes product safety and quality. China accounted for 27% of Intel''s revenue the previous year versus 26% from the US. The stock rose 1.47% while the sector was nearly flat at 0.09%, so the gain was specific to Intel, and investors appeared to treat the call as a recommendation rather than a ban.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(213, 'geopolitical', 'real_news', 213,
 'Headline: ''Intel and Commerce Department finalize $7.9 billion CHIPS Act grant''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +5.00%: A near-$8 billion grant is a lifeline for a struggling chipmaker, so shares should jump.', 'Falls -3.30%: The final grant of up to $7.865 billion is below the up to $8.5 billion in the preliminary deal, so investors may see a smaller boost.', 'Rises +0.80%: The money was widely expected, so the stock may barely change.',
 'b',
 'The stock fell 3.30% the following day (compared to the sector''s -1.30%).\nExplanation & Article Drivers: Commerce awarded Intel up to $7.865 billion in direct CHIPS Act funding, below the up to $8.5 billion in the March 2024 preliminary deal, partly because Intel also holds a $3 billion Defense Department contract funded from CHIPS money. The money is paid as milestones are completed. The stock fell 3.30% against a 1.30% sector decline, so it underperformed, and investors appeared to focus on the smaller award and the milestone conditions rather than the headline billions.\nRelated DIP Lesson: Lesson - Political: Lesson 2 (Government Grants & Subsidies)',
 1),

(214, 'geopolitical', 'real_news', 214,
 'Headline: ''Trump administration reportedly weighs 10% stake in Intel via CHIPS Act grants, making government top shareholder''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +5.00%: Making the US government the largest shareholder signals strong backing for Intel.', 'Falls -0.50%: The plan is only a report and may not happen, so the stock barely moves.', 'Falls -6.99%: Converting grants into an equity stake of about 10% could dilute existing shareholders and brings heavier government involvement.',
 'c',
 'The stock fell 6.99% the following day (against the sector''s -0.57%).\nExplanation & Article Drivers: The Trump administration was reported to be considering converting some or all of Intel''s 2022 CHIPS Act grants into an equity stake of about 10%, which would make the US government Intel''s largest shareholder and let taxpayers share in any upside. The stock fell 6.99% the next day while the sector fell only 0.57%, so the drop was clearly specific to Intel. Investors appeared to worry about what a government stake would mean for existing shareholders.\nRelated DIP Lesson: Lesson - Political: Lesson 5 (Governments as Big Buyers)',
 1),

(215, 'geopolitical', 'real_news', 215,
 'Headline: ''U.S. government takes 10% stake in Intel, as Trump expands control over private sector''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -1.01%: The government bought 433.3 million shares at $20.47 and holds a warrant for 5% more, so investors may worry about dilution.', 'Rises +6.00%: $8.9 billion from the government strengthens Intel''s finances, so the stock should jump.', 'Falls -5.50%: Government ownership means a loss of control, so a steep sell-off is likely.',
 'a',
 'The stock fell 1.01% the following day (compared to the sector''s -0.23%).\nExplanation & Article Drivers: The US government invested $8.9 billion in Intel common stock for a 10% stake, with $5.7 billion from unpaid CHIPS Act grants and $3.2 billion from a secure chips program. It gets no board seat and a warrant for 5% more if Intel stops majority-owning its foundry. The stock slipped 1.01% against a 0.23% sector dip, a slightly larger fall than the sector''s, suggesting the confirmed deal brought no fresh excitement.\nRelated DIP Lesson: Lesson - Political: Lesson 5 (Governments as Big Buyers)',
 1),

(216, 'geopolitical', 'real_news', 216,
 'Headline: ''Intel stock is up 50% over the last month, putting U.S. stake at $16 billion''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.00%: Momentum from the government stake may keep lifting the stock.', 'Falls -1.26%: After a roughly 50% climb in a month, investors may have taken profits.', 'Falls -7.00%: The rally has gone too far, so a sharp reversal is likely.',
 'b',
 'The stock fell 1.26% the following day (against the sector''s -0.61%).\nExplanation & Article Drivers: Intel shares rose about 50% in the month after the US government took a roughly 10% equity stake bought at $20.47 per share, lifting its value to about $16 billion per the headline. The article describes a climb of 3% on the news day, but this question concerns the following session. The stock fell 1.26% against a 0.61% sector fall, so it dipped about twice as much as the sector, and investors appeared to pause after a very large run.\nRelated DIP Lesson: Lesson - Political: Lesson 5 (Governments as Big Buyers)',
 1),

(217, 'geopolitical', 'real_news', 217,
 'Headline: ''Netherlands, home to a critical chip firm, follows U.S. with export curbs on semiconductor tools''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.00%: Dutch licence requirements follow US pressure and threaten China sales, so the slide continues.', 'Rises +6.00%: The curbs are narrow, so the stock should rebound strongly.', 'Rises +1.26%: The licence rule covers only the NXT:2000i and later models, so investors may have judged the damage as limited.',
 'c',
 'The stock rose 1.26% the following day (in line with the sector''s +0.89%).\nExplanation & Article Drivers: The Netherlands announced licence requirements for ASML''s most advanced immersion DUV tools, the NXT:2000i and later models, taking effect Sept. 1, after US pressure. ASML shares were down about 1.5% on the news day (a Friday). The following session saw a 1.26% rise, in line with a 0.89% sector gain, so the move looked mostly sector-driven, with investors appearing to judge the restriction as limited to the newest tools.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(218, 'geopolitical', 'real_news', 218,
 'Headline: ''ASML blocked from shipping some of its critical chipmaking tools to China''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -1.89%: Partial revocation of a licence for NXT:2050i and NXT:2100i systems closes another route to China sales.', 'Rises +2.50%: The revocation affected only a licence for 2023 shipments, so investors may see little change.', 'Falls -6.00%: Losing more China licences could cut a large part of ASML''s sales, so a steep drop is likely.',
 'a',
 'The stock fell 1.89% the following day (in line with the sector''s -2.15%).\nExplanation & Article Drivers: ASML confirmed the Dutch government had partially revoked a licence for its NXT:2050i and NXT:2100i DUV systems, following the US tightening of export controls in October 2023. The stock fell 1.89%, slightly less than the sector''s 2.15% decline, so the fall was largely sector-wide rather than specific to ASML.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(219, 'geopolitical', 'real_news', 219,
 'Headline: ''ASML shares pop 7% after report that U.S. will exempt allies from new China chip restrictions''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.50%: The reported exemption for allies lowers restriction risk, so the rally continues.', 'Falls -5.66%: A sharp sector sell-off outweighed the relief about the reported exemption for allies.', 'Falls -0.60%: The relief was already reflected in the 7% jump, so little change is likely.',
 'b',
 'The stock fell 5.66% the following day (compared to the sector''s -7.21%).\nExplanation & Article Drivers: Reuters reported the US would exclude allies such as Japan, the Netherlands and South Korea from an expanded foreign direct product rule on China chip tools, and ASML shares rose about 7% on that news day. This question is about the following session, when ASML fell 5.66% while the sector (SOXX) fell 7.21%. ASML actually fell less than the sector, so the sector drove the decline, and the article does not explain that drop.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(220, 'geopolitical', 'real_news', 220,
 'Headline: ''China and tariffs have wiped off $130 billion from critical chip firm ASML since peak value''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.00%: A $130 billion loss in market value shows lasting damage, so selling continues.', 'Rises +4.00%: The worst may be over, so shares rebound sharply.', 'Rises +0.07%: ASML has never been able to ship its most advanced machines to China, so a look back at past losses adds little new information.',
 'c',
 'The stock rose 0.07% the following day (compared to the sector''s +0.41%).\nExplanation & Article Drivers: ASML''s market value fell by more than $130 billion from its July 2024 peak, from about $429.5 billion to just under $297 billion, blamed on China export restrictions and US tariff uncertainty. The stock was almost flat the next day at 0.07%, below the sector''s 0.41% gain. The article looks back at past losses, and investors appeared to see little new information in it.\nRelated DIP Lesson: Lesson - Political: Lesson 4 (Tariffs & Trade Wars)',
 1),

(221, 'geopolitical', 'real_news', 221,
 'Headline: ''ASML shares fall after proposed U.S. export curbs target an already fragile China market''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +8.77%: The whole sector rallied strongly and ASML rose even more, despite the proposed MATCH Act.', 'Falls -4.00%: The bill could cut China off from DUV immersion machines, about 19% of system sales, so shares keep sliding.', 'Falls -1.00%: A bill is not law, so the stock slips only mildly.',
 'a',
 'The stock rose 8.77% the following day (compared to the sector''s +6.51%).\nExplanation & Article Drivers: A bipartisan group of US lawmakers introduced the MATCH Act, which could extend to ASML''s DUV immersion machines; China accounted for about 19% of ASML''s system sales. The headline says ASML fell on the news day, but this question is about the following session, when it rose 8.77% against a 6.51% sector gain. Most of the jump looked sector-driven, and since the proposal was a bill rather than law, investors appeared to look past it.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(222, 'geopolitical', 'real_news', 222,
 'Headline: ''China probes Micron for cybersecurity risks, urges Japan to stay out of US chip export curbs''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.50%: Micron said it was cooperating fully, so investors may expect a quick resolution.', 'Falls -0.44%: It was only a cybersecurity review, so the drop was mild and smaller than the sector''s.', 'Falls -6.00%: A probe tied to US export curbs could shut Micron out of China, so a steep drop is likely.',
 'b',
 'The stock fell 0.44% the following day (compared to the sector''s -1.73%).\nExplanation & Article Drivers: China''s Cyberspace Administration launched a cybersecurity review of Micron''s products sold in China, in a move seen as tied to US chip export curbs, and Micron said it was cooperating fully. The stock fell 0.44%, less than the sector''s 1.73% decline, so Micron held up better than the sector, and investors appeared to treat the review as an open question rather than a ban.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(223, 'geopolitical', 'real_news', 223,
 'Headline: ''China bans Micron chips in key infrastructure over ''national security'' risks''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.50%: The ban covers only critical infrastructure, so investors may see limited damage.', 'Falls -9.00%: The ban threatens all China sales, so a very steep drop is likely.', 'Falls -2.85%: A ban on critical infrastructure operators buying Micron products puts part of its China revenue, about 11% of 2022 sales, at risk.',
 'c',
 'The stock fell 2.85% the following day (against the sector''s +0.35%).\nExplanation & Article Drivers: China''s Cyberspace Administration said Micron products posed serious cybersecurity risks and barred operators of critical information infrastructure from buying them, without specifying the risk. China made up about 11% of Micron''s 2022 revenue of $30.8 billion, and Micron''s CEO later said about half of that was at risk. The stock fell 2.85% while the sector rose 0.35%, so the drop was specific to Micron and tied to its China exposure.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(224, 'geopolitical', 'real_news', 224,
 'Headline: ''U.S. finalizes more than $6.1 billion chips subsidy for Micron Technology''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.04%: A finalized subsidy of up to $6.165 billion supports roughly $125 billion of investment in New York and Idaho.', 'Falls -2.00%: Payments come only as milestones are met and the projects are huge, so investors may worry about delays.', 'Rises +12.00%: The subsidy is a windfall that transforms Micron''s finances.',
 'a',
 'The stock rose 4.04% the following day (compared to the sector''s +2.51%).\nExplanation & Article Drivers: Commerce finalized up to $6.165 billion in CHIPS Act funding for Micron: $4.6 billion for New York and $1.5 billion for Idaho, backing roughly $100 billion of investment in New York and $25 billion in Idaho and about 20,000 jobs, paid as milestones are met. The stock rose 4.04% against a 2.51% sector gain, so the sector lifted it, with Micron outperforming modestly as investors appeared to welcome the funding certainty.\nRelated DIP Lesson: Lesson - Political: Lesson 2 (Government Grants & Subsidies)',
 1),

(225, 'geopolitical', 'real_news', 225,
 'Headline: ''Micron to impose tariff-related surcharge on some products from April 9, sources say: Reuters''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.00%: A tariff-related surcharge signals higher costs and weaker demand.', 'Rises +18.81%: Chips themselves were exempted, so the surcharge touched only memory modules and solid-state drives, and the whole sector rallied.', 'Rises +3.00%: A modest bounce as the surcharge passes costs on to customers.',
 'b',
 'The stock rose 18.81% the following day (in line with the sector''s +18.57%).\nExplanation & Article Drivers: Micron planned a tariff-related surcharge from April 9 on some products. The tariffs applied to memory modules and solid-state drives while semiconductors themselves were exempted. The stock rose 18.81% the next day, almost exactly the sector''s 18.57% gain, so the sector drove the move and the surcharge itself appears to have mattered little to the price.\nRelated DIP Lesson: Lesson - Political: Lesson 4 (Tariffs & Trade Wars)',
 1),

(226, 'geopolitical', 'real_news', 226,
 'Headline: ''Micron to exit server chips business in China after ban, Reuters sources say''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.00%: Mainland China was $3.4 billion, or 12%, of last year''s revenue, so leaving that business hurts sales.', 'Falls -0.80%: The business had already been shrinking, so the exit changes little.', 'Rises +2.17%: Exiting a China server chip business that never recovered from the 2023 ban closes a long-running problem, and Micron keeps serving customers like Lenovo outside China.',
 'c',
 'The stock rose 2.17% the following day (compared to the sector''s +1.67%).\nExplanation & Article Drivers: Reuters reported Micron planned to stop supplying server chips to Chinese data centers after the business failed to recover from China''s 2023 ban, while still serving some customers with data center operations outside China, such as Lenovo. Mainland China was $3.4 billion, or 12%, of Micron''s last-year revenue. The stock rose 2.17% against a 1.67% sector gain, so most of the move was sector-driven, and investors appeared not to treat the exit as a major new blow.\nRelated DIP Lesson: Lesson - Political: Lesson 1 (Export Bans & Blacklists)',
 1),

(227, 'geopolitical', 'real_news', 227,
 'Headline: ''Samsung, SK Hynix get indefinite waivers to ship U.S. chip equipment to their China factories''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.71%: Indefinite waivers let Samsung keep shipping US-controlled equipment to its China factories, which hold about 40% of its NAND capacity.', 'Falls -2.50%: Samsung''s China plants stay under US scrutiny, so uncertainty remains.', 'Rises +9.00%: The waivers remove all risk from its China operations, so shares surge.',
 'a',
 'The stock rose 2.71% the following day (compared to the sector''s +0.75%).\nExplanation & Article Drivers: The US granted Samsung and SK Hynix indefinite waivers allowing them to ship US-controlled chipmaking equipment to their China factories without individual licenses; China hosts roughly 40% of Samsung''s NAND capacity. The stock rose 2.71% against a 0.75% sector gain, outperforming, as investors appeared to welcome the removal of uncertainty over their China plants.\nRelated DIP Lesson: Lesson - Political: Lesson 3 (Factory Location Risk)',
 1),

(228, 'geopolitical', 'real_news', 228,
 'Headline: ''U.S. to award Samsung up to $6.6 billion chip subsidy for Texas expansion: Reuters''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -2.50%: The figure was not final and the sector was falling, so the stock may follow it down.', 'Rises +0.60%: A reported CHIPS Act subsidy of up to $6.6 billion for the Texas expansion gave a small gain even as the sector fell.', 'Rises +5.00%: A multi-billion subsidy is a huge windfall, so shares should surge.',
 'b',
 'The stock rose 0.60% the following day (against the sector''s -1.83%).\nExplanation & Article Drivers: Reuters reported the US would award Samsung up to $6.6 billion in CHIPS Act subsidies for its Texas expansion; the later preliminary terms were up to $6.4 billion and the final award in December 2024 was up to $4.745 billion. The stock rose 0.60% while the sector fell 1.83%, so Samsung held up against a weak sector, which suggests investors saw the subsidy report as a positive.\nRelated DIP Lesson: Lesson - Political: Lesson 2 (Government Grants & Subsidies)',
 1),

(229, 'geopolitical', 'real_news', 229,
 'Headline: ''Trump''s ''100% chip tariffs'' hit Japan''s giants, but Samsung and TSMC rise on U.S. bets''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.50%: A roughly 100% chip tariff hits the whole industry, so Samsung should fall.', 'Falls -1.00%: Tariff uncertainty weighs on Asian chip stocks, so the stock slips mildly.', 'Rises +1.84%: South Korea''s trade envoy indicated Samsung and SK Hynix appeared exempt from the roughly 100% tariffs, and firms building in the US were exempt.',
 'c',
 'The stock rose 1.84% the following day (compared to the sector''s +0.84%).\nExplanation & Article Drivers: Asian chip stocks swung after Trump announced roughly 100% tariffs on imported semiconductors, with exemptions for companies building in the US, and South Korea''s trade envoy indicated Samsung and SK Hynix appeared exempt. The stock rose 1.84% against a 0.84% sector gain, so Samsung outperformed, with investors appearing to favour companies with US investments.\nRelated DIP Lesson: Lesson - Political: Lesson 4 (Tariffs & Trade Wars)',
 1),

(230, 'geopolitical', 'real_news', 230,
 'Headline: ''The U.S. makes it harder for TSMC, SK Hynix and Samsung to produce chips in China''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +0.43%: The Bureau of Industry and Security said it intends to license existing facilities, so operations continue even though expansion and upgrades are blocked.', 'Falls -3.50%: Losing validated end user status threatens the China plants, which hold about 40% of NAND capacity.', 'Rises +4.50%: The change is minor, so the stock should rally strongly.',
 'a',
 'The stock rose 0.43% the following day (against the sector''s +1.03%).\nExplanation & Article Drivers: The US removed validated end user status for Samsung and SK Hynix China memory plants and TSMC''s Nanjing fab, but the Bureau of Industry and Security said it intends to license operation of existing facilities, not capacity expansion or technology upgrades. Samsung relies on China for roughly 40% of its NAND capacity. The stock rose 0.43% but lagged the sector''s 1.03% gain, suggesting the news was a mild drag relative to the sector rather than a shock.\nRelated DIP Lesson: Lesson - Political: Lesson 3 (Factory Location Risk)',
 1),

(231, 'geopolitical', 'real_news', 231,
 'Headline: ''U.S. approves Samsung, SK Hynix chipmaking tool shipments to China for 2026: Reuters''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -2.00%: The approvals are only temporary relief, so uncertainty remains.', 'Rises +7.17%: Annual licenses for 2026 let Samsung bring equipment into its China facilities, keeping existing plants running.', 'Rises +1.00%: The relief is temporary, so only a small gain is justified.',
 'b',
 'The stock rose 7.17% the following day (against the sector''s -1.24%).\nExplanation & Article Drivers: The US granted Samsung and SK Hynix annual licenses to bring chipmaking equipment into their China facilities for 2026, replacing the revoked validated end user status, and the approvals were described as temporary relief that keeps existing plants running. The stock rose 7.17% while the sector fell 1.24%, so the jump was clearly specific to Samsung, though the article does not explain why the move was so large. Investors appeared to value the reduced uncertainty over the China plants.\nRelated DIP Lesson: Lesson - Political: Lesson 3 (Factory Location Risk)',
 1),

(301, 'earnings', 'real_news', 301,
 'Headline: ''Nvidia''s revenue triples as AI chip boom continues''\nConsidering this is a Earnings calls event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -2.46%: A big data center beat was already hoped for, and the warning about export limits gave buyers a reason to pause.', 'Rises +7.50%: Data center revenue far above the $12.97 billion consensus should send the shares sharply higher.', 'Falls -9.00%: Warnings about government sales limits could outweigh the strong quarter and trigger heavy selling.',
 'a',
 'The stock fell 2.46% the following day (against the sector''s +0.32%).\nExplanation & Article Drivers: Data center revenue of $14.51 billion beat the StreetAccount consensus of $12.97 billion by a wide margin, but executives also warned that government limits on sales to some countries would hurt results. The shares slipped while the sector edged up, so the dip looks company-specific, possibly because a strong report was largely expected and the export warning gave investors something to worry about.\nRelated DIP Lesson: Lesson - Earnings: Lesson 4 (Semiconductor-Specific Earnings Indicators)',
 1),

(302, 'earnings', 'real_news', 302,
 'Headline: ''Nvidia sales grow 78% on AI demand, company gives strong guidance''\nConsidering this is a Earnings calls event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +6.00%: Beating revenue and EPS estimates and guiding above expectations should lift the shares.', 'Falls -8.48%: A clean beat and strong guidance may not be enough when worries about AI spending and cheaper rival models weigh on the whole sector.', 'Rises +0.60%: The beat was expected and the shares were flat after hours, so only a tiny gain is likely.',
 'b',
 'The stock fell 8.48% the following day (compared to the sector''s -5.82%).\nExplanation & Article Drivers: Revenue and adjusted EPS both beat, and first-quarter guidance of about $43 billion topped the $41.78 billion expected, but the article notes shares were flat in extended trading amid DeepSeek and AI spending worries. The question is about the following session, when the stock fell, and the semiconductor sector fell sharply too, so group-wide worries probably played a big part. The stock''s drop was larger than the sector''s, which may point to extra caution around a richly valued leader.\nRelated DIP Lesson: Lesson - Earnings: Lesson 2 (Earnings Beats, Misses and Market Expectations)',
 1),

(303, 'earnings', 'real_news', 303,
 'Headline: ''Nvidia''s blowout earnings report disappoints Wall Street as stock sinks 5%''\nConsidering this is a Earnings calls event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -9.50%: The stalled OpenAI deal and sky-high expectations could trigger a much deeper selloff.', 'Rises +3.20%: A 75% jump in data center revenue that beat guidance should win investors over.', 'Falls -4.17%: Even blowout results can disappoint when expectations are sky-high and a major partnership deal is reported as stalled.',
 'c',
 'The stock fell 4.17% the following day (compared to the sector''s -1.26%).\nExplanation & Article Drivers: Data center revenue rose 75% to $62.3 billion and beat guidance, but investors pointed to the stalled $100 billion OpenAI deal as one pain point, so a very strong quarter may still have fallen short of what buyers hoped for. The headline cites a drop of about 5%, while measured close to close the following session the stock fell 4.17%, a bigger fall than the sector''s, which suggests company-specific disappointment.\nRelated DIP Lesson: Lesson - Earnings: Lesson 5 (From Earnings Calls to Stock-Price Reactions)',
 1),

(304, 'earnings', 'real_news', 304,
 'Headline: ''Nvidia earnings takeaways: Huang forecasts 70% fiscal 2028 revenue growth, far above estimates''\nConsidering this is a Earnings calls event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +8.74%: Guidance far above analyst estimates, not just a quarterly beat, can reset expectations for the year ahead and break a run of post-earnings pullbacks.', 'Falls -4.50%: After four straight post-earnings pullbacks, high expectations may lead to selling even on a beat.', 'Rises +1.20%: A beat is welcome but largely expected, so any gain should be small.',
 'a',
 'The stock rose 8.74% the following day (compared to the sector''s +1.95%).\nExplanation & Article Drivers: Guidance of about 70% growth in fiscal 2028 was far above the 44% analysts expected, and quarterly revenue of $96.22 billion also beat the $92.17 billion estimate. The stock gained far more than the sector, which suggests the guidance gap, rather than a broad chip rally, may have driven the move, especially after the shares had pulled back following the previous four reports.\nRelated DIP Lesson: Lesson - Earnings: Lesson 3 (Forward Guidance and Management Commentary)',
 1),

(305, 'earnings', 'real_news', 305,
 'Headline: ''World''s largest chipmaker TSMC sees biggest drop in profit in nearly five years''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.00%: A profit drop may already be expected, so a relief rally could follow once the numbers are out.', 'Falls -1.72%: A sharp profit decline and weak consumer electronics demand give investors a reason to trim, though the dip was no worse than a soft sector''s.', 'Falls -8.00%: The biggest profit decline in nearly five years could trigger heavy selling.',
 'b',
 'The stock fell 1.72% the following day (in line with the sector''s -1.45%).\nExplanation & Article Drivers: The report showed profit of NT$211 billion, the largest decline since the first quarter of 2019, with weak consumer electronics demand cited. The stock fell by about as much as the sector, so the move was mostly a group-wide reaction rather than a company-specific one. A modest fall for such a large profit drop hints that investors may have anticipated weak demand.\nRelated DIP Lesson: Lesson - Earnings: Lesson 1 (Understanding Earnings Reports and Earnings Calls)',
 1),

(306, 'earnings', 'real_news', 306,
 'Headline: ''Nvidia and Apple supplier TSMC shares pop after quarterly profit soars on AI demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
