 'Falls -4.20%: Paying about $700 million for a startup could raise worries about overpaying and integration distractions.', 'Rises +3.71%: A targeted purchase adds GPU workload management software to Nvidia''s DGX Cloud roadmap, a natural fit with its core AI business.', 'Rises +9.50%: Owning the software that manages GPU workloads opens a whole new revenue stream that investors will rush to price in.',
