 'The stock fell 2.82% the following day (compared to the sector''s -0.12%).\nExplanation & Article Drivers: This question is about the session after the announcement-day rise. The investment is staged as each gigawatt is deployed, with the first gigawatt planned for the second half of 2026, so the news may have been largely absorbed on the first day. The next-day fall was moderate, while the sector was close to flat.\nRelated DIP Lesson: Lesson - Corporate: Lesson 4 (Massive CapEx and Joint Ventures for Capacity Expansion)',
