 1),

(605, 'supply_chain', 'real_news', 605,
 'Headline: ''Nvidia locks down memory supply from SK Hynix as part of $500 billion AI deal''\nConsidering this is a Supply chain event, how do you expect this news to influence Nvidia''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.80%: Securing HBM supply for years removes a key bottleneck and should lift confidence in future GPU shipments.', 'Falls -4.99%: A deal this large locks in HBM supply but also commits Nvidia to a huge purchase bill, which investors may weigh against already high expectations.', 'Rises +0.40%: The deal is big, but supply agreements of this kind are usually expected, so the price may barely react.',
 'b',
 'The stock fell 4.99% the following day (compared to the sector''s -2.05%).\nExplanation & Article Drivers: Securing HBM is positive for supply, but the cost of a long-term commitment of this size may have raised questions about margins. The stock fell by more than twice the sector''s decline, which suggests company-specific factors on top of the weak chip tape. The headline date fell on a weekend, so the question refers to the next trading session.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(606, 'supply_chain', 'real_news', 606,
 'Headline: ''Apple supplier TSMC delays start of Arizona chip factory''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.20%: A delayed flagship U.S. fab could hurt relations with Apple and raise the final cost of the project.', 'Rises +2.60%: Slower overseas expansion keeps spending lower for now, which may support margins.', 'Falls -0.62%: The delay affects a future overseas site rather than current Taiwan output, so the near-term earnings effect may be small.',
 'c',
 'The stock fell 0.62% the following day (against the sector''s +0.90%).\nExplanation & Article Drivers: The Arizona fab is a future capacity project, and TSMC said it was sending trained technicians from Taiwan to speed up equipment installation. The stock slipped while the sector rose, so the move went against the broader chip tape and points to company-specific caution.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(607, 'supply_chain', 'real_news', 607,
 'Headline: ''TSMC warns AI chip crunch will last another 18 months''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -0.04%: Demand outrunning supply is already well understood, and an 18-month timeline may leave the share price almost unchanged.', 'Rises +2.80%: A supply crunch shows how strong AI demand is, and TSMC owns the scarce capacity.', 'Falls -3.10%: Being able to serve only about 80 percent of demand may mean lost sales for a year and a half.',
 'a',
 'The stock fell 0.04% the following day (in line with the sector''s -0.06%).\nExplanation & Article Drivers: The chairman''s message was that silicon was ready but advanced packaging was the limit, and the expected 18-month relief gave a clear timeline. TSMC barely moved and the sector barely moved, so the market seems to have treated the comment as a known capacity story.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure)',
 1),

(608, 'supply_chain', 'real_news', 608,
 'Headline: ''TSMC evacuated fabs after M7.4 earthquake hit Taiwan''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -6.20%: A major quake near the world''s most advanced fabs could halt chip output for weeks.', 'Falls -1.65%: TSMC reported no damage to critical tools, so the risk may be seen as contained, though Taiwan concentration remains a worry.', 'Rises +1.80%: No tool damage means little real impact, so the stock may bounce as fears fade.',
 'b',
 'The stock fell 1.65% the following day (compared to the sector''s -2.83%).\nExplanation & Article Drivers: Investors may have first worried about how much of the world''s advanced chip supply sits in one earthquake zone. TSMC''s statement that critical tools were undamaged limited the concern, and the stock fell by less than the sector''s sharper decline. The question concerns the following session.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(609, 'supply_chain', 'real_news', 609,
 'Headline: ''TSMC pauses production after strong earthquake hits Taiwan''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.00%: A production pause at the key AI chip foundry could delay shipments across the whole chain.', 'Falls -0.90%: Tool recalibration may reduce yields for some time and raise costs.', 'Rises +2.06%: Inspections were complete and operations were resuming, so the disruption may be seen as brief and manageable.',
 'c',
 'The stock rose 2.06% the following day (compared to the sector''s +1.44%).\nExplanation & Article Drivers: The company said structural inspections were finished at all sites, which could reassure investors that damage was limited. The stock rose a little more than the sector''s gain, so the recovery in confidence seems to have been partly specific to TSMC.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(610, 'supply_chain', 'real_news', 610,
 'Headline: ''January earthquake shook $165M off TSMC’s revenue forecast''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -1.13%: A loss of about 165 million dollars is small relative to TSMC''s overall revenue, but a stock can still dip when a cost is confirmed.', 'Falls -4.50%: Admitting a revenue hit from an earthquake could raise fears of larger losses ahead.', 'Rises +2.30%: A small, quantified loss removes uncertainty, so investors may buy the dip.',
 'a',
 'The stock fell 1.13% the following day (against the sector''s +0.11%).\nExplanation & Article Drivers: The cost was small compared with TSMC''s overall production, and the company promised the production schedule would get back on track, so the effect on earnings looks limited. The stock fell while the sector edged up, which points to a small company-specific reaction to the confirmed revenue loss.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Financial Metrics & Semiconductor Company Analysis)',
 1),

(611, 'supply_chain', 'real_news', 611,
 'Headline: ''ASML ships another high NA EUV lithography machine to mystery client''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.40%: Each High-NA machine is a roughly 300 to 400 million dollar sale and shows ASML''s technology lead.', 'Falls -2.05%: Progress on High-NA is good for ASML, but one more shipment to an unnamed customer is not new information, and the sector was falling.', 'Falls -5.80%: Shipping to an unnamed customer may hint that few buyers can afford the new tools.',
 'b',
 'The stock fell 2.05% the following day (in line with the sector''s -1.77%).\nExplanation & Article Drivers: Each High-NA scanner carries a price in the hundreds of millions of dollars, but a second shipment mostly confirms an expected rollout. ASML fell with the sector, only slightly more, so the move seems to reflect the broad chip decline rather than the shipment.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure)',
 1),

(612, 'supply_chain', 'real_news', 612,
 'Headline: ''ASML share plunge wipes over $50 billion off Dutch chip giant''s value''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +2.50%: After a 12 percent same-day drop, buyers may rush in for a rebound.', 'Falls -1.00%: The bad news was published and priced in on the first day, so the next day should be calm.', 'Falls -6.42%: Bookings less than half of consensus and a lowered 2025 outlook meant expectations had to be reset, and the fall may have continued the next day.',
 'c',
 'The stock fell 6.42% the following day (compared to the sector''s +0.00%).\nExplanation & Article Drivers: The early release showed bookings far below what analysts had expected and a 2025 range pointing to the lower half of earlier guidance, which hurts a stock priced for growth. The stock fell about 6.4% in the next session while the sector was flat, so the decline was specific to ASML.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 5 (Valuation, Expectations & Semiconductor Stock Prices)',
 1),

(613, 'supply_chain', 'real_news', 613,
 'Headline: ''ASML faces turbulence amid stock drop, customer delays''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +0.95%: After the large earlier drop, an expectation that China would still supply about 20 percent of 2025 revenue may have steadied the price.', 'Falls -5.00%: Customer delays from Intel and Samsung suggest the equipment order slowdown could continue.', 'Falls -1.90%: Continued export restrictions on China could trim future sales.',
 'a',
 'The stock rose 0.95% the following day (against the sector''s -0.37%).\nExplanation & Article Drivers: The article linked the weak orders to a small group of customers, including Intel and Samsung, but also said ASML expected Beijing sales to bounce. The stock rose slightly while the sector slipped, so the modest rebound seems specific to ASML.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Supply, Demand & Inventory)',
 1),

(614, 'supply_chain', 'real_news', 614,
 'Headline: ''Intel delays Ohio fab build, blames semiconductor slowdown''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.30%: A delayed Ohio fab suggests Intel''s foundry plan is slipping and demand is weaker than hoped.', 'Rises +0.40%: Delaying a large factory could save near-term capital spending, which may offset worry about falling behind in capacity.', 'Falls -1.70%: Waiting for CHIPS Act money may show that Intel cannot fund the expansion alone.',
 'b',
 'The stock rose 0.40% the following day (compared to the sector''s +1.37%).\nExplanation & Article Drivers: Intel tied the delay to weak market conditions and late subsidy money, so a later build may also mean lower near-term capital spending. The stock rose slightly while the sector rose more, so the small gain may reflect the broad chip rally more than the news.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Financial Metrics & Semiconductor Company Analysis)',
 1),

(615, 'supply_chain', 'real_news', 615,
 'Headline: ''Intel slows its roll on $28B Ohio fab expansion, pushing production to 2030s''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.60%: Cutting capital spending protects cash flow, so investors may welcome the slower pace.', 'Falls -0.20%: Delays were already known, so the news should barely register.', 'Falls -4.17%: A delay of this size may have raised doubts about Intel''s foundry plan, and the stock fell more than the sector.',
 'c',
 'The stock fell 4.17% the following day (compared to the sector''s -3.53%).\nExplanation & Article Drivers: Intel moved Ohio production to 2030 or later in order to align capital spending with demand, which protects cash but pushes back its foundry ambitions. The stock fell slightly more than the sector, suggesting a modest company-specific penalty on top of a weak chip day.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Financial Metrics & Semiconductor Company Analysis)',
 1),

(616, 'supply_chain', 'real_news', 616,
 'Headline: ''Intel puts consumer chip production on back burner as datacenters make a run on Xeons''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -5.72%: Admitting a demand misjudgement and a shortage of client chips may have worried investors, and the stock fell far more than the sector.', 'Rises +2.90%: Strong datacenter demand and a shift to higher-margin Xeon parts should lift earnings.', 'Rises +0.30%: The CFO said foundry capacity should improve from Q2, so the news may be neutral.',
 'a',
 'The stock fell 5.72% the following day (compared to the sector''s -0.48%).\nExplanation & Article Drivers: The CFO said Intel had misjudged datacenter demand and moved capacity to Xeons, leaving consumer chips short, which may have raised concerns about lost PC sales. The decline was far larger than the sector''s, which points to company-specific factors.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Supply, Demand & Inventory)',
 1),

(617, 'supply_chain', 'real_news', 617,
 'Headline: ''AMD climbs in desktop and server CPUs while Intel battles supply squeeze''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.20%: Intel''s supply squeeze may hand AMD a lasting lead in both PCs and servers.', 'Falls -1.30%: Losing market share to AMD while supply is short could worry investors, though the move was modest.', 'Rises +2.10%: Strong server chip demand for Intel Xeons outweighs losses in PCs.',
 'b',
 'The stock fell 1.30% the following day (compared to the sector''s -0.16%).\nExplanation & Article Drivers: Share gains for AMD were tied to Intel''s choice to move capacity toward server chips, so Intel''s supply problem seems to have a direct competitive cost. The stock fell a little more than the sector, so the reaction was modest.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(618, 'supply_chain', 'real_news', 618,
 'Headline: ''Intel begins production of most-advanced chip, inching closer to possible Apple deal''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.80%: Early production does not guarantee a customer, and Intel had not confirmed any Apple deal.', 'Rises +0.20%: Process node milestones are routinely announced and rarely change the share price.', 'Rises +3.46%: An advanced node reaching production, together with talk of an Apple foundry deal, could support hopes for Intel''s manufacturing business.',
 'c',
 'The stock rose 3.46% the following day (compared to the sector''s +1.44%).\nExplanation & Article Drivers: The 18A-P process was entering early production, and the report of a possible Apple deal had not been confirmed, so some of the move may reflect hope rather than a signed customer. The stock rose by more than twice the sector''s gain, which points to company-specific optimism.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure)',
 1),

(619, 'supply_chain', 'real_news', 619,
 'Headline: ''Micron bounces back as AI drives up memory prices''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +0.33%: Strong results were expected after a big run-up, so a very small move may be the market''s reaction.', 'Falls -4.80%: A sold-out product could be seen as a peak, and investors may sell the news.', 'Rises +5.10%: Returning to profit with a sold-out HBM line should send the stock sharply higher.',
 'a',
 'The stock rose 0.33% the following day (in line with the sector''s +0.12%).\nExplanation & Article Drivers: Micron''s recovery and its sold-out HBM product show a memory cycle turning up. The stock moved only a little more than the sector, so the good news may have been reflected in the price before the next session.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Supply, Demand & Inventory)',
 1),

(620, 'supply_chain', 'real_news', 620,
 'Headline: ''Micron close to selling all the high-bandwidth memory it will make in 2026''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +4.20%: A sold-out 2026 with pricing already agreed should lift the stock.', 'Falls -3.02%: After a strong run, good results and a nearly sold-out 2026 may not be enough, and investors may take profits.', 'Rises +0.30%: Results and guidance were in line, so the stock barely moves.',
 'b',
 'The stock fell 3.02% the following day (compared to the sector''s -0.32%).\nExplanation & Article Drivers: The Register highlighted high demand, DRAM shortages and soaring margins, yet the shares fell the next day while the sector slipped only slightly, which suggests investors judged the results against very high expectations.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 5 (Valuation, Expectations & Semiconductor Stock Prices)',
 1),

(621, 'supply_chain', 'real_news', 621,
 'Headline: ''AI memory is sold out, causing an unprecedented surge in prices''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.70%: A price surge this large might mean the cycle is close to a peak.', 'Rises +4.50%: Sold-out memory and rising prices should send Micron sharply higher.', 'Rises +0.23%: Higher prices help Micron, but the news was a general market story and the sector gained more, so the reaction was small.',
 'c',
 'The stock rose 0.23% the following day (in line with the sector''s +0.48%).\nExplanation & Article Drivers: The article described a shortage that benefits the three main memory vendors, including Micron, SK Hynix and Samsung. Because it covered the whole memory market rather than one company, the stock rose only a little, less than the sector. The headline date fell on a weekend, so the question refers to the next trading session.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Supply, Demand & Inventory)',
 1),

(622, 'supply_chain', 'real_news', 622,
 'Headline: ''Micron CEO says it can''t deliver enough memory to key customers after blowout earnings''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.81%: After a rise of more than 350 percent in a year, even blowout results and a supply shortage may leave little room for good surprises.', 'Rises +2.40%: Revenue nearly tripling and strong demand should send the stock higher.', 'Falls -0.30%: The shortage was widely known, so the news is mostly neutral.',
 'a',
 'The stock fell 4.81% the following day (compared to the sector''s -2.26%).\nExplanation & Article Drivers: Micron''s stock had risen by more than 350% over the prior year, so investors may have judged even a blowout quarter against very high expectations. Not being able to meet customer demand can also limit sales. The stock fell by about double the sector''s drop on the following day.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 5 (Valuation, Expectations & Semiconductor Stock Prices)',
 1),

(623, 'supply_chain', 'real_news', 623,
 'Headline: ''Samsung Electronics to make ''meaningful'' cut to chip production in effort to support prices''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.60%: A 96 percent profit drop is far worse than analysts hoped and may hurt the stock.', 'Rises +1.08%: Production cuts to support prices may be read as a step toward ending the glut, which could help the stock despite poor profit.', 'Falls -0.10%: Both the cut and the loss were expected, so the shares barely react.',
 'b',
 'The stock rose 1.08% the following day (compared to the sector''s +1.77%).\nExplanation & Article Drivers: Samsung''s cut was aimed at excess inventory and falling prices, and the market may have treated the cut as the start of the recovery instead of focusing on the bad quarter. The stock rose, but by less than the sector, so the broader market lift explains much of the move.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Supply, Demand & Inventory)',
 1),

(624, 'supply_chain', 'real_news', 624,
 'Headline: ''Samsung extends cut in memory chip production, will focus on high-end AI chips instead''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.80%: Cutting supply and focusing on AI chips should help the memory market recover.', 'Rises +0.20%: The cuts were extended as expected, so the stock does not change.', 'Falls -1.53%: Extending the cuts admits that the inventory problem is lasting, and the stock lagged a rising sector.',
 'c',
 'The stock fell 1.53% the following day (against the sector''s +2.18%).\nExplanation & Article Drivers: Samsung extended cuts to clear inventory after a large loss in memory and said it would focus on HBM. The shares fell while the sector rose by more than 2%, so the market seems to have focused on the length of the downturn instead of the plan.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Supply, Demand & Inventory)',
 1),

(625, 'supply_chain', 'real_news', 625,
 'Headline: ''Samsung''s HBM chips reportedly fail Nvidia tests due to heat and power consumption woes''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.71%: The failed test took place in April and Samsung''s struggle in HBM was a continuing story, so the stock may simply have tracked the sector.', 'Falls -4.50%: Failing the tests at Nvidia, the biggest buyer of HBM, could hurt Samsung''s AI memory plans.', 'Falls -1.60%: Heat and power problems may delay Samsung''s HBM3E revenue.',
 'a',
 'The stock rose 1.71% the following day (in line with the sector''s +1.69%).\nExplanation & Article Drivers: The report said both chip versions failed Nvidia''s test, which on its face is negative for Samsung''s HBM ambitions. The stock instead moved up by almost the same amount as the sector, so the sector rise appears to have outweighed any company-specific concern.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(626, 'supply_chain', 'real_news', 626,
 'Headline: ''Samsung''s 8-layer HBM3E chips clear Nvidia''s tests for use, Reuters reports''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.50%: Passing Nvidia''s tests opens a large HBM sales channel and should lift the stock.', 'Falls -1.74%: Samsung''s shares may have slipped despite the good news, because only the 8-layer version has passed and the 12-layer one has not.', 'Rises +7.80%: Passing the tests plus a sector rebound should send Samsung sharply higher.',
 'b',
 'The stock fell 1.74% the following day (against the sector''s +6.90%).\nExplanation & Article Drivers: Passing Nvidia''s 8-layer test was good news, but the 12-layer version had not yet passed. The sector jumped sharply while Samsung''s shares fell, so the stock went against the broad rebound and may have been held back by the unfinished 12-layer approval.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks)',
 1),

(627, 'supply_chain', 'real_news', 627,
 'Headline: ''Samsung expects second-quarter profits to more than halve as it struggles to capture AI demand''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.80%: A 56 percent profit drop reflects falling share in the most profitable memory segment.', 'Rises +2.20%: A preliminary guide often marks a low point, so investors may look past it.', 'Falls -1.63%: A big profit fall that was partly expected may be priced in, but the lag in AI memory kept the stock under pressure.',
 'c',
 'The stock fell 1.63% the following day (against the sector''s +0.32%).\nExplanation & Article Drivers: Samsung lagged rivals in supplying AI memory, which cut into profit, and the stock fell the following day while the sector rose slightly. The decline points to company-specific concern about its AI memory position.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Financial Metrics & Semiconductor Company Analysis)',
 1)
