-- =====================================================================
-- IMPORTED LESSON CONTENT — from the 5 uploaded PDFs (DIP stuff*.pdf)
-- Each category now has 5 concepts as separate rows (corporate has 4 --
-- the source PDF's "Lesson 3: Capital Allocation" was a verbatim
-- duplicate of Lesson 2, so it was not imported twice; see chat).
-- ids 1-5 (the original one-per-category placeholder lessons) are
-- replaced here with "Lesson 1" of each category's real content; ids
-- 6-24 are the remaining concepts. lessons.php should query
-- WHERE category = ? ORDER BY sort_order so a specific concept can be
-- shown on its own.
-- =====================================================================
INSERT INTO lessons (id, category, title, body_html, sort_order) VALUES
(1, 'geopolitical', 'Export Bans & Blacklists',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/geopolitical-1.svg" alt="A crate of chips rolls toward a striped gate with a no-entry sign, gets stamped BANNED, and the China sales bar on a chart drops." loading="lazy" width="640" height="260"><figcaption>One export ban can wipe out a big slice of sales overnight.</figcaption></figure><p class="lesson-lead">Most business problems take months to show up in the numbers. An export ban can erase a customer base in a single afternoon, and the stock price usually reacts the next trading day.</p><h4>Why Chips Are Treated Like Weapons</h4><p>The best place to begin is <strong>national security</strong>. The same advanced chip that trains a chatbot in a data center can also help guide a missile or sift through intelligence data, so governments no longer treat chips as ordinary consumer goods. The country that designs and builds the best ones gains a lever over everyone who wants to buy them, and it can decide when to pull that lever.</p><p>The lever is called an <strong>export ban</strong>, and it is often paired with a <strong>blacklist</strong>, which is a published list of named companies that domestic firms may not sell to. Imagine a shop that is told by law it cannot sell its best product to certain customers, however much cash they offer. Selling anyway risks heavy fines and the loss of government licences, so in practice companies comply, and the blacklisted customers simply vanish from the order book.</p><p>What makes this different from a normal business problem is the <strong>sudden shock</strong>. A weak quarter is usually visible long before the results are published: orders slow, stock piles up, and analysts trim their forecasts one small step at a time. A ban is written in a single document and can be published overnight, cutting off millions of customers at once. Investors have no time to ease out of the stock gradually, so the price tends to gap on the first trading day, which means it opens far away from where it closed the evening before.</p><p class="lesson-formula">New rule &rarr; customers cut off &rarr; sales forecast falls &rarr; share price repriced</p><p>That flow is worth remembering because almost every ban story follows it. The rule appears, customers in the affected country are cut off, analysts lower the sales forecast, and the share price adjusts to the smaller profit expected in the future. A share price is always a bet on future profit, so a rule that changes the future changes the price straight away, even though no sale has actually been lost yet.</p><h4>How an Export Ban Pushes Stocks Down</h4><p>The most direct route is <strong>lost sales</strong>. If a company is banned from a major market such as China, somewhere between 15% and 20% of its sales can vanish in a single day. Profit is what remains after fixed costs such as research and factories are paid, so losing a slice of revenue usually removes an even larger slice of profit. That is why the market reacts so sharply to what looks like a modest percentage of sales.</p><p>The second route is <strong>canceled orders</strong>. Companies that make chip-making machines build each one to order, and each machine is enormously expensive. If the customer is suddenly not allowed to receive it, a delivery that was already scheduled, and already counted in the maker''s forecast, gets canceled. A half-built machine with no legal buyer is a stranded asset, and investors price that in quickly.</p><p>The third route is <strong>extra redesign costs</strong>. A chip company can try to stay in the market by building a weaker, deliberately &quot;downgraded&quot; version that sits just under the legal performance limit. That keeps some customers, but engineers must be paid, the new product must be tested, and it sells for less than the original. It is a bit like a restaurant being told it cannot serve its signature dish in one neighbourhood, so it spends weeks inventing a cheaper dish for that neighbourhood alone.</p><p>A tightening of the rules can bring all three problems arriving together. If the performance limit is lowered far enough, even the modified chips built for the restricted market fall inside the ban, so the earlier workaround is wiped out and a second redesign becomes necessary.</p><p>One useful clue is the gap between a stock and its sector. When a stock drops much more than its sector, the bad news is specific to that company rather than a general mood in the market. That gap is a useful clue that the ban itself, and not a broad selloff, was doing most of the work.</p><h4>When the Rules Loosen: How Easing Pushes Stocks Up</h4><p>Policy can move in the other direction too, and the market responds to relief just as it responds to restriction. A <strong>special permit</strong>, meaning a temporary licence or waiver that lets a company keep selling, is the clearest example. Nothing new was sold on the day the waiver was granted, yet the future suddenly became easier to predict. Investors dislike uncertainty, so removing a threat can lift a price even if profits have not changed at all.</p><p>TSMC''s operations in China are a good case. A one-year US waiver allowed the company to keep shipping equipment to its Nanjing fab, which reassured investors that cash from older-generation production there would keep flowing without a sudden halt.</p><p>A stock can go up on news like this and still trail its peers, which makes it a relative loser, and that is why this course always shows the sector move beside the stock move.</p><p>A second kind of relief comes from <strong>new compliant products</strong>. When a company launches a chip designed to follow the rules, the sales it had assumed were lost can begin to return, and the price can recover gradually over weeks rather than in one day.</p><p>The third effect is <strong>domestic replacements</strong>. A ban often pushes local businesses and militaries in the targeted country to buy more homegrown chips, which can help local chipmakers even while the foreign seller suffers. For an investor this means a single policy can create winners and losers on opposite sides of a border.</p><h4>The Semiconductor Sector in Practice</h4><p>The most followed example is Nvidia''s AI chips and China. When the US government banned the sale of its most powerful AI chips there, the stock initially dropped as investors panicked about the lost revenue, exactly as the lost-sales and redesign problems above would suggest. Nvidia then designed modified chips for the Chinese market that stayed within the legal limits, and the stock was able to recover. The story has a recognisable shape: shock, fall, workaround, recovery, and sometimes a fresh rule that restarts the whole cycle.</p><p>When you read a ban headline, there are three questions worth asking. How much of the company''s revenue goes to the banned market? Can that supply be sold to someone else instead? And how quickly can a compliant version be built? A company with a small share of sales in the affected market and plenty of other buyers will barely flinch, while a company that depends heavily on that market can lose a large share of its value in a day.</p><p>This is also why ban news matters beyond a single company. Chip designers, equipment makers and the customers that rely on them are linked in a chain, so a rule aimed at one link tends to ripple through the others. Reading the exact scope of a rule, meaning which products and which customers it covers, is more useful than reading only the headline.</p><h4>Recent Headlines in Practice</h4><p>Across the new headlines, export rules hurt most when they hit a market a company still depends on, and the size of the reaction depends on how much revenue is exposed and how long the uncertainty lasts. Nvidia fell after the October 2023 rules closed the A800 and H800 loophole, then fell again when the H20 license requirement arrived with a $5.5 billion charge in April 2025. Micron was a different case: China barred its chips from critical infrastructure in May 2023, and by October 2025 the company was reported to be leaving the China server chip business altogether. Samsung''s China plants show the other side: the December 2025 annual licenses were followed by a jump of more than 7%. In each case, investors appeared to ask how much of the business a rule could remove and whether a license or workaround could restore it.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Nvidia &middot; 17 Oct 2023</p><p class="news-callout-headline">Nvidia stock falls after U.S. announces new restrictions on AI chip exports</p><p>The Commerce Department tightened the rules to close the loophole around Nvidia''s China-specific A800 and H800 chips, and Nvidia said the curbs also cover the A100, H100, L40, L40S and RTX 4090. Even though Nvidia said it did not expect a near-term meaningful impact, the stock fell about twice as much as the sector the next day, as investors appeared to weigh the lost China sales.</p><p class="news-callout-move">Next day: stock -3.96% vs sector (SOXX) -1.80%</p><a class="news-callout-link" href="https://www.cnbc.com/2023/10/17/nvidia-stock-falls-after-us-announces-new-chip-export-restrictions.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Export bans hit chip stocks fast because they remove customers overnight, cancel orders and add redesign costs. Waivers and compliant new products ease the pain, and the size of the move depends on how much revenue sits in the banned market and how quickly the company can adapt.</p></div>',
 1),

(6, 'geopolitical', 'Government Grants & Subsidies',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/geopolitical-2.svg" alt="Coins fly from a government building labelled Grants into a new chip factory while an orange arrow points upward." loading="lazy" width="640" height="260"><figcaption>Government grants make building a fab cheaper, and investors cheer.</figcaption></figure><p class="lesson-lead">A modern chip factory can cost more than an aircraft carrier. When governments offer to help pay, the stock market has to decide whether free money is a gift or a leash.</p><h4>Why Governments Pay for Factories</h4><p>Start with the <strong>cost problem</strong>. A single modern chip factory, often called a fab, costs over $15 billion, which is more than an aircraft carrier, and that money is spent years before the first chip is sold. Few companies in the world can carry a bill like that on their own, and fewer still can afford to build several. When a project needs this much cash, the way it is financed matters almost as much as the technology inside it.</p><p>That is where <strong>government checks</strong> come in. Countries learned during supply crises that running out of chips can stall car factories, hospitals and defense programs, so many of them now give billions of dollars in grants and tax cuts to companies willing to build factories on their own soil. In plain terms, taxpayers pay part of the construction bill in exchange for chips being made closer to home.</p><p>The financial benefit is <strong>cheaper expansion</strong>. Government aid means a chip company does not have to borrow as much or spend as much of its own cash to grow. Less debt means lower interest payments, and more cash left over for research and new products. A grant works a bit like a parent covering part of a student''s tuition: the student still has to do the work, but the loan at the end of it is much smaller.</p><p class="lesson-formula">Fab cost &minus; government grant = cash the company must raise itself</p><p>The formula above is the mental shortcut for this whole lesson. The bigger the grant is compared with the fab cost, the less the company has to raise itself, and the lower the pressure on its balance sheet. Investors therefore read every subsidy announcement by asking one thing first: how big is the check compared with the size of the project?</p><h4>How Delays and Strict Rules Push Stocks Down</h4><p>Grants are not free in the way a gift is free. Many come with <strong>strings attached</strong>, such as limits on share buybacks or a requirement to share unexpectedly large profits with the state. A company that must keep spending on matching investment, or that cannot return cash to shareholders, may look less attractive even though it received money. The headline number is only one half of the deal.</p><p>A second problem is <strong>bureaucratic delays</strong>. Grants are paid out in stages as milestones are met, so if politics or paperwork slows a payment, the company has to pause construction or use its own expensive cash to keep going. Every month a half-built factory sits idle is a month of costs with no revenue, and investors tend to mark the stock down when schedules slip.</p><p>The third worry is <strong>oversupply fears</strong>. If every country subsidises factories at the same time, the world could end up with more chips than it needs. When supply outruns demand, prices fall, and lower prices squeeze the profits of every chipmaker, including those that did not receive a subsidy. A subsidy for one company can therefore be bad news for its competitors.</p><p>A large check can still be met with a falling share price. Imagine a grant that requires large matching spending, arrives while end markets are soft, and comes with a risk that the new fab''s start date slips. Investors in that situation focus on the other half of the story, and execution risk can outweigh the gift. If the stock falls while its sector rises, that is a sign the market is not simply wobbling, and that the conditions attached to the money are doing the work.</p><h4>How Subsidy Announcements Push Stocks Up</h4><p>When a subsidy is a pleasant surprise, the effects are mostly positive. The first is <strong>free cash</strong>: receiving billions in direct grants cuts a company''s building costs, which protects its bank account and its future profit. Lower costs on the same revenue mean a wider profit margin, and that is what investors pay for.</p><p>The second effect is <strong>guaranteed customers</strong>. Laws that fund factories often expect local government agencies and defense programs to buy from those new factories, so some demand is lined up before a single wall is built. That lowers the risk of building a plant that no one wants to buy from, which is the nightmare scenario in any capital-heavy business.</p><p>The third is <strong>investor confidence</strong>. A government seal of approval signals that a company is seen as too important to fail, and that can reduce the extra return investors demand for holding its shares. A grant that arrives together with a loan facility shows this combination of cheaper building costs and locked-in customers.</p><p>Federal co-funding lowers the cost of building abroad and helps secure orders from large American customers, which is why a well-received award can help a stock beat its sector.</p><h4>The CHIPS Act and the Expected Surprise Problem</h4><p>The real-world anchor for all of this is the US CHIPS Act, a $52 billion programme to bring chip manufacturing back to America. As companies such as Intel, TSMC and Micron were awarded billions of dollars to build factories in places like Arizona and Ohio, investors bought shares, excited by the free financial backing. The rally was real, but it was not evenly spread across every company or every announcement.</p><p>The reason is that markets move on surprises, not on news itself. If investors already expected a grant, then the announcement only confirms what the price already assumed, and the stock may barely move. An award can be large and still widely anticipated, in which case the stock may gain only slightly and trail its sector.</p><p>Even a big award can be met with wariness about heavy matching spending and long construction timelines. The reaction to any subsidy depends on three questions: how large the award is compared with expectations, what conditions come with it, and how soon the factory can start making money.</p><p>So the practical lesson is to read a subsidy headline in two steps. First, ask whether the size was a surprise. Second, ask whether the strings and the schedule leave the company better off than before. A grant that fails either test can be absorbed quietly or even sold.</p><h4>Recent Headlines in Practice</h4><p>The newer subsidy headlines show that a grant tends to help a stock most when it is concrete, funded and tied to real factories. Micron''s finalized award of up to $6.165 billion, backing roughly $125 billion of investment in New York and Idaho, was followed by a gain that beat the sector. TSMC''s Arizona package, with up to $6.6 billion in grants and about $5 billion in loans, also rose more than the sector the next day. Intel''s final grant tells a more cautious story: at up to $7.865 billion it was below the earlier preliminary figure of up to $8.5 billion, and the stock fell more than the sector. So investors seemed to compare each award with what they expected, and to look at the conditions, such as milestone payments, before deciding how much the money was really worth.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Micron &middot; 10 Dec 2024</p><p class="news-callout-headline">U.S. finalizes more than $6.1 billion chips subsidy for Micron Technology</p><p>Commerce finalized up to $6.165 billion in CHIPS Act funding for Micron, with $4.6 billion for New York and $1.5 billion for Idaho, paid as milestones are met. The stock rose more than the sector the next day, as investors appeared to welcome the funding certainty for a large US build-out.</p><p class="news-callout-move">Next day: stock +4.04% vs sector (SOXX) +2.51%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/12/10/us-finalizes-more-than-6point1-billion-chips-subsidy-for-micron-technology.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Subsidies cut a chip company''s building costs and signal government backing, which usually helps its stock. The reaction depends on whether the news was expected, what strings are attached, and whether the factory can be delivered on schedule, so a big check does not guarantee a rising share price.</p></div>',
 2),

(7, 'geopolitical', 'Factory Location Risk',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/geopolitical-3.svg" alt="Warning ripples pulse around a chip factory on the island of Taiwan while a dotted route leads to a backup fab whose windows light up." loading="lazy" width="640" height="260"><figcaption>Too many chips come from one island, so backup fabs calm investors.</figcaption></figure><p class="lesson-lead">Imagine most of the world''s smartphones, AI servers and cars depending on factories on a single island. That is the situation in advanced chipmaking, and it is why a speech or a military drill can move share prices.</p><h4>One Small Island, One Big Bottleneck</h4><p>Look at where advanced chips are actually made and a striking pattern appears. More than 90% of the world''s most advanced chips are produced in Taiwan, and most of them by a single company: TSMC. This <strong>one small island</strong> concentration is unusual. Most industries spread production across many countries, but advanced chipmaking grew up in one place because the skills, suppliers and equipment all clustered there.</p><p>That creates a <strong>bottleneck</strong>. Almost every technology giant, including Apple, Nvidia, AMD and Qualcomm, designs its own chips but relies on Taiwanese factories to manufacture them. A bottleneck is the narrow neck of a bottle: no matter how much is inside, everything has to pass through that one point. If something goes wrong in Taiwan, designers elsewhere cannot simply switch factories next week, because no other factory can make the same chips at the same quality.</p><p>The risk is made sharper by geography and politics. China claims Taiwan as its territory, so a <strong>major flashpoint</strong> exists: any military threat in the region puts the world''s chip supply in question. This matters to investors even in peacetime. They do not need a war to react, only a higher chance of disruption, because a share price already reflects the probability of bad things happening, not just the bad things that have happened.</p><p class="lesson-formula">Higher tension &rarr; higher chance of a shutdown &rarr; bigger fear discount on the stock</p><p>The formula above introduces the <strong>fear discount</strong>, which is the lower price investors pay for shares when the risk of disaster rises. It is like a house in a region that might flood: the house is still standing, but buyers will only pay less for it until they feel safer.</p><h4>How War Fears Push Stocks Down</h4><p>The fear discount shows up whenever military drills or hostile political speeches happen around Taiwan. Investors get nervous and sell chip stocks to avoid the risk of factories shutting down, and the price falls even though no factory has stopped working. The market is reacting to the changed chance of a bad outcome, not to a bad outcome that has already arrived.</p><p>A second effect is that <strong>big investors walk away</strong>. Large funds often have strict rules about how much risk they may carry, and some cannot hold assets that could be cut off by a regional conflict. When one of those funds sells for risk reasons rather than business reasons, it adds extra selling pressure that has nothing to do with earnings.</p><p>The third effect is the <strong>domino effect</strong>. If Taiwanese factories were to stop, American chip designers would have no products to sell, so US technology stocks would drop as well. This is why a political event in Asia can move share prices in New York. The chain connects the factory to the designer to the company that sells the final product, and investors in every link feel the tension.</p><h4>How Calmer News and Backup Plans Push Stocks Up</h4><p>The discount can shrink as well as grow. <strong>Peaceful talks</strong>, meaning diplomatic meetings that lower tension, help calm market fears and bring buyers back into chip stocks. Because the fear discount depends on the perceived chance of disaster, anything that lowers that chance can bring the price back up without any change in the company''s actual operations.</p><p>Companies can also act on their own. When a Taiwanese chipmaker announces it is <strong>building backups</strong>, which means new factories in safer places such as the US, Japan or Europe, investors feel more secure about the supply chain. TSMC''s first plant in Japan is an example of this, built with Japanese government support.</p><p>Even good news like this may not move a stock much if the plant was widely expected or the timing is awkward, for example an opening that falls on a weekend and leaves the next trading day little new to react to. It is a good reminder that how a market reacts depends on timing.</p><p>Backups come with their own costs, such as different wages, energy prices and local rules, and the market does not always cheer. A European plant, for instance, can be backed by a government subsidy that reduces the spending risk and secures orders from the car industry, yet the stock may still slip slightly as investors weigh high European labour costs and a long construction timeline. If it holds up better than a weak sector, the news may at least have cushioned the fall.</p><p>A final upside is <strong>strong pricing power</strong>. Advanced chips are so hard to make that customers are willing to pay more for guaranteed supply. Reliable plants in several countries become a selling point, because a customer who fears running out of chips will pay a premium to a supplier who can promise they will not.</p><h4>The Semiconductor Sector in Practice</h4><p>The real-world story has two parts. First came the selloff. Famous investor Warren Buffett sold billions of dollars worth of TSMC shares shortly after buying them, explicitly saying that rising geopolitical tensions in Taiwan made him uncomfortable. Even a very patient investor decided that the fear discount was too high for him, and that kind of decision can ripple through the market.</p><p>Then came the recovery. TSMC''s stock later surged to new highs as it opened brand-new factories in Japan and advanced projects in the US, proving that it could diversify outside Taiwan. The fear never disappeared completely, but a company that is seen to be reducing its single point of failure deserves a smaller discount.</p><p>When you see a headline about Taiwan, there are two questions worth asking. Has the actual risk of disruption changed, or only the mood? And does the company have plants elsewhere that soften the blow if something goes wrong? A scary headline with no change in real risk may fade fast, while a real change in a company''s footprint can reshape how investors price it for years.</p><h4>Recent Headlines in Practice</h4><p>These headlines show that location risk is as much about perception as about physical disruption, and that it can cut both ways. Trump''s July 2024 remarks that Taiwan should pay for its defense pushed TSMC down in morning trading, yet the next session the stock edged up with the sector, which suggests the market treated words differently from a real change in supply. For Samsung, the risk sat in its China memory plants, which hold roughly 40% of its NAND capacity: the loss of validated end user status in September 2025 left the stock lagging a rising sector, while the annual licenses for 2026 announced in December 2025 were followed by a jump of more than 7% even as the sector fell. Investors appeared to price the chance that a plant could be cut off from its equipment, and to reprice quickly when that chance shrank.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">TSMC &middot; 17 Jul 2024</p><p class="news-callout-headline">Trump says Taiwan should pay the U.S. for defense; shares of chip giant TSMC fall</p><p>Trump said Taiwan should pay the US for defense, and TSMC shares fell more than 2% in morning trading on the day of the remarks. The following session the stock edged up 0.39%, close to the sector''s 0.30% gain, which suggests the market treated the remarks as words rather than a change in real supply.</p><p class="news-callout-move">Next day: stock +0.39% vs sector (SOXX) +0.30%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/07/17/trump-says-taiwan-should-pay-the-us-for-defense-shares-of-tsmc-fall.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Because so many advanced chips come from Taiwan, tension in the region puts a fear discount on chip stocks, including US designers that depend on those factories. Calm diplomacy and factories in safer locations shrink that discount, though new locations add costs of their own.</p></div>',
 3),

(8, 'geopolitical', 'Tariffs & Trade Wars',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/geopolitical-4.svg" alt="A mine cart carrying gallium and germanium crystals bumps into a brick wall labelled TARIFF while the price tag on a chip factory swings and a red arrow rises." loading="lazy" width="640" height="260"><figcaption>Trade walls block key minerals and push chipmakers&#x27; costs up.</figcaption></figure><p class="lesson-lead">When one country blocks chip sales, the other can hit back where it holds the cards: the raw materials that make chips possible. Trade wars turn politics into higher costs, and costs turn into share prices.</p><h4>Payback Moves, Rare Minerals and Tariffs</h4><p>Trade wars rarely stay one-sided. When one country blocks chip sales, the other often replies with <strong>payback moves</strong>, hitting back at the point where it has the most influence. For a country that cannot easily match the other side''s chip designs, that point is often the raw materials needed to make chips. It is a bit like two neighbours in a dispute where one stops lending tools and the other stops lending the ladder.</p><p>The key ingredients are <strong>rare minerals</strong>. Making chips requires special gases and rare metals such as gallium and germanium, and these are mostly mined or refined in only a few countries. If one of those countries limits exports, everyone else competes for what is left, and prices rise. Because the material is a small part of the final product but essential to it, a shortage can slow an entire factory.</p><p>The second tool is the <strong>tariff</strong>, which is an extra tax a government places on imported goods. Tariffs make foreign technology and electronics more expensive for buyers in the importing country. Imagine your favourite phone costing 20% more at the shop because of a border tax: you might delay the purchase or choose a cheaper brand, and the chipmaker behind that phone sees fewer orders.</p><p class="lesson-formula">Retaliation or tariff &rarr; higher input costs or weaker demand &rarr; lower profit forecasts</p><p>The flow above shows that trade fights hit chip companies from two directions. A metals ban pushes costs up on the supply side, while a tariff pulls demand down on the customer side. Either way, the profit forecast falls, and the share price follows.</p><h4>How Trade Fights Push Stocks Down</h4><p>The first effect is <strong>material shortages</strong>. If a country stops exporting critical metals, chip factories face delays and must pay much higher prices for backup supplies. A factory that stops for want of one ingredient is expensive to restart, and it may miss deliveries that it promised to customers.</p><p>The second effect is that <strong>tariffs hurt demand</strong>. Taxes on imported parts make laptops, phones and cars more expensive, so everyday shoppers buy fewer of them. Because every one of those products contains chips, the orders behind them shrink as well. The chipmaker never sees the shopper, but it feels the fall in sales weeks later.</p><p>The third is <strong>messy supply chains</strong>. Companies are forced to build expensive backup systems just to get basic materials, which means finding new suppliers, qualifying them, and holding extra stock. That spending comes straight out of profit, and it does not usually produce any extra revenue.</p><p>China''s 2023 restrictions on gallium and germanium show how this works in practice. The restrictions were widely described as payback for Western chip bans, and they targeted two key materials for compound semiconductors and optical chips.</p><p>Investors feared bottlenecks upstream, higher material costs and an escalating trade war. When a worry is shared across the whole industry rather than specific to one company, a stock falls about as much as its sector, and when investors feared all of those things at once, almost every chip stock tended to move lower together.</p><h4>How Trade Deals and Solutions Push Stocks Up</h4><p>Relief arrives in several forms. <strong>Trade truces</strong> are the most obvious: when countries agree to pause tariffs or remove trade barriers, company costs drop immediately and stocks tend to rally. An investor does not need to wait for the next earnings report, because the new tax or restriction is no longer part of the profit forecast.</p><p>A second form is <strong>finding new sources</strong>. When chipmakers announce that they have secured supply deals with friendly countries, shortages are avoided and confidence returns. A supply contract is an insurance policy, and the market is willing to pay for the reduction in risk.</p><p>The third is that <strong>local suppliers win</strong>. Domestic mining and chemical companies often see their share prices jump as they replace banned foreign suppliers. This is the mirror image of the earlier lessons: the same policy that hurts the buyer can enrich the seller who steps in to fill the gap.</p><h4>The Semiconductor Sector in Practice</h4><p>The 2023 episode follows the pattern exactly. First came the restriction: China limited exports of gallium and germanium, two critical metals used in advanced chips, in response to Western tech bans, and chip manufacturing stocks suffered a brief panic. Then came the fix: chipmakers quickly secured backup supplies from countries such as Australia and Canada, which calmed the market and allowed stock prices to steady.</p><p>A trade shock is usually worst on the first day, when the market does not know how long the shortage will last. Prices tend to recover once companies show they have a plan B. For a student of markets, this means that the length of a shock matters more than its headline size, and that evidence of a backup plan is one of the best signs that a selloff may be fading.</p><p>When you meet a trade headline, ask three simple questions. How many countries can supply the affected material? How much of the company''s output depends on it? And how long would it take to switch to another source? The answers help you tell a short-lived scare from a lasting squeeze on profits.</p><h4>Recent Headlines in Practice</h4><p>The tariff headlines show how much the details of a trade rule decide the reaction. When Trump proposed a 100% chip tariff but exempted companies building in the US, TSMC and Samsung were treated as relative winners because of their American expansion. Samsung rose more than the sector the next day, while TSMC slightly lagged a rising sector after having already jumped nearly 5% in Taiwan. In April 2025, Micron''s tariff-related surcharge on memory modules and solid-state drives came on a day when the whole sector surged, and Micron''s gain of about 18.8% almost matched the sector''s. ASML''s May 2025 headline about $130 billion of lost value from China curbs and tariff uncertainty was a look back at past losses and barely moved the stock. Exemptions, product scope and the timing of the news mattered more than the word tariff itself.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">TSMC &middot; 7 Aug 2025</p><p class="news-callout-headline">What the world''s biggest chipmakers are doing to stave off Trump''s tariffs</p><p>Trump proposed a 100% tariff on imported chips but said companies building or committed to build in the US would not be charged. TSMC shares rose nearly 5% in Taiwan on its US expansion, and the next day the stock slipped while the sector rose, so investors appeared to pause after the jump.</p><p class="news-callout-move">Next day: stock -0.33% vs sector (SOXX) +0.84%</p><a class="news-callout-link" href="https://www.cnbc.com/2025/08/07/chip-stocks-jump-after-trump-semiconductor-tariffs-on-us-footprint.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Trade wars hit chip stocks through scarce raw materials and through tariffs that weaken demand. Truces, new supply deals and local suppliers ease the pressure, and the market usually calms once companies show they have backup sources.</p></div>',
 4),

(9, 'geopolitical', 'Governments as Big Buyers',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/geopolitical-5.svg" alt="An order slip flies from a government building to a row of AI server racks, and a new rack drops into place." loading="lazy" width="640" height="260"><figcaption>Countries buying their own AI computers are giant new customers.</figcaption></figure><p class="lesson-lead">Chipmakers used to sell mainly to a handful of tech companies. Now a new kind of customer has arrived, with enormous budgets and its own reasons to buy: whole nations.</p><h4>Nations as Customers</h4><p>For many years, chipmakers sold mainly to a handful of large technology companies. Now a new kind of customer has appeared: whole countries. World leaders increasingly view AI like electricity or roads, something every country must own for itself rather than rent from foreign technology firms. This idea is often called <strong>Sovereign AI</strong>, and it turns national computing into a matter of pride and security as well as economics.</p><p>That shift creates <strong>new mega-customers</strong>. Instead of selling only to companies such as Microsoft or Google, chipmakers are now able to sell directly to national governments, which want to build their own large computing systems using their own languages and data. Selling to a government is a bit like selling to a city that has decided to build its own power station: the order is huge and rarely repeated by anyone else.</p><p>Governments also have <strong>unlimited budgets</strong>, at least in the sense that matters here. They have massive amounts of money to spend on supercomputers, regardless of what the broader economy is doing, because this spending is seen as national strength rather than a luxury. A household cuts back when times are hard, but a government that sees AI as essential infrastructure may keep spending.</p><p class="lesson-formula">National AI plan &rarr; government buys thousands of chips &rarr; chipmaker orders and forecasts rise</p><p>The flow above is the positive version of this story. A government announces a national AI plan, buys thousands of chips, and the chipmaker''s order book and sales forecast grow. The same flow can run into trouble, however, when politics gets in the way, which brings us to the downside.</p><h4>How Political Blockades Push Stocks Down</h4><p>The first problem is <strong>blocked deals</strong>. If a government stops a chipmaker from selling AI servers to a foreign state because of spying concerns, multi-billion-dollar deals can be canceled. The chips themselves may be perfectly good, but the political permission needed to sell them never arrives.</p><p>The second problem is <strong>red tape</strong>. Extra security reviews can delay large deals for months, leaving investors wondering if the sales will ever happen. Uncertainty about timing is itself a reason for prices to drop, because a delayed sale is worth less than a sale that happens this quarter, and a sale that may never happen is worth even less.</p><p>There is a subtle point here: a blockade does not always hurt, because the size of the damage depends on how much the company relies on the blocked market. A licensing hurdle in one region may matter greatly to one chipmaker and hardly at all to another. A hurdle on a government-led market matters less when the company is not dependent on it.</p><h4>How National AI Spending Pushes Stocks Up</h4><p>When national AI plans are announced, the first effect is <strong>giant orders</strong>. Countries buy thousands of the most expensive chips on the market all at once, which can add a large amount to a chipmaker''s future revenue in a single announcement.</p><p>The second effect is <strong>more customers</strong>. Chipmakers become less dependent on a few Silicon Valley technology giants for their profits, so one customer pulling back hurts less. A business with ten customers of equal size is far less fragile than one with two, and investors tend to reward that diversification.</p><p>The third is <strong>recession-proof sales</strong>. Even if regular consumers stop buying phones, governments keep funding their national defense and AI systems. That makes the revenue steadier, and steady revenue is worth more to an investor than revenue that jumps up and down with the economy. The word recession-proof should not be taken too literally, but the principle holds: government budgets follow national goals rather than the mood of shoppers.</p><p>Strong global demand can even outweigh policy friction. A warning from a government official against dodging export controls would normally be a negative headline. Yet a stock can still climb and beat its sector if investors judge that soaring worldwide AI demand outweighs the policy risk. Deep demand can act as a cushion against policy noise, and that cushion is precisely what a broad base of buyers, including governments, provides.</p><h4>The Semiconductor Sector in Practice</h4><p>The real-world movement is already visible. Countries such as Japan, France and the UAE began spending billions of dollars to build their own national supercomputers using their own local languages and data. Each of these projects needs thousands of high-end chips, which chipmakers are happy to supply.</p><p>Chipmakers pointed to this Sovereign AI demand as a major reason their sales kept beating expectations, and the result was a strong rally across the entire semiconductor sector. The sector-wide nature of the rally is important: when a new type of buyer appears, the whole supply chain feels the benefit, from chip designers to the companies that make the equipment and materials they depend on.</p><p>A single country can appear in both kinds of headline, depending on whether its government is buying chips or being blocked from receiving them. So the best habit when reading such news is to separate the buying story from the blocking story, and to ask which one is bigger for the company in question. The gap between announcement and delivery is where most of the risk sits, because plans can be delayed, reduced or blocked after the headline appears.</p><h4>Recent Headlines in Practice</h4><p>Not every recent headline involves a government as a customer, but several show the state as a very large and unusual investor in chip firms, which raises similar questions about size, conditions and delivery. Intel is the clearest case. A report on 19 August 2025 that the administration might convert CHIPS Act grants into a stake of about 10% was followed by a fall of nearly 7%, against a sector decline of under 1%. After the deal was confirmed, with the government buying 433.3 million shares at $20.47 each, the stock slipped again the next day, and even after a rise of roughly 50% over the following month it fell the day after the 2 October headline. The pattern suggests investors weigh dilution and control as well as the cash, and that having the biggest buyer in the room does not guarantee a rising price.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Intel &middot; 22 Aug 2025</p><p class="news-callout-headline">U.S. government takes 10% stake in Intel, as Trump expands control over private sector</p><p>The US government invested $8.9 billion in Intel common stock for a 10% stake, with $5.7 billion from unpaid CHIPS Act grants and $3.2 billion from a secure chips program. It gets no board seat and a warrant for 5% more if Intel stops majority-owning its foundry. The stock slipped a little more than the sector the next day, as investors appeared to weigh the new shareholder and the extra shares.</p><p class="news-callout-move">Next day: stock -1.01% vs sector (SOXX) -0.23%</p><a class="news-callout-link" href="https://www.cnbc.com/2025/08/22/intel-goverment-equity-stake.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Governments are becoming major chip buyers because they see AI as national infrastructure, and their orders are large and steady. Political blockades and long security reviews can delay those deals, so the gap between announcement and delivery is where the risk sits.</p></div>',
 5),

(2, 'earnings', 'Understanding Earnings Reports and Earnings Calls',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/earnings-1.svg" alt="An earnings report card with revenue, EPS and margin bars filling next to a speech bubble for the earnings call." loading="lazy" width="640" height="260"><figcaption>The report gives the numbers, the call gives the story</figcaption></figure><p class="lesson-lead">Four times a year, a chip company opens its books and then spends an hour on a call telling investors what it expects next. The numbers matter, but the story around them often matters more.</p><h4>What an earnings event really is</h4><p>Public semiconductor companies are required to report their financial results on a regular schedule, usually every three months. Alongside the written report, management hosts an <strong>earnings call</strong>, a live conversation where executives walk through the quarter and then take questions from the analysts who follow the stock. Think of it as a school report card combined with a parent-teacher meeting: the report card shows what happened, and the meeting tells you what the teacher expects next term.</p><p>The information arrives in a rough order, and each step feeds the next. The results come first, then management''s outlook, then the explanations given on the call, then analysts adjusting their forecasts, and finally the market deciding what the shares are now worth.</p><p class="lesson-formula"><strong>Financial Results &rarr; Forward Guidance &rarr; Management Commentary &rarr; Analyst Revisions &rarr; Stock Reaction</strong></p><p>Investors care about what happened last quarter, but they care even more about what it suggests for future revenue, profitability and demand. That is because a share price is a claim on all the profits a company will earn from now on, not a receipt for the profits it has already booked. The rest of this lesson introduces the three headline numbers you will meet in every report, and then the forward-looking part that often steals the show.</p><h4>Revenue: the top line</h4><p><strong>Revenue</strong> is the total money a company brings in from selling its products and services, and it sits at the very top of the income statement, which is why people call it the top line. For a chip company it is shaped by several things at once: how many chips are sold, the <strong>average selling price (ASP)</strong> each one fetches, the product mix (a premium AI chip earns far more than a basic controller), customer demand, market share and the production capacity available to meet orders.</p><p>Because revenue is simply volume times price, it is easy to reason about with small numbers.</p><p class="lesson-formula"><strong>Revenue = Units Sold &times; Average Selling Price</strong></p><p>Suppose a company ships 10 million chips at $100 each. Revenue is $1 billion. Next year it ships 12 million chips at $110 each, and revenue becomes $1.32 billion, a 32% increase. Notice that both levers moved: volume rose 20% and price rose 10%. Strong revenue growth may indicate rising demand, higher prices, market-share gains, or all three, and one job of the earnings call is to explain which of those it was. Growth driven by price increases on a product everyone is scrambling to buy tells a different story from growth driven by a one-off bulk order.</p><h4>Earnings per share: profit for each slice</h4><p>Revenue says how much was sold, but not how much the company kept. After paying for materials, factories, salaries, research, interest and taxes, what remains is net income. Dividing that by the number of shares gives <strong>earnings per share (EPS)</strong>, the profit attributable to each share of the company. Putting profit on a per-share basis makes companies of very different sizes comparable and lets you see growth even if the share count changes.</p><p class="lesson-formula"><strong>EPS = Net Income / Shares Outstanding</strong></p><p>A company earning $5 billion with 1 billion shares outstanding reports EPS of $5.00. Investors rarely look at that figure alone. They compare it with what analysts predicted. If analysts expected $5.00 and the company reports $5.50, that is an <strong>earnings beat</strong>, because the result came in 10% above the forecast. The next lesson looks at beats and misses in detail, but it helps to know from the start that the headline EPS number only becomes meaningful when it is held up against an expectation.</p><p>A strong report usually has revenue, EPS and guidance all arriving together. When you read one, notice how many of the numbers are stated relative to what analysts expected, not just in isolation.</p><p>A standout quarter shows the structure of a good report: sales growth, a beat on EPS, and a higher outlook for the next quarter. When the stock rises much more than the semiconductor sector index, the reaction is specific to the company and not a rising tide.</p><h4>Gross margin: how much of each sale is kept</h4><p>A company can grow revenue quickly and still be a poor business if each sale costs nearly as much as it brings in. <strong>Gross margin</strong> measures how much revenue remains after the direct cost of producing the goods, which accountants call cost of goods sold (COGS). It is expressed as a percentage of revenue.</p><p class="lesson-formula"><strong>Gross Margin = (Revenue &minus; Cost of Goods Sold) / Revenue</strong></p><p>If a chip sells for $100 and costs $60 to make, the gross profit is $40 and the gross margin is 40%. If the same chip can be sold for $110 without the cost changing, the gross profit is $50 and the margin rises to about 45%. Because chipmakers spend enormous sums on factories, a few extra points of margin can be worth billions of dollars.</p><p>For semiconductor companies, gross margin is pushed around by chip prices, factory utilisation, manufacturing costs, product mix and yield. <strong>Factory utilisation</strong> is how busy the fabs are. A fab costs the same to run whether it is half empty or full, so a busy fab spreads those large fixed costs over many more chips and each chip becomes cheaper to make. <strong>Yield</strong> is the share of chips on a silicon wafer that actually work. If a process change lifts yield from 70% to 80%, the company gets more sellable chips from the same wafer and the cost per good chip falls.</p><p>Read together, revenue growth and gross margin tell you whether growth is healthy. Rising revenue with a rising margin suggests pricing power or efficiency. Rising revenue with a shrinking margin suggests the company is buying its growth with discounts or higher costs.</p><h4>Forward guidance: the part that moves prices</h4><p><strong>Forward guidance</strong> is management''s own expectation for future periods. It may cover expected revenue, expected EPS, expected gross margin, capital expenditure (money spent on equipment and buildings), customer demand and broader industry conditions. Companies usually give a range, such as revenue of $9.5 to $10.5 billion next quarter, and analysts then compare the middle of that range with their own forecasts.</p><p>Guidance can sometimes influence the stock more than the reported quarter, because a share price is a bet on the future, not a receipt for the past. A quarter that has already ended cannot be changed, and everyone has had weeks to guess how it went. The outlook, on the other hand, is genuinely new information. If management says demand is stronger than anyone thought, analysts will raise their forecasts for the next several quarters, and the value of those extra future profits is added to the share price on the spot.</p><p>Guidance can lift a stock even when the quarter itself is unremarkable. Imagine a forecast for next quarter''s revenue above what analysts expected, together with a comment from management that customers have finished working through their old inventory. Together those tell investors that a weak spell may be ending, and the outlook can matter more than the quarter just reported. That is also why gross margin deserves a place beside revenue and EPS on your checklist: when volume recovers, the factory-utilisation effect described earlier can lift margins too.</p><h4>Recent Headlines in Practice</h4><p>The recent Samsung reports show how one line item can tell very different stories depending on the cycle. In April 2023, its first-quarter profit plunged 95% to the lowest level since 2009 as the memory chip glut hit the business, and in January 2024 its chip unit reported a record annual loss of 14.88 trillion won. Yet Samsung''s Korea-listed shares rose after both reports, by 1.39% and 1.24%, while the sector also rose. By April 2024, operating profit had jumped 933% as memory prices recovered. A report is read against what the market already knew: a dreadful number that may have been widely feared can pass quietly, so the segment detail inside the report, such as the chip unit''s direction, often matters more than the headline percentage.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Samsung &middot; 30 Apr 2024</p><p class="news-callout-headline">Samsung Electronics'' operating profit jumps 933% in first quarter, beats expectations</p><p>Operating profit jumped 933% and beat expectations as memory prices recovered, with the chip unit back to a 1.91 trillion won profit from a 4.58 trillion won loss a year earlier. Samsung''s Korea-listed shares edged up while the sector fell, so the reaction was muted despite the dramatic percentage.</p><p class="news-callout-move">Next day: stock +0.65% vs sector (SOXX) -3.38%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/04/30/samsung-electronics-first-quarter-earnings.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>An earnings report gives you two things at once: <strong>Past Performance</strong> and <strong>Expected Future Performance.</strong> Read revenue, EPS and gross margin for the past, and guidance and commentary for the future. The stock usually cares more about the second half of that sentence.</p></div>',
 1),

(10, 'earnings', 'Earnings Beats, Misses and Market Expectations',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/earnings-2.svg" alt="A dashed expected bar sits below a taller actual bar, and the gap between them lifts a stock arrow." loading="lazy" width="640" height="260"><figcaption>Stocks react to the gap between actual and expected</figcaption></figure><p class="lesson-lead">A company can post record profit and watch its stock fall, or lose money and watch it rise. The puzzle disappears once you see that the market never reacts to results alone, only to results compared with what it expected.</p><h4>Why "good" and "bad" are the wrong questions</h4><p>Beginners often assume that good earnings make a stock rise and bad earnings make it fall. In practice the link is much looser. Before a company reports, thousands of investors and analysts have already studied its customers, its suppliers and its past guidance, and they have formed a picture of what the numbers will probably be. That picture is built into the share price in advance. When the real numbers arrive, the price only needs to move if they differ from the picture.</p><p>Stocks therefore do not react simply to whether earnings are "good" or "bad." They react to the difference between actual results and market expectations. A useful simplified framework is:</p><p class="lesson-formula"><strong>Stock Reaction &asymp; New Information &minus; Market Expectations</strong></p><p>If the new information equals what everyone expected, the difference is roughly zero and the stock barely moves, even when the numbers are spectacular. If the new information is better than expected, the difference is positive and the price tends to rise. If it is worse, the price tends to fall. It is a simplification, because real reactions also depend on guidance, tone and the mood of the wider market, but it is the single most useful mental model for earnings season.</p><h4>Revenue beats and misses</h4><p>Analysts publish forecasts for each reported figure before the company speaks. Suppose analysts expect revenue of $20 billion. If the company reports $22 billion, that is a <strong>revenue beat</strong>, because actual revenue came in 10% above the forecast. If it reports $18 billion instead, that is a <strong>revenue miss</strong>, 10% below. The size of the gap matters as much as its direction: a result that lands $50 million above a $20 billion forecast is technically a beat, but it is within the noise and rarely moves anything.</p><p>Revenue is often the first number people look at, because it speaks to demand. A miss can suggest customers are ordering less or competitors are taking share. A beat can suggest the opposite. But it is only one of several numbers, and it can be contradicted by the others, as the next section shows.</p><h4>EPS beats and misses</h4><p>The same principle applies to earnings per share. When actual profit per share comes in above the forecast, it is an <strong>EPS beat</strong>, and when it falls below, it is an <strong>EPS miss</strong>.</p><p class="lesson-formula">Reported EPS &gt; Expected EPS &rarr; EPS Beat</p><p class="lesson-formula">Reported EPS &lt; Expected EPS &rarr; EPS Miss</p><p>Smart investors do not stop at the headline, because EPS can be affected by many things other than the health of the business. Revenue growth and gross margins are the healthy drivers. Operating expenses, taxes and interest expenses also play a part. Share repurchases matter too: when a company buys back its own stock, there are fewer shares outstanding, so the same profit is divided among fewer shares and EPS rises even though the business did not improve. One-time gains or losses, such as selling a property or writing down old inventory, can also swing EPS in a single quarter.</p><p>This is why the reason behind a beat matters. Imagine two companies that both report EPS of $1.10 against a forecast of $1.00. The first earned it through stronger sales and wider margins. The second got a one-off tax benefit worth 12 cents. Both are "beats", but only the first suggests the business is improving, and the market usually notices the difference.</p><p>A beat on one line can be overpowered by trouble on another. A company can report revenue ahead of estimates and still see its stock fall sharply because the profit picture went the wrong way. The line items do not vote equally: profit, margins and the outlook usually carry more weight than a small revenue beat, especially when management is also warning about the next quarter.</p><h4>Expectations versus absolute performance</h4><p>The most important consequence of this framework is that a result can be impressive in absolute terms and still disappoint. Consider a semiconductor company reporting revenue growth of +40%. That sounds excellent. But if investors expected +50%, the company has delivered 10 percentage points less than the market was counting on, and the stock may fall. Now consider a company reporting revenue growth of &minus;5%. That sounds poor. If investors had braced for &minus;15%, the result is a relief, and the stock may rise.</p><p>This means you cannot read the direction of a stock''s reaction from the quality of the numbers alone.</p><p class="lesson-formula"><strong>Strong Performance &ne; Positive Stock Reaction</strong></p><p class="lesson-formula"><strong>Weak Performance &ne; Negative Stock Reaction</strong></p><p>The important comparison is between actual and expected performance, rather than reported numbers in isolation. A useful habit is to ask two questions of every report: how did the company do, and how did that compare with what the market was expecting? Only the second question predicts the direction of the reaction.</p><p>Nvidia in August 2023 is a good example of a spectacular quarter that produced almost no price move. The company doubled its sales, raised its outlook far above forecasts, and still the shares went nowhere the next day, because investors had already pushed the price up on the expectation of exactly this kind of result.</p><aside class="news-callout news-callout--flat"><p class="news-callout-meta">Nvidia &middot; 23 Aug 2023</p><p class="news-callout-headline">Nvidia reports record Q2 revenue of $13.51 billion</p><p>Nvidia doubled Q2 revenue to $13.51B and guided Q3 revenue to $16.0B, far above the $12.6B consensus, plus a $25B buyback. The stock still finished roughly flat because it had already surged more than 200% that year, so exceptional results were largely priced in. Supply commentary about TSMC CoWoS packaging bottlenecks also capped near-term upside.</p><p class="news-callout-move">Next day: stock +0.08% vs sector (SOXX) -3.30%</p><a class="news-callout-link" href="https://www.reuters.com/technology/nvidia-forecasts-third-quarter-revenue-above-wall-street-expectations-2023-08-23/" target="_blank" rel="noopener">Read the source</a></aside><p>The opposite can happen too: a company can announce a very large quarterly loss and see its stock rise. A loss that is already expected is no longer news, while a credible plan to stop the bleeding is.</p><p>Putting these two cases side by side makes the point clearly. Record sales can produce a flat reaction, while a record loss can produce a gain, and in both cases the explanation is the gap between results and expectations.</p><h4>Consensus estimates</h4><p>When a headline says a company "beat" or "missed", it is comparing the result with a single number. Analysts publish forecasts for revenue, EPS, gross margin, operating income and free cash flow (the cash left after running the business and investing in it). The average or aggregated forecast is generally referred to as the <strong>consensus estimate</strong>, and it is the yardstick most headlines use.</p><p>Consensus is useful, but it has limits. Individual analysts may be outdated, and many investors hold views more optimistic or pessimistic than the published average. Sometimes you will hear about a "whisper number", the informal level traders actually expect, which can sit above consensus when a stock has been rising into the report. The next lessons build on this idea by showing how the outlook and the surrounding commentary change expectations in the days after a report.</p><h4>Recent Headlines in Practice</h4><p>Beats and misses are measured against consensus estimates, so the gap matters more than the absolute figure. Intel''s October 2023 report is a clean example: adjusted EPS of 41 cents against 22 cents expected, plus revenue ahead of forecasts, and the shares rose 9.29% the next day, far above the sector''s 1.08%. Beats do not always lift prices, though. Micron''s June 2025 results topped both EPS and revenue estimates, yet the stock pared its early after-hours gain and closed 0.98% lower the next day. Nvidia''s February 2025 beat on revenue, EPS and guidance was followed by an 8.48% drop in a sector that fell 5.82%. When expectations are already high, a beat can be necessary without being sufficient.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Intel &middot; 26 Oct 2023</p><p class="news-callout-headline">Intel stock rises on earnings beat and strong revenue guidance</p><p>Adjusted EPS of 41 cents beat the 22 cents expected and revenue of $14.16 billion beat $13.53 billion, with fourth-quarter guidance of $14.6 billion to $15.6 billion. A large gap against consensus, paired with a good outlook, helped the stock outrun the sector.</p><p class="news-callout-move">Next day: stock +9.29% vs sector (SOXX) +1.08%</p><a class="news-callout-link" href="https://www.cnbc.com/2023/10/26/intel-intc-earnings-report-q3-2023.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>When analysing earnings, always compare <strong>Actual Results vs. Market Expectations.</strong> A beat only means something relative to the bar the market had set, and a miss only matters relative to the same bar.</p></div>',
 2),

(11, 'earnings', 'Forward Guidance and Management Commentary',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/earnings-3.svg" alt="A CEO speaks a bubble containing a rising forecast line above a dashed old outlook, and the stock badge rises." loading="lazy" width="640" height="260"><figcaption>A better outlook can move the stock more than last quarter</figcaption></figure><p class="lesson-lead">The most expensive sentence on an earnings call is often the one about next quarter. Investors buy the future, so a change in outlook can outweigh everything that already happened.</p><h4>Why the outlook matters more than the past</h4><p>Stock prices are forward-looking. A share is a claim on profits that have not been earned yet, so what the market pays for it depends on what it believes about the coming quarters and years. This is why investors may care more about what management says about the next quarter or year than about the quarter that has already ended. The reported numbers are history, and everyone has already had time to estimate them. The outlook is fresh information.</p><p>The basic process works like a chain reaction. Management gives new guidance, analysts update their models, the future earnings that the market expects change, and the stock price adjusts to match.</p><p class="lesson-formula"><strong>New Guidance &rarr; Analyst Forecast Changes &rarr; Future Earnings Expectations &rarr; Stock Price</strong></p><p>The rest of this lesson walks through the parts of that chain you will hear on a call, beginning with the numbers management puts on the table and ending with the softer commentary that hints at what is coming.</p><h4>Revenue guidance</h4><p>Management may provide an expected revenue range for the next quarter or the year. As with results, what matters is the comparison with what the market already expected. If the market expects $25 billion and the company guides to $28-30 billion, the whole range sits above expectations. Analysts may raise their forecasts for that quarter, and they may also raise forecasts for later quarters, because a stronger start usually implies a stronger year. The opposite occurs when guidance is below expectations: analysts cut their numbers and the stock tends to follow.</p><p>Because the change flows into every future period, a guidance surprise can be worth far more than a surprise in the quarter just reported. The clearest case is a chipmaker whose forecast sits so far above consensus that the whole industry has to rethink its models.</p><p>A guidance number is most convincing when management gives a reason, such as customers shifting part of their spending toward a new product category, because analysts can then judge whether the trend should last. When the stock rises far more than its sector, most of the move belongs to the company.</p><p>The reverse also happens. A company can report an acceptable quarter and then give a forecast for the next one that is far below what analysts had hoped for. Guidance that misses by a wide margin can overwhelm a perfectly fine quarter. If the sector also falls that day but the stock falls several times as much, the guidance shortfall explains most of the move.</p><h4>Margin guidance</h4><p>Revenue growth alone does not determine profitability, so investors also examine the gross margin that management expects. A company that grows its sales by 20% while its margin widens will see profits grow by considerably more than 20%. A company whose sales grow while its margin narrows may see profit stall or even fall. The two combinations are worth memorising.</p><p class="lesson-formula">Revenue &uarr; + Gross Margin &uarr; &rarr; Stronger Earnings Growth</p><p class="lesson-formula">Revenue &uarr; + Gross Margin &darr; &rarr; Profitability May Weaken</p><p>Declining margins may indicate higher manufacturing costs, weaker pricing power or an unfavourable product mix. For example, if revenue is expected to grow 10% but gross margin is guided down from 50% to 45%, then gross profit would be roughly flat, because 1.10 times 45 is about 49.5 against 50 today. The headline sounds like growth, but the profit does not grow at all.</p><p>Memory makers know a related pattern well: good news on revenue can be overshadowed by a gloomy margin or loss outlook. Context matters here too. If the shares fall while the sector rises, the guidance is a company-specific problem and not a general mood swing in chip stocks.</p><h4>Demand and customer commentary</h4><p>Beyond the numbers, executives talk about where demand is coming from. Semiconductor companies frequently discuss end markets including AI, data centres, cloud computing, smartphones, PCs, automotive and industrial electronics. Each statement gives clues about future chip demand. A remark that data-centre orders are accelerating while smartphone demand is soft tells you which parts of the business to expect more or less growth from.</p><p>Management may also discuss customer inventory, order trends, customer capital spending (CapEx), long-term contracts, product adoption and order cancellations. These comments are valuable because they can reveal changes that are not yet visible in reported revenue. A chip company records revenue when it ships a product, but customers place orders months earlier and decide how much to hold in stock. If customers say "inventory is normalising", they are telling you they will soon resume ordering at full rate. If they say "orders are being pushed out", shipments are about to slow. Either phrase can say more about next year than any line of last quarter''s income statement.</p><h4>Supply commentary</h4><p>Management also talks about what limits the company. This may include manufacturing capacity, availability of high-bandwidth memory (HBM), advanced packaging capacity, wafer supply, equipment availability and other production constraints. Supply limits can cut both ways. A supply shortage can sometimes improve pricing power, because buyers compete for scarce products and accept higher prices, while simultaneously limiting shipment volume, because the company cannot make everything it could sell. When you hear that a product is "sold out", it usually means strong demand and good prices, but it also caps near-term growth.</p><h4>Risk commentary</h4><p>Finally, every call includes some discussion of what could go wrong. Important risks may include export restrictions, product delays, customer concentration (a few buyers account for most of sales), competition, manufacturing problems and rising production costs. Investors pay attention to how management describes these. A risk that is mentioned for the first time, or described in sharper language than last quarter, can be a sign that something has changed. It is useful to compare the transcript with the previous quarter''s and spot what is new.</p><h4>Recent Headlines in Practice</h4><p>Guidance often decides how a report is remembered. Intel''s January 2026 results beat on EPS and revenue, but guidance for the first quarter fell short of expectations and the stock lost 17.03% the next session while the sector fell 1.14%. In contrast, Nvidia''s August 2026 report included a forecast of about 70% growth in fiscal 2028, far above the 44% analysts expected, and the shares rose 8.74% the next day. ASML shows the uncertain middle ground: in July 2025 it said it could not confirm growth in 2026, and the shares fell about 11% on the news date even though its key bookings figure beat consensus. In each case, investors appeared to weigh what management said about the future more heavily than the quarter just reported.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Intel &middot; 22 Jan 2026</p><p class="news-callout-headline">Intel stock plunges 13% on soft guidance, concerns about chip production</p><p>Adjusted EPS of 15 cents beat the 8 cents expected, but first-quarter guidance of $11.7 billion to $12.7 billion and breakeven EPS missed the 5 cents expected. The article ties the drop to supply and yield concerns, so the outlook outweighed the quarter''s beat.</p><p class="news-callout-move">Next day: stock -17.03% vs sector (SOXX) -1.14%</p><a class="news-callout-link" href="https://www.cnbc.com/2026/01/22/intel-intc-earnings-report-q4-2025-.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>The central question during an earnings call is: <strong>What has changed about the company''s future outlook?</strong> A change in outlook moves analyst forecasts, and forecasts move the stock. Listen for new numbers, new reasons and new risks, and compare each with what the market already believed.</p></div>',
 3),

(12, 'earnings', 'Semiconductor-Specific Earnings Indicators',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/earnings-4.svg" alt="Four tiles show a fabless chip, a foundry fab, a memory stick and an equipment tool, each with its own gauge." loading="lazy" width="640" height="260"><figcaption>Each chip business needs its own scorecard</figcaption></figure><p class="lesson-lead">Reading a chip earnings report with the wrong checklist is like judging a restaurant by its parking lot. A designer, a factory, a memory maker and a toolmaker each make money in different ways, so each needs its own scorecard.</p><h4>One industry, several business models</h4><p>Not all semiconductor companies should be analysed using the same earnings metrics. The industry is a chain, and each link does a different job. Some companies design chips, some manufacture them, some sell memory, some build the machines used in factories and some assemble finished chips into packages. The most important indicators depend on where the company operates in this supply chain.</p><p>This matters because the same words on a slide can mean very different things. A rise in capital expenditure is a warning sign for a designer whose margins might suffer, but good news for a toolmaker whose customers are about to buy more machines. Learning to match the indicator to the business is the main skill of this lesson, and the table near the end brings the five types together.</p><h4>Fabless companies</h4><p><strong>Fabless</strong> firms such as NVIDIA, AMD, Broadcom and Qualcomm design chips but leave manufacturing to others. Having no factory means they carry few fixed costs, so their gross margins can be high, and their success depends on design quality and demand for what they sell. Important indicators include revenue growth, segment revenue (the split by business line), gross margin, market share, new product adoption, customer demand and forward guidance.</p><p>For AI chip companies, investors may pay particular attention to data-centre revenue and accelerator demand. A fabless firm can have a stellar quarter and still be priced for perfection, so guidance and product adoption are usually what separate a rise from a fall. If a designer says its newest accelerator is being adopted faster than the last, analysts will model higher future sales and the stock may react even if the current quarter was in line.</p><h4>Foundries</h4><p><strong>Foundries</strong> manufacture chips for other semiconductor companies. Major examples include TSMC and Samsung Foundry. Because they own the factories, their economics are very different from a designer''s. Important indicators include capacity utilisation, wafer shipments, advanced-node revenue (revenue from the newest, smallest and most expensive manufacturing processes), yield rates, wafer ASP, capital expenditure and customer demand.</p><p>Higher utilisation can significantly improve profitability because manufacturing has high fixed costs. The same factory cost is spread over more wafers. Imagine a fab that costs $100 million a quarter to run. If it produces 100,000 wafers, the fixed cost is $1,000 per wafer, but if demand drops and it produces only 80,000, that rises to $1,250 per wafer. Revenue per wafer has not changed, so the whole $250 difference comes out of margin. That is why a foundry''s gross margin follows its utilisation so closely.</p><p>A foundry whose customers are working down their stockpiles shows this effect in reverse.</p><p>Notice the chain: customers were working down their stockpiles, so they ordered fewer wafers, so utilisation fell, so margins were squeezed. A foundry''s guidance on utilisation is therefore one of the best early indicators for the whole industry.</p><h4>Memory companies</h4><p><strong>Memory</strong> manufacturers require a different framework because memory is largely a commodity. DRAM and NAND chips from different suppliers are close substitutes, so prices move up and down with supply and demand rather than being set by one company. Important indicators include DRAM prices, NAND prices, HBM demand, bit shipments, inventory, production growth and capital expenditure. A <strong>bit shipment</strong> is simply the amount of memory capacity sold, measured in bits, so it plays the role of the unit count. A simplified relationship is:</p><p class="lesson-formula"><strong>Memory Revenue &asymp; Bit Shipments &times; Memory ASP</strong></p><p>Memory profitability can change rapidly when prices move, because costs do not fall as fast as prices do. A fab''s running costs are mostly fixed in the short run, so when the selling price rises, almost all of the increase drops to profit, and when it falls, the loss comes straight out of profit. A 10% rise in price can therefore lift gross margin by far more than 10%, and the effect flows on to EPS.</p><p class="lesson-formula">DRAM ASP &uarr; &rarr; Revenue &uarr; &rarr; Gross Margin &uarr; &rarr; EPS &uarr;</p><p>Things can turn sharply once prices and demand improve, for instance when a memory maker swings from an expected loss to an actual profit. In a cyclical business, investors look for the turn and pay attention to inventory: when customers and suppliers hold less stock, prices tend to recover.</p><h4>Semiconductor equipment companies</h4><p><strong>Equipment</strong> companies build the machines that factories use, including lithography systems, etching tools and inspection equipment. Their customers are the foundries and memory makers, so they are highly sensitive to semiconductor capital expenditure (CapEx). Important indicators include new orders, backlog (orders received but not yet delivered), semiconductor CapEx, Wafer Fab Equipment (WFE) spending, geographic revenue exposure, export restrictions, and foundry and memory investment.</p><p>Equipment demand also shows what manufacturers expect for future capacity. A chipmaker does not order a new machine unless it expects to need the output, so the order book is a window into the industry''s confidence two or three years ahead. Orders are also more volatile than sales, because a single EUV lithography system can cost well over a hundred million euros and a few cancellations or delays make a big difference. Geographic exposure matters too: if a large share of sales goes to a country that may face export restrictions, a policy change can alter the outlook overnight.</p><p>This is why orders are watched so closely. A toolmaker can keep its full-year guidance and still see its shares drop if an order shortfall raises doubts about when customers will build new capacity. When the sector falls on the same day, part of the move is an industry-wide mood.</p><h4>Advanced packaging companies and a scorecard for each type</h4><p><strong>Advanced packaging</strong> companies assemble and connect finished chips into the packages that go onto boards, increasingly stacking several chips together. Important indicators include capacity utilisation, advanced packaging demand, AI-related packaging revenue, capacity expansion and customer orders. AI accelerators often require sophisticated packaging technologies, making packaging capacity an important part of the AI semiconductor supply chain.</p><p>In practice, an AI processor may combine a compute chip with several stacks of high-bandwidth memory in one package. If packaging capacity is short, the chips cannot be shipped even when everything else is ready. This is why packaging commentary shows up on the calls of designers and foundries as well, and why a bottleneck here can limit the revenue of the whole chain.</p><p>To bring it together, each company type has its own scorecard of what to look for in an earnings report.</p><table><thead><tr><th>Company type</th><th>Important earnings indicators</th></tr></thead><tbody><tr><td>Fabless</td><td>Revenue growth, product demand, gross margin, guidance</td></tr><tr><td>Foundry</td><td>Utilisation, wafer ASP, advanced nodes, CapEx</td></tr><tr><td>Memory</td><td>DRAM/NAND/HBM prices, bit shipments, inventory</td></tr><tr><td>Equipment</td><td>Orders, backlog, WFE spending, customer CapEx</td></tr><tr><td>Packaging</td><td>Utilisation, advanced packaging demand, capacity</td></tr></tbody></table><p>Use the table as a starting point, not a rule. The categories overlap, and some companies span several of them, but if you know which description fits the company you are reading about, you know where to look first.</p><h4>Recent Headlines in Practice</h4><p>Different chip companies publish different leading indicators, and the headline numbers often reflect the business model. ASML sells chipmaking equipment, so its net bookings show how much customers plan to spend: 2.6 billion euros in October 2023, down 42% from the prior quarter as customers cut spending, then 7.09 billion euros in January 2025 against 3.99 billion expected, and a record 13.2 billion euros in January 2026. Micron, a memory maker, points to data center revenue, capital expenditure and gross margin; in December 2025 it raised capex to $20 billion and projected a gross margin of about 68% as AI memory demand left it more than sold out. Bookings and margins are forward-looking signals that can matter more than last quarter''s revenue.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">ASML &middot; 29 Jan 2025</p><p class="news-callout-headline">ASML shares jump as surge in orders defies fears of DeepSeek hitting AI chip demand</p><p>Fourth-quarter net bookings of 7.09 billion euros were up 169% quarter on quarter and well above the 3.99 billion euros expected, showing customers placing orders despite DeepSeek-driven worries about AI chip demand. Bookings are an early sign of future equipment sales.</p><p class="news-callout-move">Next day: stock +3.42% vs sector (SOXX) +2.03%</p><a class="news-callout-link" href="https://www.cnbc.com/2025/01/29/asml-earnings-report-q4-2024.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>The correct earnings indicators depend on the company''s position in the semiconductor value chain. Before reading any report, ask: <strong>what does this company actually sell, and what drives its profit?</strong> Then check the indicators that belong to that business and ignore the ones that do not.</p></div>',
 4),

(13, 'earnings', 'From Earnings Calls to Stock-Price Reactions',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/earnings-5.svg" alt="A glowing pulse travels along a chain from results to outlook to forecasts and finally the stock price." loading="lazy" width="640" height="260"><figcaption>Results change expectations, and expectations move the price</figcaption></figure><p class="lesson-lead">This is where everything connects. A stock does not move because a number was big or small. It moves because the earnings call changed what investors expect to happen next.</p><h4>The transmission mechanism</h4><p>The final step is connecting earnings information to stock-price movements. Each piece of information from an earnings event changes what people believe about the company''s future, and those beliefs determine the price. A simplified transmission mechanism is:</p><p class="lesson-formula"><strong>Earnings Results &rarr; Guidance &rarr; Future Revenue Expectations &rarr; Future Margin Expectations &rarr; EPS Forecasts &rarr; Valuation &rarr; Stock Price</strong></p><p>Read it from left to right as a story. The reported results and the guidance tell analysts what revenue to expect, and what margin that revenue will earn. Together those give a forecast for future EPS. <strong>Valuation</strong> is the price the market is willing to pay for that stream of future earnings, often described as a multiple of EPS. When forecasts rise, or when investors become more confident about them, the value of the shares goes up. When they fall, the value goes down.</p><h4>Why strong earnings can push stocks up, and weak earnings down</h4><p>A positive reaction may occur when revenue exceeds expectations, EPS exceeds expectations, guidance exceeds expectations, gross margins improve, customer demand strengthens, management raises long-term forecasts, or new products gain market share. All of these developments lead analysts and investors to increase their future earnings expectations. Often several arrive together, and that cluster is what produces the largest rallies.</p><p>It is worth noticing that these items are not equal. A beat on last quarter''s revenue changes only one quarter''s profit. A raised long-term forecast or a new product that takes market share changes many quarters, which is why the second kind usually has a bigger effect on the share price.</p><p>The mirror image is a negative reaction. This may occur when revenue misses, EPS misses, guidance is reduced, gross margins decline, inventory increases, customer orders weaken, production costs rise, or product launches are delayed. These developments reduce expected future profits, and a lower profit forecast means a lower fair price. Rising inventory deserves special attention in semiconductors. If a company or its customers are holding more unsold chips, future orders will fall until the excess is cleared, even if the current quarter looks fine.</p><h4>Why good earnings can still cause a selloff</h4><p>A company can report record revenue and still see its share price fall. Possible reasons include strong results already being priced in, investors expecting a larger beat, disappointing guidance, weaker-than-expected gross margins, slowing future growth, or an already very high valuation. In each case, the news may have been good in absolute terms, but it was not good enough compared with what the price already assumed.</p><p>For example, if consensus revenue is $30B and the company reports $32B, it officially beats expectations by about 6.7%. But if investors had built even higher expectations before the announcement, perhaps $33B after a run-up in the share price, the result can still disappoint. Published consensus and the higher expectations embedded in the stock price are not always the same thing. The share price is a better guide to what the market really expects than the analyst average.</p><p>Even a raised outlook can be read as bad news when investors look past the headline to what is driving it.</p><p>The point is the quality of the revenue. Orders that are a rush before a deadline are not the same as steady demand, and investors discount them. If the wider sector also falls that day, part of the decline is industry-wide.</p><h4>Why weak current earnings can still produce a rally</h4><p>The opposite can also happen. A memory company may report falling revenue, weak EPS and low gross margins, all of which look grim. But management may indicate that customer inventories are normalising, DRAM prices are recovering, HBM demand is accelerating and production cuts are reducing supply. Investors may then expect a chain of improvements that has not yet appeared in the accounts.</p><p class="lesson-formula">Future ASP &uarr; &rarr; Future Revenue &uarr; &rarr; Future Gross Margin &uarr; &rarr; Future EPS &uarr;</p><p>The stock can therefore rise before reported earnings recover. Markets try to look through the trough, so prices can start recovering while the headlines still read badly.</p><p>A memory maker that reports a record loss can still see its stock rally if management''s actions tell investors the worst is behind them. If the stock also rises more than the sector, the market is valuing the turnaround plan on its own merits.</p><h4>Earnings calls as expectation-reset events</h4><p>One way to remember all of this is to treat each earnings call as an event that resets expectations. Before the report, the stock price reflects whatever investors already believe. The report and the call give them new information, they revise their beliefs, and the price moves to a level that matches the new beliefs.</p><p class="lesson-formula">Before earnings: Existing Expectations &rarr; Current Stock Price</p><p class="lesson-formula">After earnings: New Information &rarr; Revised Expectations &rarr; New Stock Price</p><p>This is why earnings-related stock movements can sometimes appear disconnected from headline financial results. The headline describes the past quarter, while the price reflects the revision in expectations about all the quarters to come. Once you accept this, a surprising number of puzzling headlines make sense.</p><h4>Putting it together for three companies</h4><p>Different companies have different chains that matter most. For NVIDIA, the chain runs from AI demand to data-centre revenue, to gross margin, to forward guidance. Rapid current growth may not be enough for a positive reaction if market expectations are even higher, so the guidance for the next quarter is where the stock is decided.</p><p>For Micron, the chain runs from DRAM, NAND and HBM prices to inventory, to bit shipments, to gross margin and future EPS. The stock may react to expected memory pricing changes before they fully appear in reported earnings, which is why memory shares often rise while the latest quarter still looks poor.</p><p>For Intel, the chain runs from product revenue to manufacturing costs, to foundry performance, to CapEx and gross margin. Meeting revenue expectations may not be enough if manufacturing profitability or the foundry outlook deteriorates, because Intel''s investment in its factories is a large drag until the new capacity fills up.</p><p>The transmission mechanism can work in a single report, where results, margin and guidance all point up together. If investors had feared that customer spending would pause, results and an outlook above consensus replace that fear with a new expectation, and the expectation is repriced in a single trading day.</p><h4>Recent Headlines in Practice</h4><p>The move after an earnings report depends on how results compare with what was already priced in, not just on whether they are good. In February 2026, Nvidia''s data center revenue rose 75% to $62.3 billion and beat guidance, yet the shares fell 4.17% in the next session while the sector dipped 1.26%. Micron''s June 2026 report showed revenue more than quadrupling and a 15% surge on the news date, but the following session brought a 6.69% decline in a falling sector. At the other end, Intel''s April 2026 results, with revenue up more than 7% despite a wider net loss, sent the stock up 23.60% against a sector gain of 4.67%. Expectations and sector mood both shape the reaction.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Micron &middot; 25 Jun 2026</p><p class="news-callout-headline">Micron soars 15% after blockbuster earnings, lifting some chip stocks</p><p>Revenue more than quadrupled on soaring memory prices and the stock surged 15% on the news date. The following session saw a pullback in step with the sector, a reminder that the first reaction and the next one can differ.</p><p class="news-callout-move">Next day: stock -6.69% vs sector (SOXX) -5.64%</p><a class="news-callout-link" href="https://www.cnbc.com/2026/06/25/micron-stock-3q-earnings-memory.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>The complete framework runs from reported revenue and EPS, to beat or miss, gross margin, guidance, management commentary, analyst revisions, future EPS expectations and valuation. The central principle: <strong>stocks react primarily to changes in expectations about the future, not simply to whether current earnings look good or bad.</strong></p></div>',
 5),

(3, 'macro', 'The Cost of Capital: Interest Rate Hikes & Cuts',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/macro-1.svg" alt="A rate dial swings up while a chip stock balloon is pulled down toward the ground." loading="lazy" width="640" height="260"><figcaption>Higher rates weigh down chip stocks</figcaption></figure><p class="lesson-lead">Imagine two companies with the same factory, the same customers and the same profit. Change only the interest rate on the money they borrowed, and the market will suddenly value one of them very differently. That is the power of the cost of capital.</p><h4>Why the price of money matters</h4><p>Every business runs on money that someone else lent or invested, and that money is never free. The <strong>cost of capital</strong> is the price a company pays to use it, whether through interest on loans and bonds or through the returns shareholders expect. Central bank interest rates sit underneath all of this. When the Federal Reserve moves its policy rate, it sets the baseline cost of borrowing, and almost every other rate, from corporate loans to government bonds, is built on top of that baseline.</p><p>Think of the policy rate as gravity for the stock market. You rarely notice it on a calm day, but it quietly shapes how everything else behaves. A change in the rate affects stocks through two separate routes. The first is the cost route: what companies pay to fund their operations. The second is the valuation route: how much investors are willing to pay today for profits that will arrive in the future.</p><p class="lesson-formula">Fed changes the rate &rarr; borrowing costs and bond yields move &rarr; company profits and stock valuations adjust</p><p>Chipmakers feel this more than most. A modern fabrication plant costs billions of dollars and takes years to build, and it is usually paid for with a mix of debt and internal cash. Even a small change in the interest rate on that debt adds up to a very large number over the life of a factory. That is why semiconductor stocks are often described as capital-intensive, meaning they need a huge amount of money tied up in equipment before a single chip is sold.</p><h4>How rate hikes push stocks down</h4><p>Central banks raise rates when inflation runs hot, because dearer borrowing slows spending and cools the economy. For a company with a lot of debt, the first effect is simple arithmetic: <strong>higher borrowing costs</strong> mean bigger interest payments, and those payments come straight out of profit. A firm that borrows to build a new fab or fund years of research sees its profit margin squeezed, even if its customers and prices have not changed at all.</p><p>The second effect is subtler and usually bigger. An investor buying a share is really buying a stream of future profits, and money received later is worth less than money received today. To see why, ask what you would pay now for 100 dollars due in a year. If a safe government bond pays 2%, you would pay about 98 dollars. If the safe bond pays 5%, you would pay only about 95 dollars, because your money could have grown more elsewhere. The share is the same, but the "<strong>risk-free rate</strong>", the yield on government bonds, has moved, so the price you will pay falls.</p><p>This is called <strong>valuation multiple compression</strong>. The <strong>Price-to-Earnings (P/E) ratio</strong>, which is the share price divided by the company''s earnings per share, tells you how many dollars investors pay for each dollar of annual profit. When safe yields rise, investors demand more reward for taking risk, so they accept a lower P/E. Another way to picture it is a job offer comparison. If a safe job pays 5%, a risky venture promising 6% hardly seems worth the stress. If the safe job pays 2%, the same venture suddenly looks generous. The stock did not change; the alternative did.</p><p>Growth companies and capital-intensive companies suffer most, because a large share of their expected profit sits far in the future, where the discounting effect bites hardest.</p><h4>How rate cuts and pauses push stocks up</h4><p>The mirror image works just as logically. When a central bank lowers rates, or even just signals that it is finished raising them, the market tends to cheer. The first reason is <strong>cheap capital</strong>: debt costs less to service, so companies can finance new equipment, expansion projects and research without watching interest eat their margins. Projects that did not look worthwhile at 6% may suddenly make sense at 3%.</p><p>The second reason is <strong>higher valuations</strong>. When yields on safe bonds fall, holding bonds pays less, and investors move some money into riskier assets like stocks in search of better returns. At the same time, future corporate profits are discounted at a lower rate, so each future dollar is worth more today. Both effects push share prices upward, and the P/E multiple expands.</p><p>Notice that a pause does not need to be a cut. Markets look forward. If investors believe the last rate hike has already happened, they begin pricing in cheaper money immediately, often well before the first actual cut. This is why a central bank meeting can move stocks even when the rate itself does not change.</p><h4>How an investor reads a Fed meeting</h4><p>Rate decisions rarely come as a surprise, because markets spend weeks guessing them. What moves prices is the gap between what was expected and what the Fed says. Three things are worth watching. The first is the decision itself. The second is the Fed''s projections for where rates will be in the future, often shown as the number of cuts expected next year. The third is the tone of the press conference, especially phrases such as "higher for longer", which tell investors that borrowing costs will stay heavy for a long time.</p><p>A useful habit is to check what the 10-year Treasury yield did on the same day. If it jumped, valuation pressure was probably the main story. If it fell, relief was probably the main story. Looking at the sector at the same time also helps: if a single stock moves with the whole chip sector, the rate message is the likely cause. If it moves against the sector, something company-specific is probably happening as well.</p><h4>Real-world application: the semiconductor sector</h4><p>The 2022-2023 cycle is a clear case study. To fight inflation, the Federal Reserve raised rates aggressively, and chip stocks were pushed around by every hint about how long the high rates would last. When the Fed signalled that rates would stay "higher for longer", the 10-year Treasury yield surged. That compressed valuation multiples across the technology sector and caused a sharp selloff in capital-intensive businesses like Intel and TSMC, whose factories are expensive and slow to pay back.</p><p>The reverse came later. When the Fed held rates steady and acknowledged a "disinflationary process", meaning inflation was slowing, yields fell. The pressure on technology valuations eased, and semiconductor stocks rallied as investors priced in cheaper borrowing in the years ahead.</p><p>Putting the pieces together, you can see why chipmakers react so visibly. Their factories need borrowed money, their profits arrive years after the spending, and their valuations lean heavily on those future profits. All three features make them sensitive to the price of money. When you next read about a rate decision, ask three simple questions: did borrowing costs move, did bond yields move, and did the message about the future change?</p><h4>Recent Headlines in Practice</h4><p>The recent headlines tied to this lesson show how chip stocks react to the tone of the Fed as well as to its decisions. After the Federal Reserve cut its benchmark rate for the first time since 2020 in September 2024, CNBC noted that lower rates and bond yields tend to benefit tech stocks, and Nvidia gained 4% on the day. In the following session, though, Nvidia slipped 1.59% while the sector slipped 1.46%, so the rally did not simply keep going. In September 2023 the Fed held rates but signaled that another hike was possible, the 2-year Treasury yield reached its highest since July 2006, and Nvidia fell 2.94% the next day against a sector drop of 1.64%. A hold can still hurt when the message is higher for longer.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Nvidia &middot; 19 Sep 2023</p><p class="news-callout-headline">Stocks slide as Fed signals it''s not done hiking rates, Nasdaq falls 1.5%: Live updates</p><p>The Fed held rates steady but signaled higher for longer, and the 2-year yield hit its highest since July 2006. Nvidia had already lost 13.1% for the month, though it was still up about 194% in 2023, and it fell more than the sector, which fits a high-growth stock being sensitive to rate worries.</p><p class="news-callout-move">Next day: stock -2.94% vs sector (SOXX) -1.64%</p><a class="news-callout-link" href="https://www.cnbc.com/2023/09/19/stock-market-today-live-updates.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Interest rates set the price of money. Hikes and a "higher for longer" message raise borrowing costs and shrink valuation multiples, which hurts debt-funded, capital-intensive chipmakers. Cuts, pauses and falling bond yields do the opposite. Because the effect reaches every company, the whole sector often moves together.</p></div>',
 1),

(14, 'macro', 'Inflation Indicators (CPI & PCE) as Market Catalysts',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/macro-2.svg" alt="A CPI thermometer fills with red and a seesaw tips so the chip side drops while yields rise." loading="lazy" width="640" height="260"><figcaption>Hot CPI lifts yields and sinks chips</figcaption></figure><p class="lesson-lead">On certain mornings, one number published by a government statistics office can move the whole chip sector before breakfast. That number is inflation, and traders treat it as a preview of what the Federal Reserve will do next.</p><h4>What the two inflation reports measure</h4><p><strong>Inflation</strong> is the rate at which the prices of goods and services are rising. If a basket of groceries, rent, fuel and gadgets costs 3% more than it did a year ago, annual inflation is 3%. Two monthly reports dominate the news. The <strong>Consumer Price Index (CPI)</strong> tracks the prices of a fixed basket of things households buy. <strong>Personal Consumption Expenditures (PCE)</strong> covers a broader range of spending and adjusts as people change what they buy, and it is the measure the Federal Reserve itself prefers.</p><p>A related idea is "core" inflation, which strips out food and energy because those prices jump around for reasons that have little to do with the underlying economy. Analysts often look at the headline number and the core number side by side. If the headline is high because of an oil price spike but the core is calm, the Fed is less worried than the headline suggests.</p><h4>Why a price report moves stocks</h4><p>Here is the part that surprises many new investors: stocks do not react to inflation because shoppers are paying more for milk. They react to what inflation makes the central bank do. If prices are rising too fast, the Fed raises rates or keeps them high to slow spending. If inflation is cooling, the Fed has room to pause or cut. Inflation data is therefore the compass that points toward future interest rates.</p><p class="lesson-formula">Inflation report &rarr; expected Fed policy &rarr; bond yields &rarr; stock valuations</p><p>This chain links directly to the previous lesson. Interest rates act as gravity on stock valuations, so any report that changes the expected path of rates changes how much investors will pay for future profits. That is why every monthly release is watched so closely, and why a single report can shift the entire market within minutes of publication.</p><p>What counts is the number against what economists expected, not the number by itself. Before each release, analysts publish a <strong>consensus forecast</strong>, an average of their predictions. If the consensus says 3.8% and the actual figure is 3.5%, that is good news even though 3.5% is still high. If everyone expects 3.2% and the figure is 3.4%, that is bad news even though inflation is falling. Markets move on surprises.</p><h4>How hot inflation data pushes stocks down</h4><p>When inflation comes in "<strong>hotter</strong>" than economists expected, it signals that the economy is still running too fast, with demand outpacing supply and prices continuing to climb. That worries investors because the Fed''s usual answer is to keep interest rates high, or even raise them again, to cool spending. The fear of future hikes is often enough to move prices before the Fed does anything at all.</p><p>The impact on technology and semiconductor stocks tends to be sharp and quick. Higher expected rates mean higher future borrowing costs for companies that build expensive factories, and they also compress valuation multiples, because future profits are discounted at a higher rate. High-growth and capital-intensive sectors, with so much of their value sitting in the future, typically sell off immediately.</p><h4>How cool inflation data pushes stocks up</h4><p>The opposite surprise helps share prices. When inflation comes in "<strong>cooler</strong>" than expected, it shows that the central bank''s efforts are working. That gives the Fed the green light to pause hikes or even begin cutting, and investors rush to price in cheaper borrowing costs and lower bond yields. The result is often a <strong>relief rally</strong>, where money flows back into equities and share prices rise quickly because the biggest worry has just been taken off the table.</p><p>A cooler report does not guarantee a gain for every stock. Companies that benefit most are those whose profits depend on cheap financing or on a recovery in spending, which makes hardware and memory makers natural candidates. The next callout shows a memory and electronics giant rising well ahead of the sector after a cooler CPI report, as Treasury yields tumbled.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Samsung &middot; 14 Nov 2023</p><p class="news-callout-headline">US CPI comes in cooler than expected for October</p><p>October CPI slowed to 3.2% year over year, below forecasts. Bond yields tumbled and expectations of a rate pause rose, which lowered the cost of capital and boosted hopes for a hardware recovery. Samsung gained well ahead of the sector.</p><p class="news-callout-move">Next day: stock +1.98% vs sector (SOXX) +0.73%</p><a class="news-callout-link" href="https://www.cnbc.com/2023/11/14/cpi-inflation-report-october-2023.html" target="_blank" rel="noopener">Read the source</a></aside><h4>When good news is already in the price</h4><p>One caution deserves its own section. Markets are forward-looking, so a piece of good news is sometimes bought before it arrives. If investors have been pushing a stock higher for weeks in the hope that inflation will cool, a cool report only confirms what the price already reflects. At that point, traders may sell to lock in gains, a behaviour known as <strong>profit-taking</strong>, and the stock can stay flat or even fall on good news.</p><p>This is not a contradiction. It is the reason professionals say that prices move on surprises rather than on facts.</p><h4>Real-world application: the semiconductor sector</h4><p>Autumn 2023 shows the pattern. When October CPI came in cooler than expected, the market priced in a rate pause and an easier funding environment, and chip stocks rose, as the Samsung example above showed.</p><p>When you read an inflation release yourself, follow a simple routine. First, find the consensus forecast and compare it with the actual figure for both headline and core. Second, check what Treasury yields did, since they are the quickest summary of how the rate outlook changed. Third, look at whether the stock moved with the sector or apart from it, and whether the stock had already run up beforehand. That sequence turns a confusing news day into a short, logical story.</p><h4>Recent Headlines in Practice</h4><p>None of the new headlines is a CPI or PCE print, so the closest example is another scheduled macro number: the US jobs report. The July 2024 report disappointed, stoked recession concerns and raised worries that the Fed was behind the curve on cuts, and chip stocks sold off, with Nvidia down 6.4% on the Monday. The pattern matches an inflation surprise, because a data point changes what investors expect from the Fed and prices adjust at once. The following session was a rebound for Nvidia of 3.78% against the sector''s 0.91%, a reminder that the first reaction to a data surprise can be partly reversed. Likewise, the Fed''s September 2023 message that another hike could come moved Nvidia down 2.94% the next day.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Nvidia &middot; 5 Aug 2024</p><p class="news-callout-headline">Nvidia, Super Micro Computer lead AI trade carnage</p><p>A disappointing July jobs report stoked recession concerns and worries that the Fed was behind the curve on cuts. Nvidia fell 6.4% on the headline Monday and was nearly 29% below its 52-week high, and then rebounded the next day by much more than the sector.</p><p class="news-callout-move">Next day: stock +3.78% vs sector (SOXX) +0.91%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/08/05/nvidia-super-micro-computer-lead-ai-trade-carnage-with-both-stocks-down-more-than-12percent.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>CPI and PCE matter because they steer the Fed, and the Fed steers bond yields and valuations. Hotter-than-expected readings tend to push chip stocks down; cooler-than-expected readings tend to lift them. The surprise versus expectations moves prices, not the raw number.</p></div>',
 2),

(15, 'macro', 'Consumer Demand Cycles & Inventory Gluts',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/macro-3.svg" alt="A warehouse fills with unsold chip boxes while a chart of chip orders falls." loading="lazy" width="640" height="260"><figcaption>Gluts mean cancelled orders</figcaption></figure><p class="lesson-lead">A fashion retailer that misjudges demand ends up with a rack of unsold coats. A chipmaker that misjudges demand ends up with a warehouse full of unsold chips. And the further you are from the shopper, the bigger the mistake gets.</p><h4>How a chip travels from factory to shopper</h4><p>To understand chip stocks, it helps to picture the whole supply chain. At the start sit the "<strong>upstream</strong>" companies: foundries that manufacture chips and memory makers that produce storage and working memory. In the middle are device brands that buy those chips and assemble them into PCs, smartphones and servers. At the end, "<strong>downstream</strong>", are the consumers and businesses who buy the finished products. Orders travel up the chain, and money travels back down it.</p><p class="lesson-formula">Consumers &rarr; device brands (downstream) &rarr; chip orders &rarr; chipmakers (upstream)</p><p>Each link in this chain keeps a stock of parts and finished goods so that it never runs out. That stock is called <strong>inventory</strong>, and it is the key to the whole lesson. A company that holds too little inventory misses sales. A company that holds too much has cash trapped in boxes that are slowly becoming obsolete.</p><h4>The bullwhip effect and the chip cycle</h4><p>Flick the handle of a whip gently and the tip cracks violently. Supply chains behave the same way, and the phenomenon is known as the <strong>bullwhip effect</strong>. A small change in consumer demand at the shop counter turns into a much larger swing in manufacturing orders at the top. Suppose shoppers buy 5% fewer laptops. Laptop brands, nervous about the trend, may cut their chip orders by 20% or more, because they also want to run down the stock they already hold. The chipmaker sees a collapse in orders even though consumers only slowed down a little.</p><p>A second force makes the swings bigger: chips take a long time to build. A new factory can take years from planning to production, so capacity decisions are made long before anyone knows what demand will be. The result is <strong>cyclicality</strong>. The industry swings between periods of shortage, when buyers compete for scarce chips and prices rise, and periods of oversupply, known as a <strong>glut</strong>, when too many chips chase too few buyers and prices fall. These swings are driven mostly by consumer purchasing habits and by how aggressively the supply chain builds stock.</p><h4>How an inventory glut pushes stocks down</h4><p>A glut usually begins with weak demand. If consumers suddenly stop buying electronics, because the economy is weak or because everyone bought a new laptop during a pandemic and does not need another, brands are left with warehouses full of unsold products. That is the first domino.</p><p>The second domino is <strong>order cancellations</strong>. Brands with full warehouses stop ordering new chips from their upstream suppliers until the stock is sold. From the chipmaker''s side, this looks like a sudden drop in demand, and it often arrives with little warning because orders fall faster than consumer sales do.</p><p>The third domino is the <strong>margin collapse</strong>. The chipmaker is left with factories built for higher volumes and with inventory it cannot sell at current prices. To clear that stock, it cuts prices, which destroys profit margins. Because a factory has large fixed costs, falling prices and falling volumes together hit profit very hard. Share prices often drop steeply, sometimes long before the quarterly results show the damage.</p><h4>How a recovery cycle pushes stocks up</h4><p>Gluts do not last forever. Eventually the stockpile of electronics is slowly sold off to consumers. This painful waiting period is known as <strong>inventory digestion</strong>, and during it chipmakers still suffer because brands are living off their stock rather than placing new orders. Every unit sold from a warehouse is a unit that does not need to be built.</p><p>Once the warehouses are empty, the logic reverses. Brands must restock for their next generation of products, so factory orders resume, often with some urgency. The influx of orders lets chipmakers raise prices again, because supply is no longer greater than demand. Higher prices on the same factories lift profit margins quickly, and share prices tend to climb. This <strong>pricing power</strong> is what investors are looking for when they talk about a cycle turning.</p><p>A subtle point is that stock prices usually turn before the news does. Investors buy shares in anticipation of recovery, long before the headlines say the glut is over. That means a terrible data point near the bottom of the cycle can be met with a flat or even rising share price, because everyone already expected it.</p><h4>Real-world application: the semiconductor sector</h4><p>Early 2023 was a textbook downturn. PC shipments fell sharply, and downstream PC makers were sitting on very large inventories. The shock travelled upstream and hit memory chip makers such as Micron and Samsung hard, causing deep revenue declines and stock selloffs as memory prices fell to rock bottom.</p><p>By late 2023 the picture had begun to change. As inventories were worked down, inventory digestion finished, brands could resume factory orders, and that helped trigger a recovery in memory chip stocks.</p><p>When you analyse a chip stock yourself, a few questions help locate the stage of the cycle. Are device sales growing or shrinking? Are brands talking about "clearing inventory" or "restocking"? Are chip prices still falling, or have they stopped falling? Each answer tells you which of the dominoes are falling and in which direction. Remember too that the same news can mean different things at different points of the cycle: a poor sales report in a boom is a warning, but at the bottom of a glut it may simply be the last bad number before things improve.</p><h4>Recent Headlines in Practice</h4><p>Consumer demand cycles show up in headlines about PCs and memory. PC shipments fell for a fourth straight quarter in Q4 2022 as demand stayed muted, and Intel rose 1.47% the next day, a little ahead of the sector''s 1.22%. In Q1 2023 global shipments fell by roughly a third, and Intel''s Client Computing group reported $5.8 billion of revenue, down 38% year on year, yet the stock moved -0.52% against the sector''s -0.53%. On the memory side, DRAM prices fell about 20% in Q1 2023 amid an inventory glut and weak demand, with analysts expecting a further 10-15% drop in Q2, and Micron fell 0.71% while the sector rose 1.65%. Weak demand matters, but the next-day reaction can be small or even opposite to the headline.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Intel &middot; 10 Apr 2023</p><p class="news-callout-headline">Global PC shipments dropped by a third in Q1</p><p>After a spike in the first two years of the pandemic, global PC shipments fell for a fourth consecutive quarter, and Intel''s Client Computing revenue fell 38% year on year. The stock moved almost exactly with the sector, so the shipment data was not punished more than the group.</p><p class="news-callout-move">Next day: stock -0.52% vs sector (SOXX) -0.53%</p><a class="news-callout-link" href="https://techcrunch.com/2023/04/10/global-pc-shipments-dropped-by-a-third-in-q1/" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Chip stocks swing with inventory cycles because small changes in consumer demand are amplified up the supply chain. Gluts mean cancelled orders, price cuts and falling stocks; once inventory is digested, orders resume and pricing power returns. Because much of the bad news is priced in near the bottom, stocks often turn before the headlines do.</p></div>',
 3),

(16, 'macro', 'Sector-Wide Growth Forecasts (SIA Data)',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/macro-4.svg" alt="Industry sales bars rise toward dashed forecast bars with an arrow pointing to an AI demand badge showing plus 13 percent." loading="lazy" width="640" height="260"><figcaption>SIA data shows if growth is real</figcaption></figure><p class="lesson-lead">One company''s earnings tell you how that company did. To know whether the whole chip industry is shrinking or growing, you need someone to add everyone up. That is exactly what the Semiconductor Industry Association does.</p><h4>Why industry-wide numbers matter</h4><p>Imagine you hear that five chipmakers each reported a weak quarter. That could mean five separate problems: a delayed product here, a lost customer there, a factory accident somewhere else. Or it could mean one shared problem, such as customers buying fewer chips overall. You cannot tell from the company reports alone. That is the gap that industry associations fill.</p><p>Groups such as the <strong>Semiconductor Industry Association (SIA)</strong> collect and combine sales data from across the entire global market and publish it, usually monthly, along with forecasts for the year ahead. If the SIA reports that global sales are down, then it is one shared problem, and the cause is probably the industry cycle rather than any single company''s mistakes. This gives investors a comprehensive and relatively unbiased view of the sector''s overall health, because the figures are compiled from many firms rather than from one company''s own presentation.</p><p>The data also helps institutional investors, such as pension funds and asset managers, decide whether a recent price movement is a temporary blip or a longer <strong>cyclical shift</strong>. A stock that jumps one week might be reacting to rumours, but a stock that jumps after official data confirms a turning point is reacting to something more lasting.</p><h4>Reading the numbers: year over year and month over month</h4><p>Industry reports usually give two kinds of comparison, and mixing them up causes a lot of confusion. <strong>Year over year (YoY)</strong> compares this month with the same month a year earlier. It removes seasonal patterns, so it is the best way to judge how large a slump or boom really is. <strong>Month over month (MoM)</strong> compares this month with the one before it, so it is the first place a turn shows up. A report can show a large YoY decline and a small MoM increase at the same time, and that combination often means the worst is passing.</p><p>Another point to keep in mind is that sales are measured in dollars, not units. Falling chip prices can reduce total sales even when the number of chips shipped is steady, so a sales decline might reflect price cuts during a glut as much as weaker demand. That is why analysts look at the SIA numbers together with inventory and pricing news, as the previous lesson described.</p><h4>How negative data and forecasts push stocks down</h4><p>When rumours of a slowdown have been circulating, an official report showing a double-digit drop in global sales <strong>validates fears</strong> and turns worry into fact. Investors who were guessing now have a number to point to, and many of them sell.</p><p>The reaction tends to be broad. Analysts use industry data to lower revenue estimates for the whole sector, which causes a <strong>synchronized selloff</strong> that drags down even the strongest companies. The reason is that the "pie" these companies are fighting over is shrinking, so even a firm that is gaining market share has a smaller pie to share.</p><p>The third effect is a freeze in <strong>capital expenditure (CapEx)</strong>, the money companies spend on factories and equipment. Poor industry forecasts signal to chipmakers that they should delay building new factories, and that hurts the suppliers that sell them manufacturing tools. So a bad forecast reaches deep into the supply chain.</p><h4>How positive data and forecasts push stocks up</h4><p>The most powerful positive signal is <strong>calling the bottom</strong>. After a long slump, the first month-over-month increase in global sales tells the market that the worst is probably over. Buyers who want to be early in the recovery rush in, and prices can rise before any single company has reported better results. Professionals often say that the market bottoms when the news is still bad, and data like this is how they spot it.</p><p>Optimistic forecasts do more when they point to a clear reason for growth. If an association says that sales will grow because of cloud computing or artificial intelligence, investors learn where the new demand will come from. This <strong>identifying new catalysts</strong> step gives the market the confidence to price in future expansion. Finally, a strong industry outlook <strong>restores confidence</strong> among large investors, who may then allocate billions of dollars back into the sector. The callout below shows memory-driven recovery data lifting a large Korean chip maker, though less than the sector as a whole.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Samsung &middot; 1 Nov 2023</p><p class="news-callout-headline">SIA says global semiconductor sales increased month-to-month in September</p><p>The SIA data confirmed that memory production cuts and the absorption of downstream inventory were producing a durable recovery in pricing. Samsung rose, though less than the broader sector rally on the same day.</p><p class="news-callout-move">Next day: stock +1.60% vs sector (SOXX) +2.27%</p><a class="news-callout-link" href="https://www.semiconductors.org/global-semiconductor-sales-increase-1-9-month-to-month-in-september/" target="_blank" rel="noopener">Read the source</a></aside><h4>Why a rising tide does not lift every boat</h4><p>A positive industry forecast is not the same as a positive forecast for every company. The question to ask is how directly a company''s products connect to the growth being forecast. If the forecast is driven by AI accelerators, then a company that makes AI accelerators should benefit most, while a company that mainly sells PC and server processors may benefit much less. In other words, a forecast of strong growth can lift sentiment across the whole sector while a company whose products are not the main source of that growth sees little benefit.</p><h4>Real-world application: the semiconductor sector</h4><p>The SIA numbers made a clear story through 2023. Its reports confirmed how severe the cyclical downturn was, and heavy pressure on chip stocks continued. Later in the year, the SIA reported a month-to-month sales increase in September, the first clear macro confirmation that the chip market had bottomed out.</p><p>To use this in practice, check three things whenever an industry report appears. Is it a year-over-year or a month-over-month figure? Is the change a surprise compared with what analysts expected? And does the growth driver match what the company you are studying actually sells? Those questions help you tell the difference between a headline that matters and one that is already in the price.</p><h4>Recent Headlines in Practice</h4><p>Monthly sales figures and industry forecasts work as growth signals for the whole chip chain. TSMC''s July 2026 revenue of NT$467.58 billion was up 44.7% year on year, and August revenue of NT$514.8 billion rose 53.3%, a fourth straight monthly rise driven by AI chip demand. The stock gained 0.86% and 1.22% the following days, close to and a little under the sector''s 0.91% and 1.86%, so strong numbers moved TSMC with its peers rather than ahead of them. Forecasts can also point to a slowdown: in September 2026 TrendForce expected conventional DRAM contract price growth to moderate to 13-18% in Q3 after up to 98% in Q1, and Micron fell 1.61% while the sector rose 1.64%. Growth that is slowing, even from a very high level, may be read as less exciting.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Micron &middot; 7 Sep 2026</p><p class="news-callout-headline">DRAM contract prices forecast to grow only 13-18% in Q3</p><p>TrendForce cited the limited ability of PC and smartphone buyers to absorb more price increases. Prices were still forecast to rise, yet Micron slipped while the sector gained, which may reflect investors focusing on the slower pace of growth, though the article does not report their motives.</p><p class="news-callout-move">Next day: stock -1.61% vs sector (SOXX) +1.64%</p><a class="news-callout-link" href="https://www.theregister.com/storage/2026/09/07/dram-contract-prices-forecast-to-grow-only-13-18-in-q3/5294776" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Industry-wide data from groups like the SIA shows whether a slump or a boom is real. Deep declines trigger sector-wide selloffs and CapEx freezes, the first monthly rise calls the bottom, and a forecast with a clear driver such as AI restores confidence. Always ask how directly a company''s products tie into the growth being forecast.</p></div>',
 4),

(17, 'macro', 'Macro "Soft Landings" and Enterprise Spending',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/macro-5.svg" alt="A plane glides down onto a runway for a soft landing while the data center racks light up." loading="lazy" width="640" height="260"><figcaption>Soft landing unlocks IT budgets</figcaption></figure><p class="lesson-lead">A chip order often starts as a meeting where a chief executive decides whether to approve next year''s IT budget. When the CEO feels confident about the economy, the answer is yes. When a recession looks likely, the answer is "not now".</p><h4>What a soft landing is</h4><p>When inflation is too high, central banks raise interest rates to slow the economy. The danger is that they slow it too much. If rates are raised too far, spending collapses, companies lay off workers and the economy slips into a <strong>recession</strong>, which is a period of falling output and rising unemployment. A <strong>soft landing</strong> is the happy middle: rates are raised just enough to cool inflation, but not so much that they trigger a severe recession. Think of a pilot bringing a plane down gently instead of dropping it onto the runway.</p><p>Soft landings are difficult to achieve, because the effect of higher rates arrives with a delay and policymakers are steering with old data. That is why the phrase is often used with a sense of relief, and why markets react strongly when the data suggest that one has been achieved.</p><h4>Who buys the chips: consumers and enterprises</h4><p>Earlier lessons looked at consumer demand for laptops and phones. For many technology companies, however, the biggest source of revenue is <strong>enterprise spending</strong>, sometimes called B2B (business to business) spending. This means large corporations buying servers, cloud computing capacity, networking equipment and the rest of the IT infrastructure that keeps their operations running. A single bank or retailer may order more computing power in a year than thousands of households.</p><p>Enterprise spending is lumpy and planned. Large firms set budgets months ahead, and they commit billions of dollars when they feel secure. Most of that spending is classed as <strong>capital expenditure (CapEx)</strong>, money spent on long-lasting assets such as data centers, rather than day-to-day costs. Because CapEx can be delayed without stopping the business, it is among the first things executives cut when they get nervous.</p><h4>The confidence factor</h4><p>Corporate budgets follow macroeconomic confidence. If chief executives fear a recession, they freeze spending and wait. If they feel that the economy has achieved a safe soft landing, they invest in technology aggressively. This chain connects the broad economy to the orders that land on a chipmaker''s desk.</p><p class="lesson-formula">Macro confidence &rarr; enterprise IT budgets &rarr; server and cloud orders &rarr; chip demand</p><p>Investors watch indicators that reveal this confidence early. <strong>Gross domestic product (GDP)</strong> measures the total output of the economy and shows whether it is growing or shrinking. The <strong>Purchasing Managers'' Index (PMI)</strong> is a survey of factory managers: a reading above 50 means activity is expanding, and below 50 means it is shrinking. Jobs reports show whether employers are still hiring. Together, they sketch the mood in boardrooms before the budgets are announced.</p><h4>How recession fears push stocks down</h4><p>When GDP growth turns negative or recession fears peak, corporations slash their capital spending. They delay server upgrades, pause moves to the cloud and freeze hiring. These <strong>IT budget freezes</strong> are the first link in a domino effect.</p><p>The second link is the knock-on to suppliers. A spending freeze hits enterprise software and hardware providers, which then cut orders for the high-end chips that power data centers and corporate networks. Equipment makers further up the chain are hit as chipmakers postpone their own factory expansions, so the damage grows with each step away from the customer.</p><p>The third link is <strong>valuation downgrades</strong>. Analysts lower earnings forecasts for the entire technology supply chain, so share prices fall, often long before the recession officially arrives. Because markets look ahead, they react to the fear of lower spending, not only to the lower spending itself.</p><h4>How a soft landing pushes stocks up</h4><p>When data shows solid growth even with high interest rates, recession fears fade. Corporations <strong>unlock their budgets</strong> and green-light projects that were delayed. The effect is a release of pent-up demand, similar to a dam opening.</p><p>Confidence also changes what companies choose to buy. Sure of a stable economy, firms rush to invest in new technologies, such as the infrastructure that powers AI, because they do not want to fall behind competitors. Analysts call this the fear of missing out, or FOMO, spending. Competitive pressure turns a modest budget increase into a large order book for the companies that supply the chips.</p><p>The final stage is the <strong>revenue multiplier</strong>. The influx of corporate cash is a windfall for data center providers and chipmakers, and it drives earnings beats, meaning results better than analysts forecast, which push stock prices higher. Moderate data on jobs can also help if it suggests the economy is cooling just enough to ease wage inflation without tipping into recession. Investors sometimes call this a "Goldilocks" reading: not too hot, not too cold.</p><h4>Reading macro data without over-reading it</h4><p>Macro numbers rarely point in a single direction, so it helps to keep a few habits. Compare each figure with the consensus forecast, because the surprise is what moves prices. Look at several indicators together instead of relying on one. And separate the macro effect from company news, since the two can pull in opposite directions on the same day. A strong economy does not rescue a company that has just given weak guidance, which is a forward-looking statement from management about expected sales or profit.</p><p>It also helps to remember that "good news" can have two faces. Very strong growth may remind investors that inflation could stay high and rates may not fall, which is a reason for caution rather than celebration. The best case for enterprise chip demand is the middle ground: growth that is steady, inflation that is easing and rates that are no longer rising.</p><h4>Real-world application: the semiconductor sector</h4><p>Throughout much of 2022 and 2023, economists widely predicted a severe US recession. Many corporations tightened their belts and delayed hardware upgrades, which weighed heavily on chip stocks tied to enterprise demand. Then growth data began to come in stronger than expected, and it was widely seen as evidence of the elusive soft landing.</p><p>That kind of evidence boosts confidence in enterprise technology spending and acts as a catalyst for chip stocks tied to data centers and corporate IT infrastructure. Even so, a single day''s price move is the net result of many forces. A leading foundry can rise while the sector falls if another large chipmaker''s weak guidance drags the sector down that day, because the macro effect and the company effect can pull in different directions.</p><p>The practical lesson is to read macro data as a story about corporate behaviour. Ask whether the numbers make a chief executive more or less willing to sign a large purchase order, and then ask who in the chip supply chain would feel that decision first.</p><h4>Recent Headlines in Practice</h4><p>Enterprise spending on AI is the macro engine behind chip demand, and several headlines test how long it can last. In February 2026, ahead of Nvidia''s earnings, Alphabet, Microsoft, Meta and Amazon were expected to spend nearly $700 billion combined on AI in 2026, over 60% above 2025, and investors were scrutinizing hyperscaler capex and free cash flow. In January 2025 DeepSeek''s cheaper model raised doubts about AI infrastructure spending and Nvidia dropped nearly 17% in one day, then rebounded 8.93% the next session against the sector''s 0.45%. In July 2026, AMD, Intel and Micron extended losses amid worries over how long AI spending can keep rising, and Micron fell 9.94% against the sector''s 5.38% drop. Rising budgets support prices, and doubts about them shake prices.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Nvidia &middot; 24 Feb 2026</p><p class="news-callout-headline">Nvidia earnings report collides with Wall Street skepticism over AI spending</p><p>Hyperscaler spending, expected to be over 60% above 2025, drives demand for Nvidia''s products, but investors were also questioning that spending. The stock gained a little less than the sector, so the two forces seem to have roughly balanced.</p><p class="news-callout-move">Next day: stock +1.41% vs sector (SOXX) +1.65%</p><a class="news-callout-link" href="https://www.cnbc.com/2026/02/24/nvidia-earnings-collide-with-wall-street-skepticism-over-ai-spending.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Enterprise chip demand depends on corporate confidence. Recession fears freeze IT budgets and drag down the tech supply chain, often before any recession arrives; a soft landing, shown by strong GDP and moderate inflation, unfreezes budgets. Sector-wide moves can still be offset by company news on the same day.</p></div>',
 5),

(4, 'corporate', 'Strategic Restructuring and Spinoffs',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/corporate-1.svg" alt="A company building splits off a smaller chip unit that floats away, grows on its own and shows a rising value arrow." loading="lazy" width="640" height="260"><figcaption>A spinoff lets the market price a hidden unit on its own</figcaption></figure><p class="lesson-lead">Sometimes the biggest news a company can announce is that it is taking itself apart. Layoffs, closed divisions and spinoffs can send a stock soaring or crashing, and the difference comes down to what the market thinks the move says about the business.</p><h4>What restructuring and spinoffs actually are</h4><p>Most people picture a company as one solid block, but a large corporation is really a bundle of businesses stitched together over many years. Sometimes the bundle stops working well, and management decides to change it. <strong>Restructuring</strong> is the umbrella word for a fundamental change in how a company operates: laying off a large share of the workforce, creating new business units, merging or closing divisions, or shutting down a product line that keeps losing money. Think of it as a major renovation of a house you still live in. It is noisy, expensive and disruptive while it lasts, and the whole point is to leave a healthier building afterwards.</p><p>A <strong>spinoff</strong> is a more specific tool. The parent company takes one of its divisions and separates it into its own independent, publicly traded company, so that shareholders can hold and value the two businesses separately. If you owned shares in the parent before the split, you usually end up owning shares in both pieces. Nothing about the factories or customers changes on day one, but the market now puts a separate price tag on each part.</p><p>What ties these actions together is the goal. Management is usually trying to unlock "hidden" shareholder value, make the core business leaner, or isolate heavily unprofitable segments so that they stop dragging down everything else. The basic logic fits in one line.</p><p class="lesson-formula">Messy conglomerate &rarr; separate, focused pieces &rarr; each piece valued on its own merits</p><h4>How restructuring and spinoffs can push a stock up</h4><p>The first way is <strong>unlocking value</strong>. Imagine a slow-growing parent company that quietly owns a fast-growing, highly profitable division. Investors tend to value the whole company as a blend, so the star division gets dragged toward the parent''s lower <strong>valuation multiple</strong>, which is simply how many dollars the market will pay for each dollar of earnings. As a purely illustrative example, if the parent as a whole earns a multiple of 10 but the division alone would earn a multiple of 25 as a standalone business, then splitting them lets the market pay a fair price for the star. A spinoff, or even just a plan to run the division on its own, lets that higher valuation show up.</p><p>An announced plan to separate a division usually earns only a partial reward: the market pays for results it can see, and a promise of future separation is not the same as a finished spinoff.</p><p>The second way is <strong>cost savings</strong>, sometimes called the layoff effect. Mass layoffs are painful news for the people involved, yet Wall Street often rewards them. Cutting thousands of jobs, or closing a failing plant, removes hundreds of millions or even billions of dollars from the yearly expense bill, and that flows straight into future profit margins.</p><p>The third way is <strong>focusing on core strengths</strong>. A bloated business with many unrelated units forces management to spread its attention and cash thinly. Shedding a division that does not fit lets the team concentrate on what it does best. Exiting a business that only loses money also frees cash and engineers for the lines that are profitable.</p><p>Sometimes a company does not separate a division completely but sells a slice of it, for example by selling a minority of a listed subsidiary''s shares while keeping control. Investors often welcome this, because the cash can fund the core business without taking on new debt or giving up control of the unit.</p><h4>When restructuring signals distress</h4><p>The same toolbox can send the opposite message. A sudden, desperate restructuring can tell the market that the company''s core strategy has failed and revenue is collapsing. This is the <strong>admitting defeat</strong> problem. Investors ask why a healthy business would need to cut so deeply and so quickly, and the layoffs read as a retreat rather than as discipline. Timing and context do most of the work here: a company trimming fat from a position of strength looks confident, while one slashing everything at once looks like it is in trouble.</p><p>The second danger is <strong>execution risk</strong>. Turnaround plans take years and cost billions, and they rarely run to schedule. If investors doubt that management can carry out the plan, the stock faces heavy selling pressure even while the plan is still just a slide deck. Cost cuts only help if the underlying business is still worth saving, so the market keeps watching revenue and customers as well as expenses.</p><h4>Intel, a restructuring case study in two acts</h4><p>Intel''s story shows how one company can use several tools from this lesson, with different reactions. Act one was the spinoff of its Altera business, a move aimed at unlocking value. Act two was an internal restructuring in June 2023: Intel reorganized its core manufacturing business to operate like a completely separate foundry with its own <strong>Profit &amp; Loss (P&amp;L)</strong> statement, treating its own product groups as foundry customers. A P&amp;L statement lists a unit''s revenue, costs and resulting profit or loss, so giving the factories their own lets investors see how design and manufacturing each perform.</p><p>That transparency cuts both ways. The stock slipped 0.58% the next day while the sector rose 0.46%, because the new reporting laid bare how large the foundry''s operating losses really were. Hidden problems are easier to ignore than visible ones, and a reorganization that exposes them can make the stock look worse in the short run, even if the long-run discipline is healthy.</p><p>When you read the next restructuring headline, check three things. Is the company acting from strength or from a crisis? Is the benefit visible in profit margins or in a clearer valuation of a division? And is there a believable plan with a believable team to carry it out?</p><h4>Recent Headlines in Practice</h4><p>The recent headlines mapped to this lesson show restructuring from two angles: shrinking to fix a weak core, and reshaping the portfolio by selling or buying units. Intel''s August 2024 plan to cut more than 15% of its workforce, about 15,000 jobs, was announced with weak results and guidance, so the stock fell sharply instead of celebrating the savings. Its April 2025 agreement to sell 51% of its Altera unit to Silver Lake raised about $4.4 billion in net cash, yet the stock still slipped the next day while the sector edged up. Nvidia''s purchases of Run:ai and Groq''s assets were growth-minded deals, and its stock rose after both. The common thread is that investors judge the health of the core business behind a move, not the move alone.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Intel &middot; 1 Aug 2024</p><p class="news-callout-headline">Intel lays off 15% of its staff and its stock tumbles as it struggles to turn around its ailing business | CNN Business</p><p>Intel paired the cuts with weak quarterly results and guidance, so investors may have focused on how deeply the business was struggling rather than on the planned $10 billion of savings. The cuts were expected to hit R&amp;D, marketing and administrative roles.</p><p class="news-callout-move">Next day: stock -26.06% vs sector (SOXX) -5.32%</p><a class="news-callout-link" href="https://edition.cnn.com/2024/08/01/business/intel-layoffs-chips" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Restructuring and spinoffs are neutral tools. A spinoff that reveals a hidden gem or a cost cut from a position of strength can lift a stock, while an emergency overhaul signals distress and execution risk. Ask what the move says about the health of the core business.</p></div>',
 1),

(18, 'corporate', 'Capital Allocation: Stock Splits and Buybacks',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/corporate-2.svg" alt="A share pie cut into ten slices, with one slice bought back and flying to an earnings per share chart whose bar then rises." loading="lazy" width="640" height="260"><figcaption>Splits cut the slices, buybacks lift earnings per share</figcaption></figure><p class="lesson-lead">When a company makes more cash than it needs, someone has to decide where it goes. Two of the most visible answers are buying back shares and splitting them, and the market reads each very differently.</p><h4>Where does a company''s cash go?</h4><p>Imagine a company that earns far more cash than it needs to keep the lights on. Somebody has to decide what to do with the surplus, and that decision is called <strong>capital allocation</strong>. Management can invest in research and development (R&amp;D), build new factories, buy other companies, pay down debt, or return cash directly to shareholders through <strong>buybacks</strong> or dividends. Each choice sends a message about how management sees the future, and each one has an <strong>opportunity cost</strong>: every dollar spent on one option is a dollar that cannot be spent on another.</p><p>A dividend is the plainest form of return, a cash payment per share. Intel''s 2023 dividend cut shows how tight the trade-off can be. In February 2023 it cut its quarterly payout by 65.7%, from $0.365 to $0.125 per share, to save about $4 billion a year and fund its fab expansion. Income-focused investors were disappointed, yet the stock still rose 0.55% the next day, trailing a 3.29% sector rally, because the market accepted that protecting cash and credit ratings mattered more during a capital-intensive buildout.</p><p>This lesson focuses on the two best-known ways a successful company deals with its good fortune: buying back its own shares and splitting them. They sound similar, since both change the number of shares, but they do very different things.</p><h4>Share buybacks: fewer slices of the same pie</h4><p>In a <strong>share buyback</strong>, the company uses its own cash to buy its shares on the open market and then retires them. The total supply of shares shrinks, so each remaining share represents a slightly larger piece of the company. Because the company is spending real cash, a big buyback is one of the strongest signals management can send. It says: we believe our stock is undervalued, and our future cash flow is secure enough that we can afford to spend this money on ourselves.</p><p>Buybacks also change a key number called <strong>earnings per share (EPS)</strong>, which is net profit divided by the number of shares outstanding. Here is a simple, illustrative example. Suppose a company earns $1,000 million in profit with 1,000 million shares outstanding, so EPS is $1.00. It then retires 100 million shares. The profit is the same, but it is now divided among 900 million shares, so EPS rises to about $1.11, an increase of 11% without earning a single extra dollar.</p><p class="lesson-formula">EPS = net profit &divide; shares outstanding: $1,000M &divide; 1,000M = $1.00, then $1,000M &divide; 900M &asymp; $1.11</p><p>Wall Street valuation models lean heavily on EPS, so this arithmetic makes the stock look more attractive on paper. That is why people say buybacks "artificially" boost EPS: the business did not improve, the denominator just got smaller. The effect is real in the numbers but is only as good as the cash behind it. A buyback funded by strong, predictable cash flow is a sign of strength, while one funded by borrowing, or one that crowds out important investment, deserves more suspicion.</p><p>Context matters too. Resuming buybacks signals confidence, but it can be read with caution if it arrives before the recovery is secure, for example when investors question spending on repurchases before operating cash flow has clearly turned positive.</p><h4>When buybacks make the most sense: visible cash flow</h4><p>The safest buybacks come from companies whose future cash is easy to see. ASML makes the extreme ultraviolet (EUV) lithography machines that advanced chipmakers cannot do without, and it holds a very large backlog of orders. With multi-year revenue effectively locked in, a company like that can return capital without worrying that a downturn would leave it short of cash.</p><p>The lesson is that a buyback is a confirmation of strength, not a magic trigger. It tends to matter most when the market has doubts about cash; where cash flow is already well understood, the announcement may add little.</p><h4>Stock splits: a smaller slice size, not a smaller pie</h4><p>A <strong>stock split</strong> divides each existing share into several new shares, for example in a 10-for-1 split. The overall value of the company does not change, only the price of each individual share. The easiest way to remember it is to think of cutting a pizza into more slices: the pizza is the same size, but each slice is smaller and easier to pick up.</p><p class="lesson-formula">1 share &times; $1,000 &rarr; 10 shares &times; $100 = still $1,000</p><p>In illustrative numbers, a company with 1 billion shares at $1,000 each is worth $1 trillion. After a 10-for-1 split it has 10 billion shares at $100 each, which is still $1 trillion. If you owned one share before, you own ten after, and your total stays exactly the same. Nothing about profits, factories or competition has changed.</p><p>So why do stocks often rise on split news? The reason is <strong>retail accessibility</strong>. A $100 share is much easier for individual investors and company employees to buy as a whole share than a $1,000 one, and cheaper prices can boost trading volume (liquidity) and participation in the options market. More buyers can mean more demand, even though the underlying value is unchanged.</p><p>Nvidia announced a 10-for-1 split in May 2024, after a period of explosive, AI-driven growth had sent its price to roughly $1,000 per share. The stated aim was to make the equity more accessible to employees and retail investors, which gave the stock a psychological boost.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">NVDA &middot; 22 May 2024</p><p class="news-callout-headline">Nvidia announces 10-for-1 stock split following massive earnings beat</p><p>Nvidia paired the split with record quarterly earnings and a dividend increase. The per-share price fell from roughly $1,000 to $100, improving access for retail buyers, and the stock rose while the sector dipped.</p><p class="news-callout-move">Next day: stock +9.32% vs sector (SOXX) -0.56%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/05/22/nvidia-announces-10-for-1-stock-split.html" target="_blank" rel="noopener">Read the source</a></aside><p>The stock rose 9.32% the next day while the sector fell 0.56%. A caution is needed, though. The split came together with record quarterly earnings and a 150% dividend increase, so much of the jump reflects that good news as well. Treat a split as a sentiment helper that rides along with fundamentals, never as a source of value by itself.</p><h4>The downside: opportunity cost and lack of innovation</h4><p>Every allocation choice has a price. If a company in a fast-moving sector spends nearly all its cash on buybacks instead of research and development, investors might wonder whether it has run out of new ideas or is failing to invest in its future.</p><p>A related risk appears when a struggling company uses cash on distractions. A small acquisition outside the core business can worry investors if the company is already burning heavily on its main turnaround, because every dollar spent elsewhere is a dollar not spent fixing the core.</p><p>To read any capital allocation announcement, ask three questions. Is the cash coming from real, repeatable earnings? Does the company still invest enough in its own future? And does the move change the value of the business, or only the way it is sliced?</p><h4>Recent Headlines in Practice</h4><p>The new headlines show that capital allocation covers more than repurchases. Nvidia''s $50 billion buyback authorization and Samsung''s roughly $7.2 billion plan, its first buyback since November 2017, are the classic way of returning cash, yet both stocks fell the next day, Nvidia by 6.39% and Samsung by 0.71%. Other companies put cash into strategic stakes instead: Nvidia took a $1 billion stake in Nokia and ASML put 1.3 billion euros into Mistral. Their reactions differed, with Nvidia rising 2.99% while ASML slipped 1.49% against a rising sector. A cash decision is read through the surrounding expectations, the earlier price run-up and what the money buys, so similar announcements can lead to opposite next-day moves.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Samsung Electronics &middot; 18 Nov 2024</p><p class="news-callout-headline">Samsung shares climb more than 7% after surprise $7 billion buyback plan</p><p>Samsung shares rose more than 7% in Seoul on the announcement day, so part of the reaction may already have been reflected before the next session. Investors were also concerned about its memory chip business at the time.</p><p class="news-callout-move">Next day: stock -0.70% vs sector (SOXX) +0.19%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/11/18/samsung-shares-climb-more-than-7percent-after-unveiling-surprise-7-billion-buyback.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Buybacks and splits are choices about what to do with success. A buyback signals confidence and lifts EPS, and a split makes shares easier to buy without changing company value. Both are strongest when backed by solid cash flow, and a buyback is weakest when it replaces investment in the future.</p></div>',
 2),

(19, 'corporate', 'Leadership Transitions and Board Decisions',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/corporate-3.svg" alt="An outgoing executive hands a baton to a successor while a jagged stock line settles into a calm green line." loading="lazy" width="640" height="260"><figcaption>A planned handoff keeps the stock calm</figcaption></figure><p class="lesson-lead">A chip company is only as good as the people steering it. When the person at the top changes, investors immediately ask what it means for the strategy they were paying for.</p><h4>Why leadership news moves stocks</h4><p>A chip company is an enormous machine, and a small group of people steer it. The C-suite, meaning the chief executive officer (CEO), the Chairman, the chief operating officer (COO) and their peers, together with the <strong>Board of Directors</strong>, set the long-term strategy, shape the culture and decide how to allocate capital. When people say management is the "brain" of the company, they mean that most major decisions in this course, from restructurings to buybacks to new factories, ultimately trace back to them.</p><p>Investors price a stock based on how confident they are that management can carry out its vision. That is why the market dislikes uncertainty: any change at the very top introduces something unknown. A new leader may keep the strategy, change it, or take years to find their footing, and no analyst can know in advance which one will happen.</p><p>There is a second factor, the "why". Wall Street reacts very differently to a long-planned, well-telegraphed retirement than to a sudden, unexpected firing or resignation. The first suggests a company that is organized and in control. The second suggests that something went wrong, and the market wants to know what. The two ideas can be summarized in a pair of short flows.</p><p class="lesson-formula">Planned handoff &rarr; certainty &rarr; calm stock</p><p class="lesson-formula">Abrupt exit &rarr; uncertainty &rarr; volatile stock</p><h4>How smooth transitions support a stock</h4><p>A planned handoff does one thing very well: it <strong>signals stability</strong>. When a highly successful CEO announces retirement months or years ahead and names a trusted internal successor, investors conclude that the winning strategy will continue without interruption. The new leader grew up inside the company, knows its customers and understands its technology roadmap.</p><p>A boring transition is a good transition, because it means nobody had to price in a surprise.</p><p>A smooth handoff also helps with <strong>maintaining multiples</strong>. Large institutional investors, such as pension funds and asset managers, hold huge positions and care about stability. If a transition is calm, they have no reason to panic-sell, so the stock can keep its premium valuation multiple, the extra price the market pays for a company it trusts. If the transition is messy, those same investors may sell quickly and the premium can disappear.</p><h4>Consolidating power and organizing for expansion</h4><p>Not all leadership news is a simple replacement. Sometimes a company changes the shape of its top team. <strong>Consolidating power</strong>, such as merging the Chairman and CEO roles, can show the market that decision-making is becoming faster and more efficient, which is valuable during periods of rapid global expansion. A company building factories on several continents may want fewer layers between a problem and a decision.</p><p>Consolidation is not always rewarded straight away. If a departing executive led key projects, such as overseas expansion, investors may worry about execution friction and complicated geopolitical negotiations.</p><p>A promotion can land very differently. Elevating trusted insiders into expanded roles can be read as a proactive step to groom the next generation of leaders, which reinforces confidence in execution. The same kind of leadership change can draw different reactions depending on what is lost and what is gained.</p><h4>How abrupt changes signal trouble, and sometimes opportunity</h4><p>When a major division head is fired or resigns suddenly, the market tends to assume the worst. This is the <strong>admitting failure</strong> reflex: removing a senior leader in public is an acknowledgement that the company is losing market share or failing to innovate. It usually triggers immediate volatility and downward pressure on the stock, because investors now have to guess how deep the problem runs.</p><p>The semiconductor case is a chipmaker that has fallen behind its rivals in a hot product area. If it abruptly replaces the head of its chip business, the market is likely to read the dismissal as a public admission of operational failure, even though it can also be a sign that the company is taking the problem seriously. The stock may lag the sector on the day, because investors price the admission before they can judge the fix.</p><p>That brings up the other side, the <strong>turnaround catalyst</strong>. If the market believes the previous leadership was the bottleneck, bringing in a respected "fixer" from outside, or promoting a strict internal veteran, can become a strongly positive catalyst. It signals that the company is finally treating its problems with urgency. The market''s first reaction to the firing may be negative, but the later reaction to a credible new leader can turn around if results begin to improve. That is why a good rule is to separate the event (a leader left) from the plan (who is coming in and what will they change).</p><h4>A quick checklist for reading leadership news</h4><p>When you see a leadership headline, there are three questions that tell you most of what you need. First, was it planned or sudden? Months of notice and a named successor suggest control, while an overnight departure suggests a problem. Second, who steps in? An insider who has already helped build the strategy is lower risk than an outsider with an unproven plan, although a strong outsider can be exactly what a struggling company needs. Third, what did the departing person own? If they led a key project, such as overseas fabs or a lagging memory line, the market will price in the risk of losing that knowledge.</p><p>Remember too that the stock does not move in a vacuum, so it is worth comparing the stock with the sector index before blaming or crediting the people at the top.</p><h4>Recent Headlines in Practice</h4><p>Leadership news in this group shows that the way a change happens matters as much as the change itself. ASML''s succession plan, with Peter Wennink retiring in April 2024 and veteran Christophe Fouquet stepping up, was seen by analysts as orderly, and the stock rose 1.23% the next day against a 0.47% gain for the sector. Intel''s board removing CEO Pat Gelsinger, with only interim co-CEOs named, left open who would lead its turnaround, and the stock fell 6.10% while the sector slipped 0.57%. Samsung''s appointment of Jun Young-hyun as co-CEO and head of memory came as the company struggled in advanced memory, and its shares fell 1.42% while the sector rose. Planned, continuous handovers tend to reassure investors, while abrupt exits invite doubt about direction.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Intel &middot; 2 Dec 2024</p><p class="news-callout-headline">Intel CEO Pat Gelsinger ousted by board after disastrous performance</p><p>CNBC reported a contentious board meeting over Gelsinger''s perceived failure to respond to Nvidia''s competitive lead, and the company named only interim co-CEOs. Investors may have worried about who would lead the turnaround.</p><p class="news-callout-move">Next day: stock -6.10% vs sector (SOXX) -0.56%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/12/02/intel-ceo-pat-gelsinger-is-out.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Leadership news is about confidence. A planned, well-telegraphed handoff protects the valuation, while an abrupt change confirms trouble, even if the replacement turns out to be a strong fixer. Always check why the change happened and who is stepping in.</p></div>',
 3),

(20, 'corporate', 'Massive CapEx and Joint Ventures for Capacity Expansion',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/corporate-4.svg" alt="Coins flow toward a new chip fab rising next to a crane, with two crossed partner flags marking a joint venture." loading="lazy" width="640" height="260"><figcaption>Big CapEx builds the fab, a joint venture shares the risk</figcaption></figure><p class="lesson-lead">Building a modern chip factory can cost more than a small country spends on its roads. When a company commits that kind of money, investors have to decide whether it is a bold bet on demand or a risky cash drain.</p><h4>What CapEx is, and why chip fabs are special</h4><p><strong>Capital Expenditure (CapEx)</strong> is the money a company spends to buy, maintain or improve its physical assets, such as buildings, machines and equipment. For most companies it is a routine line in the budget. In the semiconductor industry it means building huge, multi-billion-dollar manufacturing factories known as "fabs", and the numbers are on a different scale. Advanced chip manufacturing is probably the most capital-intensive industry on earth, and a single cutting-edge fab can cost upwards of $20 billion.</p><p>That price tag works as a <strong>moat</strong>, which is an advantage that protects a business from competition. It is a massive barrier to entry, because very few organizations in the world can afford to write a $20 billion cheque for a factory that will not produce a single chip for years. Existing leaders keep their lead, and new competitors stay out.</p><p>Because the risk is so large, chipmakers often form <strong>joint ventures (JVs)</strong>, in which two or more companies build and own a factory together. A JV shares the financial risk and, when partners are major customers, guarantees buyers for the output. The chain of events behind a big CapEx announcement can be summarized in one flow.</p><p class="lesson-formula">Huge CapEx &rarr; years of building &rarr; new capacity &rarr; revenue later (if demand is still there)</p><p>The words in brackets are important. Nearly everything about a CapEx decision rests on whether demand will still be there when the factory is ready, and the market spends its time debating that single question.</p><h4>The bull case: why big spending can lift a stock</h4><p>First, massive CapEx is a <strong>signal of future demand</strong>. Management does not commit $20 billion unless it has supreme confidence in long-term customer orders, so the size of the spending reveals how strong the company believes its pipeline is.</p><p>Second, governments often help pay. Modern fab expansion is frequently subsidized, for example by the US CHIPS Act or European equivalents. These <strong>subsidies</strong> work like free money that reduces how much the company must pay out of its own pocket, and they also lift investor sentiment.</p><p>Third, a JV with big customers means <strong>locking in customers</strong>. If automakers or technology giants own a part of the factory, they are effectively promising to buy what it makes.</p><p>Government support shows up in real projects. Federal CHIPS Act grants, for instance, can cushion a very large cost and make it more comfortable, and investors may take a subsidized build as a sign of confidence in long-term demand.</p><h4>The bear case: three ways a fab can hurt</h4><p>The first risk is <strong>killing short-term margins</strong>. A fab takes three to five years to build. During that time the company is burning billions in cash without a single dollar of revenue from the new facility, which hurts short-term profit and free cash flow. This is why a company with confident long-term plans can still see its stock lag in the short term.</p><p>The second is <strong>execution risk</strong>. Mega-projects are prone to construction delays, labor shortages and cost overruns, and if a factory is delayed, investors punish the stock. TSMC''s Arizona project in February 2023 is the example. Its board approved a $3.5 billion capital injection for its Arizona subsidiary to cover soaring construction expenses and labor premiums in Phoenix. The stock slid 5.31% the next day while the sector gained 0.40%, because the extra funding confirmed that replicating a fab overseas was far more expensive than doing it in Taiwan, which would dilute gross margins.</p><p>The third is the <strong>oversupply trap</strong>. Suppose a company builds large capacity during a boom, but the factory comes online right as the economy enters a recession. It is left with empty, very expensive buildings, a scenario that crushes stock prices. Chip demand is cyclical, so a plan that looks wise at the peak may look reckless at the bottom.</p><p>A cousin of this problem is financing the spending. In February 2023, during a memory downturn, Samsung borrowed 20 trillion won, about $16 billion, from its display affiliate Samsung Display to fund chip investment. The stock fell 1.58% the next day while the sector gained 0.40%. The unusual internal loan highlighted liquidity strain and cash burn from Samsung''s decision not to cut CapEx during the downturn, and it raised worries about leverage on the balance sheet.</p><h4>The mega-hub: ambition against a long timeline</h4><p>Sometimes a CapEx plan is so large that it becomes a statement of national and corporate strategy, often backed heavily by a government keen to secure national tech supremacy. The catch is the timeline. A commitment that stretches over decades weighs on near-term free cash flow, and a stock can lag even when the sector rallies. Bold ambition can be admired and still cost the stock something in the short run.</p><h4>A worked payback example, and how to read CapEx news</h4><p>It helps to run the numbers in a simplified, illustrative way. Suppose a new fab costs $20 billion and, once it is running, generates $4 billion in extra cash each year after expenses. The <strong>payback period</strong> is the time needed to earn the investment back.</p><p class="lesson-formula">Payback years = CapEx &divide; annual cash generated: $20B &divide; $4B = 5 years</p><p>Five years looks acceptable, but remember that the fab needs three to five years to be built before it produces anything. The company therefore waits roughly eight to ten years from the first dollar spent to getting that dollar back. If demand disappears or prices fall by even a quarter, the payback stretches far longer. Joint ventures and subsidies shorten the story by reducing how much of the $20 billion falls on the company itself, which is why a subsidized or partnered project looks sturdier than a fully self-funded one.</p><p>Partnerships do not have to be about factories alone. Two companies can also fund an advanced research facility together, which shares the R&amp;D risk and can secure early adoption of new equipment by a major customer.</p><p>When you read a CapEx headline, check the demand evidence, who is sharing the bill, how long the build will take and where the economy is in its cycle. A big commitment can be a bold bet or a risky drain, and the answer usually depends on timing.</p><h4>Recent Headlines in Practice</h4><p>The capacity announcements mapped here involve very large sums, yet the reactions varied widely. TSMC''s second Japan fab with Sony and Toyota backing and Micron''s $24 billion Singapore plant both rose, by 4.69% and 6.10%, and each beat the sector''s gain. By contrast, TSMC''s additional $100 billion for Arizona in July 2026, with no timeline given, fell 2.78%, and the ESMC groundbreaking in Dresden was slightly lower while the sector rose 1.42%. Micron''s roughly $200 billion U.S. plan held up better than a sector that fell 2.61%. Partners that share the cost, demand tied to AI, and a clear schedule appear to ease investor worries about spending, while open-ended commitments can raise them.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">TSMC &middot; 6 Feb 2024</p><p class="news-callout-headline">World''s biggest chipmaker TSMC to open second Japan factory with backing from Sony, Toyota</p><p>TSMC announced a second Kumamoto fab through its JASM venture with Sony and Toyota backing, to make 6nm and 7nm class chips with operations by the end of 2027. Partners sharing the cost and demand risk may have eased worries about funding the expansion.</p><p class="news-callout-move">Next day: stock +4.69% vs sector (SOXX) +1.53%</p><a class="news-callout-link" href="https://www.cnbc.com/2024/02/06/tsmc-to-open-second-japan-chip-factory-with-backing-from-sony-toyota.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>CapEx is a bet on the future paid for with today''s cash. Joint ventures and subsidies reduce the risk, and a confident build can signal strong demand. The same spending can hurt margins, run late or arrive just as demand fades, so the market weighs ambition against timing.</p></div>',
 4),

(5, 'supply_chain', 'Semiconductor Industry Structure',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/supply_chain-1.svg" alt="A chip travels along a conveyor through design, fab, packaging and test stages and ends with a green tick." loading="lazy" width="640" height="260"><figcaption>Each stage of the chain earns money differently</figcaption></figure><p class="lesson-lead">A chip in your phone has passed through the hands of half a dozen different companies before you ever touch it. Before you can judge a semiconductor stock, you need to know which link in that chain the company owns.</p><h4>The Core Concept</h4><p>The semiconductor industry is not one business. It is a relay race made up of specialised stages, and each stage is usually run by different companies. Some firms focus on <strong>chip design</strong>, others on manufacturing, memory production, equipment, packaging or testing. The reason is simple: modern chips are so complicated, and the factories that make them so expensive, that almost nobody can do everything well. A company that is brilliant at drawing circuits rarely also owns a multibillion-dollar factory.</p><p>The basic structure of the industry looks like this:</p><p class="lesson-formula">Chip Architecture &rarr; Chip Design &rarr; Manufacturing &rarr; Equipment &amp; Materials &rarr; Packaging &amp; Testing &rarr; Electronic Products.</p><p>Read from left to right, ideas become blueprints, blueprints become silicon wafers, and wafers become the finished parts that sit inside phones, cars and data centres. Equipment and materials sit in the middle because every factory needs specialised machines and chemicals before it can make anything at all.</p><p>Why does this matter for an investor? Knowing where a company operates in this <strong>value chain</strong> tells you who its customers are, who supplies it, who competes with it, how its costs are structured, what drives its growth and which risks it carries. Two chip companies can appear in the same headline and still be affected in opposite ways. A shortage of factory capacity, for example, is a headache for a designer waiting for supply but good news for the factory whose lines are full of orders.</p><h4>Fabless Chip Designers</h4><p><strong>Fabless</strong> companies design semiconductor chips but usually outsource the manufacturing to foundries. A useful analogy is an architect who draws a building and then hires a construction firm to put it up. The architect keeps the creative value and avoids buying cranes and cement mixers. Well-known examples are NVIDIA, which designs GPUs and AI accelerators, AMD, which designs CPUs and GPUs, Broadcom, which focuses on networking and custom AI chips, and Qualcomm, which designs smartphone processors and communication chips.</p><p>Because they do not own factories, their competitive advantage has to come from somewhere else. It usually comes from chip architecture, software ecosystems that developers get used to, intellectual property, product performance and long customer relationships. A customer who has built its software around one company''s tools will think twice before switching, even if a rival chip looks similar on paper.</p><p>Not owning a fab also changes the financial profile. Fabless companies generally have lower <strong>capital expenditure (CapEx)</strong>, which is the money spent on buildings and equipment, than semiconductor manufacturers. Most of their spending goes into research and engineering talent instead. Their results therefore depend more on how well their products sell than on how full a factory happens to be.</p><h4>Foundries</h4><p><strong>Foundries</strong> are the contract manufacturers of the chip world. They make chips that other companies have designed, and the best-known examples are TSMC and Samsung Foundry. Because many fabless designers send their work to the same few foundries, a foundry''s fortunes are tied to the order books of lots of customers at once.</p><p>Several indicators tell you how a foundry is doing. <strong>Wafer demand</strong> shows how many silicon wafers customers want to buy. <strong>Capacity utilisation</strong> measures how much of the factory is actually in use. <strong>Process-node leadership</strong> asks whether the foundry can make the most advanced, finest-featured chips that top customers need. The <strong>yield rate</strong> is the share of chips on a wafer that actually work, and <strong>wafer ASP</strong> is the average selling price per wafer. Finally, capital expenditure matters because staying at the leading edge means constantly buying new tools.</p><p>Utilisation deserves a worked example. A fab has enormous fixed costs: the building, the machines and the staff cost roughly the same whether the lines are busy or idle. If the factory is half empty, those costs are shared across few wafers, so each wafer is expensive to make. If it runs close to full, the same costs are spread across many wafers and each one becomes cheaper. That is why stronger demand, such as extra advanced-node wafer orders for AI accelerators, can lift a foundry''s profitability faster than its sales.</p><h4>Memory Manufacturers</h4><p>Memory companies manufacture products such as <strong>DRAM</strong>, <strong>NAND</strong> and <strong>HBM</strong>. DRAM is the working memory a computer uses while it runs, NAND is the storage that keeps your files when the power is off, and HBM, short for high-bandwidth memory, is a special stacked memory placed right next to AI chips. Major producers include Micron, SK Hynix and Samsung.</p><p>Unlike many specialised logic chips, memory is relatively standardised. A buyer can often swap one maker''s DRAM for another''s, so producers compete hard on price and the market behaves a little like a commodity such as oil or wheat. That means industry supply and demand have an unusually large effect on prices and profitability. When memory supply is limited relative to demand, the chain reaction runs like this:</p><p class="lesson-formula">Memory Prices &uarr; &rarr; Revenue &uarr; &rarr; Gross Margin &uarr; &rarr; Profit &uarr;</p><p>The logic is straightforward. Higher prices bring in more revenue for the same number of chips, while the cost of making each chip barely changes, so the gap between price and cost widens and profit grows quickly. The opposite can occur during periods of oversupply, when prices fall faster than costs can be cut.</p><h4>Semiconductor Equipment</h4><p>Semiconductor factories cannot be built from ordinary machinery. They need highly specialised <strong>manufacturing equipment</strong>, and a small group of companies supplies it. The main categories are lithography, which prints microscopic patterns onto wafers, etching, which carves material away, and deposition, which lays down thin layers of material. Metrology, inspection and process control then measure and check the results so that defects are caught early.</p><p>Major names include ASML in lithography, Applied Materials in deposition and other manufacturing equipment, Lam Research in etching and deposition, and KLA in process control and inspection. You can think of these businesses as the pick-and-shovel sellers of the chip gold rush. They do well when many people are digging, whoever ends up finding the gold.</p><p>Their fortunes are strongly influenced by semiconductor manufacturers'' CapEx. When chipmakers build, toolmakers get orders, and when chipmakers pause their expansion plans, those orders slow down.</p><h4>Packaging and Testing</h4><p>After a wafer is fabricated, it is cut into individual <strong>dies</strong>, the small slices of silicon that each become one chip. Those dies must then be packaged, meaning mounted in a protective case with connections to the outside world, and tested before they can be used in electronic products. For many years this was a routine step that attracted little attention.</p><p>Advanced AI chips changed that. GPUs, CPUs, HBM and other components must communicate at extremely high speeds, so they are assembled very close together using sophisticated <strong>advanced packaging</strong>. Only a limited number of facilities can do this work. As a result, advanced packaging capacity can become an important supply-chain constraint even when wafer supply is perfectly fine, like a restaurant with plenty of ingredients but only one oven.</p><p>A single step in the chain can limit a whole product line. A packaging bottleneck limits how many chips can be shipped, but it is also evidence of very strong demand, so investors may not treat it as simple bad news.</p><h4>Recent Headlines in Practice</h4><p>Several recent headlines show that the narrowest stage of the chip relay race sets the pace for everyone else. In September 2023, TSMC''s chairman said the constraint on AI chips was CoWoS packaging capacity rather than the chips themselves, with relief expected in roughly eighteen months. In April 2026, CNBC reported that Nvidia had reserved the majority of TSMC''s most advanced packaging capacity and that almost all advanced packaging still happens in Asia. At the equipment end, ASML shipped its second High-NA EUV machine, reported to cost roughly 300 to 400 million dollars, to an unnamed customer in April 2024. Reading headlines this way shows why a design firm like Nvidia, a foundry like TSMC and a toolmaker like ASML can all be affected by the same chain, even though each earns money differently.</p><aside class="news-callout news-callout--flat"><p class="news-callout-meta">TSMC &middot; 8 Sep 2023</p><p class="news-callout-headline">TSMC warns AI chip crunch will last another 18 months</p><p>TSMC''s chairman said the silicon was ready but advanced packaging was the limit, and that the company could support about 80 percent of customer needs. The shares barely moved, in line with the sector, which may mean investors already knew packaging capacity was tight.</p><p class="news-callout-move">Next day: stock -0.04% vs sector (SOXX) -0.06%</p><a class="news-callout-link" href="https://www.theregister.com/software/2023/09/08/tsmc-warns-ai-chip-crunch-will-last-another-18-months/401174" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>A semiconductor company should first be understood according to <strong>where it sits in the semiconductor value chain.</strong> Fabless designers, foundries, memory makers, equipment makers and packagers each earn money in a different way, so the same headline can mean very different things for each of them. Before judging any chip headline, ask which link in the chain the company owns.</p></div>',
 1),

(21, 'supply_chain', 'Supply Chains and Semiconductor Stocks',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/supply_chain-2.svg" alt="A chain of four linked boxes where the packaging box flashes red and the slowdown turns the memory and stock boxes red in turn." loading="lazy" width="640" height="260"><figcaption>One blocked link ripples down the chain</figcaption></figure><p class="lesson-lead">One earthquake in Taiwan can shave a few percent off a chip stock on the other side of the world. Semiconductor companies are tightly linked, so a shock in one place travels along the chain.</p><h4>The Core Concept</h4><p>Semiconductor companies are tightly interconnected. A designer buys manufacturing from a foundry, the foundry buys machines from equipment makers, the finished chip needs memory and packaging, and the final product is sold to someone who may or may not still want it. Because of these links, a change in one part of the industry can affect revenue, costs, production and investment in every other part.</p><p>A simplified transmission mechanism, the path along which a shock travels, is:</p><p class="lesson-formula">End-Market Demand &rarr; Chip Orders &rarr; Wafer Production &rarr; Memory &amp; Packaging Demand &rarr; Equipment Investment.</p><p>The AI boom is a worked example. Each arrow is a company reacting to the one before it. Cloud companies decide they need more AI computing power and raise their spending, which creates orders for AI accelerators, which need foundry capacity, HBM memory and advanced packaging, and eventually those suppliers order more machines:</p><p class="lesson-formula">AI Demand &uarr; &rarr; Cloud companies increase AI CapEx &rarr; AI accelerator orders &uarr; &rarr; Foundry demand &uarr; &rarr; HBM demand &uarr; &rarr; Advanced packaging demand &uarr; &rarr; Semiconductor equipment investment may eventually &uarr;</p><p>The word eventually matters. Equipment orders sit at the end of the chain, so they tend to react later than the earlier steps. For an investor, one headline about a cloud company''s spending is really a clue about many other companies further down the line.</p><h4>Supply-Chain Weakness: When Demand Fades</h4><p>Weak demand or excess supply can create several problems at once. The first is <strong>excess inventory</strong>. Customers who bought plenty of chips earlier may simply stop ordering while they use up what they already hold. For the chipmaker, that shows up as revenue falling even though the customer''s own business may be fine:</p><p class="lesson-formula">Inventory &uarr; &rarr; New Orders &darr; &rarr; Semiconductor Revenue &darr;.</p><p>Next come <strong>falling chip prices</strong>. When there is more supply than buyers need, sellers cut prices to win orders. This is especially visible in commodity-like markets such as DRAM and NAND, where one maker''s product is easy to swap for another''s.</p><p>Falling volumes also cause <strong>lower capacity utilisation</strong>. A factory operating below full capacity still pays for its building, machines and staff, so those fixed manufacturing costs are spread across fewer units. The cost per chip rises and gross margins shrink. Imagine a bus that costs the same to run whether it carries ten passengers or forty: with ten passengers, every ticket has to cover far more of the bill.</p><p>Finally, <strong>order cancellations</strong> can hit when customers in smartphones, PCs, automotive, cloud computing or other markets reduce their expected purchases. A cancelled order is worse than a delayed one, because it removes revenue that analysts may have been counting on.</p><h4>Supply-Chain Weakness: Disruptions and Restrictions</h4><p>Not every problem comes from weak demand. <strong>Production disruptions</strong> happen when shortages of materials, manufacturing equipment or packaging capacity, or a physical shock such as an earthquake, prevent companies from meeting the demand that is there. In this case customers want the chips, but the chain cannot deliver them. Because so much advanced manufacturing is concentrated in a few places, one local event can have global consequences.</p><p><strong>Geopolitical restrictions</strong> are the second kind of non-demand problem. Export controls and trade restrictions can affect a company''s access to customers, to manufacturing technology and to semiconductor equipment. Governments, not markets, set these rules, and they can change quickly. For a supplier, a rule that blocks sales or servicing in a large market removes revenue regardless of how good its products are.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">ASML &middot; 14 May 2026</p><p class="news-callout-headline">Dutch government objects to proposed US law restricting ASML''s China exports</p><p>A proposed US law could limit not only new ASML tool shipments to China but also servicing of tools already installed there. That threatens high-margin recurring service revenue, a good example of a geopolitical restriction hitting a supplier in the chain.</p><p class="news-callout-move">Next day: stock -5.22% vs sector (SOXX) -4.06%</p><a class="news-callout-link" href="https://www.reuters.com/world/asia-pacific/dutch-government-objects-proposed-us-law-restricting-asmls-china-exports-2026-05-14/" target="_blank" rel="noopener">Read the source</a></aside><p>This is a good example of a supplier being hit by a rule rather than by weak customers. The stock fell more than the sector because the exposure was specific to ASML.</p><h4>Supply-Chain Strength</h4><p>Improving conditions create the opposite effect. The starting point is <strong>rising end-market demand</strong>: growth in AI servers, smartphones, vehicles, data centres or other electronics increases the amount of semiconductor content people buy. This flows into <strong>higher capacity utilisation</strong>, because more wafer production lets manufacturers spread their fixed costs across more units. Each chip becomes cheaper to make, and margins widen.</p><p>As demand outruns supply, buyers often see <strong>longer lead times</strong>, which is the gap between placing an order and receiving the product. Increasing delivery times can sometimes indicate that demand is exceeding available supply. When supply stays tight, <strong>improving chip prices</strong> follow, because sellers gain pricing power and buyers compete to secure parts.</p><p>Strong conditions then trigger <strong>capacity expansion</strong>. Chip manufacturers respond by investing in new fabs, equipment and advanced packaging. Sometimes the response is faster and more creative, such as finding capacity somewhere else. Removing a single bottleneck can be treated as a revenue unlock, because the same demand can then be served sooner.</p><h4>Important Supply-Chain Indicators</h4><p>To read all this in real time, investors watch a handful of numbers. <strong>Inventory</strong> tells you whether customers or manufacturers are sitting on excess chips. <strong>Lead time</strong> signals how tight or loose the balance between supply and demand is. <strong>ASP</strong>, the average selling price, is a direct read on pricing power: if it rises while volumes hold, suppliers have the upper hand.</p><p><strong>Capacity utilisation</strong> reflects how much demand there is for manufacturing. <strong>Customer orders</strong> show future production demand, since orders placed today become shipments next quarter. <strong>CapEx</strong> hints at expected future capacity, because companies only build when they expect a need. And <strong>backlog</strong>, the value of orders received but not yet delivered, gives visibility into future revenue.</p><p>No single indicator tells the whole story. Rising inventory with falling orders is a warning, while falling lead times and rising ASP together suggest conditions are tightening. The skill is to combine them, then ask which company in the chain gains and which one is hurt.</p><h4>Recent Headlines in Practice</h4><p>Recent headlines show how a problem at one link can reach a chip designer. In August 2024, reports said Nvidia''s Blackwell GPUs would slip to the first quarter of 2025, linked to the complexity of TSMC''s CoWoS packaging, and Nvidia''s shares rose the next day. In January 2025, TSMC paused work at plants after a magnitude 6.4 earthquake, with operations gradually resuming after inspections. Samsung''s memory shows the other side of the chain: in May 2024, Reuters reported its HBM3E chips had failed an Nvidia test because of heat and power consumption problems, and in August 2024 the 8-layer version was reported to have cleared the tests. Together these show that one bottleneck can delay many customers at once.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Nvidia &middot; 5 Aug 2024</p><p class="news-callout-headline">Nvidia reportedly delays Blackwell GPUs until 2025 over packaging issues</p><p>The delay was blamed on packaging complexity at TSMC rather than on weak demand, and the backdrop was large orders for AI services. The stock rose about four times as much as the sector, which suggests investors judged the delay unlikely to hurt Nvidia over the long term.</p><p class="news-callout-move">Next day: stock +3.78% vs sector (SOXX) +0.91%</p><a class="news-callout-link" href="https://www.theregister.com/2024/08/05/nvidia_delays_blackwell_gpus_until/" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p><strong>Supply-chain indicators can provide early signals about future semiconductor revenue, margins, and earnings.</strong> Learn to read inventory, lead times, prices, utilisation, orders, CapEx and backlog together, and a headline about one company often tells you about several others.</p></div>',
 2),

(22, 'supply_chain', 'Semiconductor Cycles: Supply, Demand & Inventory',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/supply_chain-3.svg" alt="A chip rides a wave from a boom peak down to a glut trough and back up again." loading="lazy" width="640" height="260"><figcaption>Chip cycles swing between boom and glut</figcaption></figure><p class="lesson-lead">Why do chip stocks swing from boom to bust and back again? Because building a fab takes years, but customers can change their minds in months.</p><h4>The Core Concept</h4><p>The semiconductor industry is <strong>cyclical</strong>, which means it moves through repeating periods of boom and bust. The root cause is a timing mismatch. Building new capacity, such as a fab, can take years, while customer demand can change within months. Factories are planned for the world of today but switch on in the world of tomorrow.</p><p>A good analogy is a farmer deciding what to plant. When crop prices are high, every farmer plants more. By harvest time everyone''s extra crop arrives together and prices crash. Chipmakers face the same problem with much larger sums of money. The pattern can be summarised as:</p><p class="lesson-formula">Short-Term Demand Changes + Slow Supply Adjustment = Semiconductor Cycles.</p><p>A simplified semiconductor cycle moves through these phases and then starts again:</p><p class="lesson-formula">Recovery &rarr; Expansion &rarr; Shortage &rarr; Overinvestment &rarr; Oversupply &rarr; Downturn &rarr; Inventory Correction &rarr; Recovery</p><p>Real cycles are never this tidy, and each one differs in length and size. But knowing the typical order helps you recognise where the industry probably is and which signals to expect next.</p><h4>Stage 1 and Stage 2: Recovery and Expansion</h4><p>In <strong>Stage 1: Recovery</strong>, the worst is over. Customer inventories begin falling as buyers finally use up their excess chips, and orders start to recover. Typical signals are inventory falling, orders rising, ASP stabilising, capacity utilisation rising and revenue growth beginning to improve. At this point headlines are often still gloomy, which is why recoveries are easy to miss.</p><p>In <strong>Stage 2: Expansion</strong>, demand strengthens and manufacturers increase production. The signals now point clearly upward: revenue, ASP, gross margin, capacity utilisation and CapEx are all rising. Companies feel confident, order books fill up and management teams begin talking about adding capacity.</p><h4>Stage 3 and Stage 4: Shortage and Overinvestment</h4><p>In <strong>Stage 3: Shortage</strong>, demand exceeds available supply. Lead times may increase, and suppliers can gain pricing power because buyers compete for scarce parts. The chain of effects is:</p><p class="lesson-formula">Demand &gt; Supply &rarr; ASP &uarr; &rarr; Margin &uarr; &rarr; Profit &uarr;</p><p>Because factory costs are largely fixed, extra price falls almost entirely into profit. This stage can produce particularly strong earnings growth, and it is often the period in which a company''s results look their best. Investors also ask how long a shortage might last, because a longer shortage means longer-lasting pricing power.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">Micron &middot; 27 Aug 2026</p><p class="news-callout-headline">AI memory shortage drives long-term capacity expansion across HBM supply chain</p><p>Industry reports pointed to HBM memory shortages lasting through 2030 and multi-year capacity build-outs. Investors priced in long-lasting pricing power for memory makers, so the stock rose even as the sector fell.</p><p class="news-callout-move">Next day: stock +2.40% vs sector (SOXX) -3.20%</p><a class="news-callout-link" href="https://www.reuters.com/world/asia-pacific/sk-hynix-holds-groundbreaking-ceremony-4-billion-indiana-ai-chip-packaging-2026-08-27/" target="_blank" rel="noopener">Read the source</a></aside><p>The stock rose even as the sector fell, because investors were pricing in long-lasting pricing power for memory makers.</p><p><strong>Stage 4: Overinvestment</strong> is where the seeds of the next downturn are planted. Strong profitability encourages semiconductor manufacturers to expand capacity. However, fabs are expensive and take significant time to construct. This creates an important risk: <strong>companies invest based on current strong demand, but the new capacity may arrive after demand has already slowed.</strong> Every company makes a sensible decision on its own, but when all of them build at once, the industry as a whole builds too much.</p><h4>Stage 5: Oversupply and Downturn</h4><p>Eventually, supply catches up and then overtakes demand. In <strong>Stage 5: Oversupply</strong> the balance flips to Supply &gt; Demand, and the effects are the reverse of the shortage. Inventory rises, ASP falls, capacity utilisation drops, gross margin shrinks and earnings decline. The effect is particularly important in DRAM and NAND markets, which behave like commodities, because with little to distinguish one maker''s product from another''s, sellers cut prices to keep their factories busy.</p><p>The downturn is often made worse by the fixed-cost problem described earlier. A half-empty fab still costs nearly as much to run, so margins fall faster than revenue. Companies respond by postponing or cancelling expansion projects, and the news during this phase tends to be about cuts and delays.</p><h4>The Inventory Cycle</h4><p>Inside the bigger cycle sits a shorter and more mechanical one: the <strong>inventory cycle</strong>. It explains why chip orders can collapse even when consumers are still buying electronics, and why they bounce back strongly afterwards. A common sequence looks like this:</p><p class="lesson-formula">End Demand Weakens &rarr; Customers reduce purchases &rarr; Inventory accumulates &rarr; Chip orders fall faster than end demand &rarr; Manufacturers reduce production &rarr; Inventory gradually normalises &rarr; Customers begin ordering again &rarr; Semiconductor production recovers</p><p>The key step is the third one. When sales weaken, customers find they hold more chips than they need. They stop ordering altogether until the pile shrinks, so chipmakers see a drop in orders that is much larger than the drop in actual demand.</p><p>This helps explain the semiconductor industry''s <strong>bullwhip effect</strong>: a relatively small decline in final electronics demand can produce a much larger decline in semiconductor orders when customers simultaneously reduce inventory. A flick of the wrist at the handle becomes a large crack at the tip of the whip. The same effect works on the way up, when customers rebuild stock at the same time as demand improves.</p><p>How does the cycle end? Eventually producers cut output to bring supply back toward demand. Such moves are how an oversupplied market starts to clear inventory.</p><p>Investors can read a supply cut as the beginning of the end of the glut. This is a good reminder that markets look ahead, which is a point we return to in the final lesson.</p><h4>Putting the Three Factors Together</h4><p>Looking back over the stages, three things drive the story: demand, inventory and supply growth. Strong demand with low inventory and slow supply growth leads to shortages and rising prices. Weak demand with high inventory and fast supply growth leads to gluts and falling prices. The messy middle cases are where careful analysis pays off.</p><p>For example, demand can look healthy while inventory quietly piles up in customers'' warehouses, which warns that today''s orders may overstate tomorrow''s. Or demand can be weak while supply growth has already been cut sharply, which hints that a recovery could be closer than the headlines suggest. Checking all three together helps you avoid reading too much into any single data point.</p><h4>Recent Headlines in Practice</h4><p>Several headlines show the cycle from the supply side. In April and July 2023, Samsung said it would cut chip production and then extended the cuts, aiming to normalize inventory after a chip glut and a memory-unit loss of about 4.36 trillion won in the second quarter. By March 2024 the picture had changed, with Micron reporting that HBM was sold out for calendar 2024 and that most of 2025 was already allocated. In January 2026, CNBC described AI memory as sold out and prices surging, as makers shifted output toward HBM. A different supply squeeze appeared at Intel in January 2026, when its CFO admitted misjudging datacenter demand and capacity was moved toward Xeon server parts. Producers cut supply in a glut and later struggle to meet demand.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Samsung Electronics &middot; 27 Jul 2023</p><p class="news-callout-headline">Samsung extends cut in memory chip production, will focus on high-end AI chips instead</p><p>Samsung extended its memory production cuts to normalize inventory and said it would focus on HBM. The move is for Samsung''s Korea-listed shares, which fell while the sector rose, so the market may have focused on how long the downturn had lasted.</p><p class="news-callout-move">Next day: stock -1.53% vs sector (SOXX) +2.18%</p><a class="news-callout-link" href="https://techcrunch.com/2023/07/27/samsung-extends-cut-in-memory-chip-production-will-focus-on-high-end-ai-chips-instead/" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Semiconductor investors should analyse three factors together: <strong>Demand + Inventory + Supply Growth.</strong> A glut or a shortage only makes sense when you can see all three, and because new capacity arrives slowly, cycles are a normal feature of the industry rather than a surprise.</p></div>',
 3),

(23, 'supply_chain', 'Financial Metrics & Semiconductor Company Analysis',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/supply_chain-4.svg" alt="A dashboard with a utilisation gauge, a margin bar and a revenue line that all rise together." loading="lazy" width="640" height="260"><figcaption>Busy fabs lift margins and revenue together</figcaption></figure><p class="lesson-lead">Industry stories eventually land in a chip company''s financial statements. Knowing which numbers to check, and which matter for which type of company, turns headlines into analysis.</p><h4>The Core Concept</h4><p>Changes in industry conditions eventually appear in semiconductor companies'' financial statements. A shortage shows up as higher prices, a glut as piling inventory, and a new fab as heavy spending. If you know which line of the statements reflects which part of the story, a headline about the industry becomes a prediction about a company''s numbers.</p><p>The starting point is a basic relationship:</p><p class="lesson-formula"><strong>Units Sold &times; Average Selling Price = Revenue</strong></p><p class="lesson-formula"><strong>Revenue &minus; Costs = Profit.</strong></p><p>Revenue depends on how many chips are sold and at what price, and profit is what remains after the costs of making and running the business. However, different semiconductor business models require different financial indicators. A fabless designer, a memory maker and a toolmaker earn and spend money in very different ways, so the same metric can mean very different things for each. The sections below walk through the numbers that matter most, roughly in the order a chip company''s story flows through its accounts.</p><h4>Revenue Growth</h4><p><strong>Revenue growth</strong> indicates whether a company''s business is expanding or contracting. Investors should distinguish between volume growth and price growth, because they say different things. Growth from selling more units suggests real demand, while growth from price increases may reflect a temporary shortage that could fade.</p><p>Memory makers make this split especially clear. For them:</p><p class="lesson-formula">Revenue &asymp; Bit Shipments &times; ASP</p><p>Revenue can therefore increase because the company sells more memory, memory prices increase, or both. If revenue jumps 30% but shipments barely moved, almost all of the growth is price. A rise like that can reverse quickly if the supply and demand balance changes, whereas growth driven by shipments is usually more durable. Reading revenue growth well means always asking how much came from volume and how much from price.</p><h4>Gross Margin and Operating Leverage</h4><p><strong>Gross margin</strong> is one of the most important profitability metrics because it shows how much of each dollar of sales is left after the direct cost of making the product:</p><p class="lesson-formula"><strong>Gross Margin = (Revenue &minus; Cost of Goods Sold) / Revenue.</strong></p><p>Higher utilisation and stronger pricing can significantly improve gross margins. When a factory runs fuller, the cost of making each chip drops, and when prices rise, each chip brings in more. Put the two together and the effect compounds:</p><p class="lesson-formula">ASP &uarr; + Utilisation &uarr; &rarr; Revenue &uarr; &rarr; Cost per chip &darr; &rarr; Gross margin &uarr; &rarr; Operating profit &uarr;</p><p>This creates <strong>operating leverage</strong>, where profits can increase faster than revenue because fab costs are largely fixed. A simple illustration: if a factory costs the same whether it makes 100 wafers or 120, then making the extra 20 adds revenue but almost no cost, so most of that extra revenue becomes profit. The effect works in reverse too, which is why profits in this industry swing more wildly than sales.</p><aside class="news-callout news-callout--up"><p class="news-callout-meta">TSMC &middot; 4 Jun 2026</p><p class="news-callout-headline">TSMC working hard to meet chip demand, would like to hike prices</p><p>TSMC''s chairman said AI capacity was under strain and that it would like to raise prices for advanced manufacturing and packaging. When demand exceeds supply, higher wafer prices fall straight through to margin, so the stock rose while the sector sold off.</p><p class="news-callout-move">Next day: stock +2.40% vs sector (SOXX) -10.44%</p><a class="news-callout-link" href="https://www.investing.com/news/stock-market-news/tsmc-boss-upbeat-on-outlook-as-ai-boom-shows-no-sign-of-easing-4725571" target="_blank" rel="noopener">Read the source</a></aside><p>That is leverage in action. The stock rose even though the whole sector sold off on the day, because the market focused on what extra pricing power does to margins.</p><h4>Capital Expenditure</h4><p>Semiconductor manufacturing requires significant investment, which is why <strong>capital expenditure (CapEx)</strong> is such a closely watched number. It can include spending on new fabs, manufacturing equipment, advanced process nodes, advanced packaging capacity and factory expansion. For these companies, CapEx is not a side cost. It is often the largest single use of cash.</p><p>Increasing CapEx can indicate expectations of strong future demand, because managers rarely commit billions unless orders are in sight. However, excessive industry-wide CapEx can eventually create excess capacity and oversupply, the overinvestment problem from the cycle lesson. So context matters: is the spending tied to specific, high-margin orders, or is everyone simply racing to build?</p><h4>Inventory and Free Cash Flow</h4><p><strong>Inventory</strong> is particularly important when analysing cyclical semiconductor companies. A useful metric is <strong>Days Inventory Outstanding (DIO)</strong>, which estimates how many days of sales a company is holding in stock. A rising DIO means products are taking longer to sell. Rising inventory combined with slowing revenue may indicate weakening demand, while falling inventory during an industry recovery may indicate that excess supply is being absorbed.</p><p>Profits do not always translate into cash. Semiconductor manufacturers can report strong accounting profits while simultaneously spending heavily on new factories and equipment. Therefore it helps to look at <strong>free cash flow</strong>, the cash left after paying for the factories:</p><p class="lesson-formula"><strong>Free Cash Flow = Operating Cash Flow &minus; Capital Expenditure.</strong></p><p>Free cash flow is particularly important when analysing capital-intensive semiconductor businesses. A company with strong profits but negative free cash flow may need to borrow or raise money to keep building, while one with healthy free cash flow has room to invest, pay down debt or return cash to shareholders.</p><h4>Different Companies Require Different Metrics</h4><p>No single number works for every chip company. For a <strong>fabless</strong> designer, the key signals are revenue growth, gross margin and market share, since it has no factory to worry about. For a <strong>foundry</strong>, the focus shifts to utilisation, wafer ASP, yield and CapEx, because filling an expensive fab at good prices is the whole business.</p><p>For a <strong>memory</strong> maker, the key signals are DRAM, NAND or HBM ASP, bit growth and inventory, since the product is standardised and prices swing with the cycle. For <strong>equipment</strong> makers, investors look at orders, backlog and WFE (wafer fab equipment) spending, which reveal how much chipmakers plan to build. For <strong>packaging</strong> specialists, the questions are utilisation and advanced packaging capacity.</p><p>Each of these metrics is simply a different window onto the same industry conditions covered in earlier lessons. Matching the metric to the model avoids a common beginner mistake, such as judging a toolmaker by chip prices or a memory maker by market share. Ask what drives this particular business, then check those numbers first.</p><h4>Recent Headlines in Practice</h4><p>These headlines show how financial metrics connect to news about factories and demand. Intel''s decision in February 2024 to delay its Ohio site to late 2026 was tied to weak market conditions and late CHIPS Act subsidy money, and a year later it said the first Ohio fab would start production between 2030 and 2031. Both are examples of capital expenditure being matched to demand, which is a key metric for a chipmaker that spends heavily on fabs. TSMC''s warning in February 2025 that a January earthquake would cost it roughly 165 million dollars of revenue shows a smaller number set against a very large production base. Samsung''s July 2025 projection that second-quarter operating profit would drop about 56 percent shows how a lag in AI memory can feed straight into profit. For each company, the question is which metric the news actually changes: capital spending, revenue or operating profit.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Intel &middot; 28 Feb 2025</p><p class="news-callout-headline">Intel slows its roll on $28B Ohio fab expansion, pushing production to 2030s</p><p>Intel said it slowed construction to match capital spending with market demand, pushing the first Ohio production to between 2030 and 2031. The stock fell slightly more than the sector on a weak chip day, so the penalty for the later foundry timeline looks modest.</p><p class="news-callout-move">Next day: stock -4.17% vs sector (SOXX) -3.53%</p><a class="news-callout-link" href="https://www.theregister.com/2025/02/28/intel_delay_ohio/" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Financial statements should be analysed together with industry conditions: <strong>Industry Conditions &rarr; Operational Metrics &rarr; Financial Performance.</strong> Choose the metrics that fit the type of company in front of you, and use the industry story to explain why the numbers are moving.</p></div>',
 4),

(24, 'supply_chain', 'Valuation, Expectations & Semiconductor Stock Prices',
 '<figure class="lesson-figure"><img src="../assets/img/lessons/supply_chain-5.svg" alt="A balance scale where a heavy expectations weight outweighs a pile of earnings coins while a red price tag swings with a down arrow." loading="lazy" width="640" height="260"><figcaption>Beating results can still miss expectations</figcaption></figure><p class="lesson-lead">A company can report excellent results and its stock can still fall. That surprises most beginners, and it is the single most useful idea in this lesson.</p><h4>The Core Concept</h4><p>Stock prices do not simply react to whether a company is performing well or poorly. They also react to whether actual and expected performance is better or worse than what the market has already priced in. That sounds abstract, but it explains many puzzling days when great news pushes a stock down or awful news pushes it up.</p><p>A simplified framework is:</p><p class="lesson-formula"><strong>Stock Price &asymp; Earnings &times; Valuation Multiple</strong></p><p>For example, Price &asymp; EPS &times; P/E. EPS is earnings per share, and the P/E is the multiple investors are willing to pay for each dollar of earnings. Semiconductor stocks are therefore affected by two major forces: <strong>Earnings Changes + Valuation Changes.</strong> A stock can rise because earnings grow, because investors are willing to pay a higher multiple, or both. It can also fall for either reason.</p><h4>Earnings Expectations</h4><p>Analysts publish forecasts, and the market treats the average forecast as the baseline. Suppose analysts expect EPS = $10, but the company reports EPS = $11. The company has produced an <strong>earnings beat</strong>, and the stock often rises because reality came out better than the baseline. A miss works the other way.</p><p>However, historical results alone are usually insufficient. Investors also focus heavily on <strong>forward guidance</strong>, which is management''s own outlook for future quarters. A great quarter paired with cautious guidance can disappoint, and a mediocre quarter paired with confident guidance can delight. The market is effectively asking what the future looks like and not only what just happened:</p><p class="lesson-formula">Reported Results + Forward Guidance &rarr; Future Earnings Expectations</p><h4>Good Results Can Still Cause Stocks to Fall</h4><p>Here is the idea that surprises most beginners. Suppose a semiconductor company reports Revenue Growth = +50%, which is strong growth in absolute terms. However, suppose market expectations were Expected Revenue Growth = +60%. Compared with what the market hoped for, the company fell short, so:</p><p class="lesson-formula"><strong>Strong Absolute Performance &ne; Better-than-Expected Performance.</strong></p><p>The stock can decline because actual results were weaker than expectations already embedded in the share price. Think of an exam: a student who gets 85% is happy, unless everyone expected 95%. Share prices are set by people who have already imagined the good news, so the price may already include it. Traders sometimes say a stock has priced in a result, meaning that the good news is already reflected in today''s price and only a surprise can move it further.</p><p>The reverse also happens. When a company has warned about a weak period in advance, the news that arrives may be bad on paper and still cause a rise, because it matched the warning.</p><p>Excellent news can fall flat too, when the market had largely expected it: the stock may drift or even slip because the good news was already built into the price.</p><p>Both cases show the same rule. What matters is the gap between the news and the expectation, not whether the news sounds good or bad in isolation.</p><h4>Valuation Multiples</h4><p>Two companies with identical current earnings can trade at very different valuations. Investors may assign higher <strong>valuation multiples</strong> to companies with higher expected growth, stronger competitive advantages, higher margins, higher returns on capital, more predictable revenue and stronger long-term growth opportunities. In simple terms, you pay more for each dollar of earnings when you believe those dollars will grow and are safe.</p><p>Common semiconductor valuation metrics include the <strong>P/E Ratio</strong>, which compares the share price with what the company earns per share:</p><p class="lesson-formula">P/E = Share Price / EPS</p><p>The <strong>Forward P/E</strong> uses expected earnings for the coming year instead of past earnings, which fits a forward-looking market better:</p><p class="lesson-formula">Forward P/E = Share Price / Expected Future EPS</p><p>Cyclical industries can distort both, because earnings at the top of a cycle are unusually high and at the bottom unusually low. A third measure is <strong>EV/EBITDA</strong>, which compares a company''s enterprise value, roughly the price of the whole business including its debt, with its operating earnings before interest, taxes, depreciation and amortisation. It is handy for factory-heavy businesses because it ignores the large depreciation charges that fabs produce. No single multiple is perfect, so analysts usually compare a company against its own history and against similar companies rather than reading one number alone.</p><h4>Interest Rates and Valuation</h4><p>Growth companies often derive a significant portion of their valuation from expected future profits, which may be years away. When interest rates rise, a dollar received in the future is worth less in today''s terms, because safer alternatives pay more. Analysts reflect this by using a higher <strong>discount rate</strong>, which shrinks the value of distant profits:</p><p class="lesson-formula">Interest Rates &uarr; &rarr; Discount Rate &uarr; &rarr; Present Value of Future Earnings &darr;</p><p>This can produce <strong>valuation multiple compression</strong>, where the P/E that investors will pay falls, even if the underlying company''s revenue continues growing. The business may be doing fine while its share price drops, purely because the yardstick changed. For a student with a long career ahead, think of it like valuing a future salary: the higher the interest rate you could earn elsewhere, the less a promised payment ten years away is worth today. Conversely, when rates fall:</p><p class="lesson-formula">Interest Rates &darr; &rarr; Discount Rate &darr; &rarr; Valuation Multiples May Expand</p><p>Falling rates make future profits more valuable today, which can lift multiples even before earnings change.</p><h4>The Market Is Forward-Looking</h4><p>This concept is especially important for cyclical semiconductor companies. Suppose memory prices are still falling today, but investors begin expecting a sequence of improvements:</p><p class="lesson-formula">Inventory Normalisation &rarr; Production Cuts &rarr; Supply-Demand Balance &rarr; Memory Price Recovery</p><p>Stock prices may begin rising before reported earnings recover. By the time the numbers look good, the early investors have already moved and the price has risen. The opposite can happen near the top of a cycle, when profits look wonderful but buyers sense the shortage ending:</p><p class="lesson-formula">Current Earnings Strong + Future Expectations Deteriorating &rarr; Stock Price May Decline</p><p>Therefore: <strong>Stock Cycle &ne; Earnings Cycle.</strong> Stock prices generally attempt to reflect expectations about future earnings rather than only current financial performance. This is why a chip stock can seem to move in the opposite direction to the news in front of you, and why reading the news together with the stage of the cycle is so useful.</p><h4>Recent Headlines in Practice</h4><p>Valuation depends on what the market already expected, which is why good results can still lead to a fall. In March 2026, Micron''s CEO said it could supply only about half to two-thirds of key customers'' mid-term needs after earnings in which revenue nearly tripled, and the shares fell about 3 percent that day and 4.81 percent the next. In September 2025, Micron said its HBM supply for 2026 was nearly fully committed, with pricing agreements for most HBM3E volume, and the stock fell 3.02 percent the next day while the sector slipped only slightly. ASML''s October 2024 results showed third-quarter bookings of 2.6 billion euros against a 5.6 billion euro consensus, and the stock fell 6.42 percent the following session with the sector flat. In each case, the shares reacted to the gap between results and expectations rather than to the results themselves.</p><aside class="news-callout news-callout--down"><p class="news-callout-meta">Micron &middot; 19 Mar 2026</p><p class="news-callout-headline">Micron CEO says it can''t deliver enough memory to key customers after blowout earnings</p><p>Micron''s stock was up more than 350 percent in the prior year, so even revenue nearly tripling may have been judged against very high expectations. The decline was about double the sector''s, which suggests company-specific profit taking on top of a weak chip market.</p><p class="news-callout-move">Next day: stock -4.81% vs sector (SOXX) -2.26%</p><a class="news-callout-link" href="https://www.cnbc.com/2026/03/19/micron-falls-blockbuster-earnings-chips-ai.html" target="_blank" rel="noopener">Read the source</a></aside><div class="key-takeaway"><h5>Key takeaway</h5><p>Understanding semiconductor stocks requires connecting the entire analytical chain: End-Market Demand &rarr; Customer Orders &rarr; Inventory &rarr; Supply &amp; Pricing &rarr; Capacity Utilisation &rarr; Revenue &rarr; Gross Margin &rarr; Earnings &amp; Cash Flow &rarr; Future Expectations &rarr; Valuation &rarr; Stock Price. At every link, the market reacts to how reality compares with expectations, not to the news alone.</p></div>',
 5)
